window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0203", [{"word":"soluble","ipa_uk":"/ˈsɒljəbl/","ipa_us":"/ˈsɑːljəbl/","definition_zh":"可溶的；能溶解的；（难题、谜团）可解决的","definition_en":"able to be dissolved in a liquid, or able to be solved or explained","core_image":"一块方糖沉进温水，棱角一圈圈化开，最后杯底只剩一点甜","scene":"实验台上，学生把一小块白色晶体放进温水，晶体很快散开，杯底不留残渣。The white crystal proved highly soluble in warm water.","sceneCN":"这里 soluble 指物质能在液体里被溶解（第 1 个义项：能在液体中溶散）；句意为这块白色晶体在温水中极易溶解。图中可辨识物件：烧杯、温水、玻璃棒、晶体。","pos":[{"tag":"adj.","zh":"可溶的；能溶解的"},{"tag":"adj.","zh":"（问题、谜团）可解决的；可解释的"}],"collocations":[{"phrase":"soluble in water","zh":"溶于水"},{"phrase":"highly soluble","zh":"极易溶解的"},{"phrase":"soluble salt","zh":"可溶性盐"},{"phrase":"soluble fibre","zh":"可溶性膳食纤维"},{"phrase":"soluble fertiliser","zh":"可溶性肥料"},{"phrase":"soluble in alcohol","zh":"溶于酒精"}],"forms":[{"label":"原级","form":"soluble"},{"label":"比较级","form":"more soluble"},{"label":"最高级","form":"most soluble"},{"label":"名词（可溶性；溶解度）","form":"solubility"},{"label":"反义形容词","form":"insoluble"},{"label":"相关名词","form":"solution"}],"derivatives":[{"word":"solubility","pos":"n.","zh":"可溶性；溶解度"},{"word":"insoluble","pos":"adj.","zh":"不溶的；无法解决的"},{"word":"solute","pos":"n.","zh":"溶质；被溶解的物质"},{"word":"solution","pos":"n.","zh":"溶液；解答"},{"word":"solubly","pos":"adv.","zh":"可溶地（罕用）"}],"senses":[{"no":"01","title":"Able to dissolve in a liquid","titleCN":"能在液体中溶解","definition":"capable of being dissolved in a liquid and mixed into it so completely that no solid remains visible","definitionCN":"能在液体中溶解并完全混入其中，看不出固体残留","example":"Sugar is soluble in warm water.","exampleCN":"糖能溶于温水。","why":"soluble descends from Latin solvere 'to loosen', so the core picture is a solid whose particles are loosened apart by a liquid.","whyCN":"soluble 出自拉丁 solvere「松开」，核心画面是固体的微粒被液体拆散。"},{"no":"02","title":"Dissolving in a named solvent","titleCN":"对某种指定溶剂的溶解性","definition":"dissolving in the particular liquid that is named, rather than dissolving in any liquid at all","definitionCN":"能溶于被点名的那种液体，而不是泛指任何液体","example":"This resin is soluble in alcohol but not in water.","exampleCN":"这种树脂溶于酒精，却不溶于水。","why":"dissolving is always a relation between two things, so naming the solvent turns a bare ability into a measured pair.","whyCN":"溶解总是两样东西之间的关系，点明溶剂就把笼统的能力变成一对具体的搭配。"},{"no":"03","title":"A problem that can be solved","titleCN":"问题可以解决","definition":"able to be settled or worked out, said of a difficulty rather than of a substance","definitionCN":"指困难可以被处理、被解决，而非指物质","example":"The dispute proved soluble once both sides met.","exampleCN":"双方一见面，这场纠纷便显出可以化解。","why":"the Latin root also meant 'to untie a knot', and a difficulty that can be untied is one that can be solved.","whyCN":"拉丁词根还表示「解开绳结」，能解开的困难就是能解决的问题。"},{"no":"04","title":"A puzzle that can be explained","titleCN":"谜团可以解释清楚","definition":"capable of being explained or answered, said of a riddle, a question or a mystery","definitionCN":"指谜语、疑问或谜团能够被解释、被回答","example":"The riddle was soluble with a single clue.","exampleCN":"只要一条线索，这个谜语就能解开。","why":"a riddle is a knot tied in thought, so loosening it is the same gesture as solving it.","whyCN":"谜语是打在思路上的结，把它松开与把它解出是同一个动作。"},{"no":"05","title":"A difference that can be reconciled","titleCN":"分歧可以调和","definition":"able to be brought into agreement, said of views, claims or interests that are opposed","definitionCN":"指对立的看法、主张或利益能够被调和一致","example":"Their differences were soluble through a neutral arbiter.","exampleCN":"经一位中立的仲裁者，他们的分歧得以调和。","why":"two positions tied against each other can be untied, and that untieing is what dissolving means at root.","whyCN":"两个相互抵住的立场可以解开，而「解开」正是 dissolve 与 soluble 的本义。"},{"no":"06","title":"Able to be loosened, an old use","titleCN":"古义：绳结可以解开","definition":"able to be undone or loosened, said of a knot, a band or a fastening in older usage","definitionCN":"旧时用法中指绳结、束带或系缚能够被解开","example":"An old text might call a knot that can be undone soluble.","exampleCN":"旧文献可能把能解开的结称作 soluble。","why":"this is the oldest physical sense, and chemistry later kept only the image of parts coming apart.","whyCN":"这是最古老的实体义，化学后来只保留了「各部分散开」这一层。"},{"no":"07","title":"A fertiliser that dissolves in irrigation water","titleCN":"可随灌溉水施用的可溶性肥料","definition":"able to be dissolved in water so that it can be delivered through an irrigation system","definitionCN":"能溶于水，从而可经灌溉系统施入田间","example":"Farmers spread soluble fertiliser through the irrigation line.","exampleCN":"农民通过灌溉管道施用可溶性肥料。","why":"the technical sense narrows the first one: a fertiliser that dissolves in water can travel with the water.","whyCN":"这一技术义是把第一义收窄：能溶于水的肥料可以跟着水走。"},{"no":"08","title":"A feeling that might soften","titleCN":"抽象义：情绪或心结可以化解","definition":"able to be eased or softened, said figuratively of grief, anger or a hard feeling","definitionCN":"比喻指悲伤、怒气或难解的心绪能够被缓解、被冲淡","example":"Her grief was not soluble in a single conversation.","exampleCN":"一次谈话化不开她的悲伤。","why":"the abstract use treats a feeling as a substance that may or may not dissolve, which is the root image carried into the mind.","whyCN":"抽象用法把情绪当成可能溶、也可能不溶的物质，正是词根意象被带入心里。"}],"etymology":{"intro":{"en":"Soluble comes through Old French from Late Latin solubilis 'that may be dissolved', built on solvere 'to loosen, untie, dissolve' plus -bilis 'able to'. It is recorded in English from the fourteenth century. Dates are approximate.","cn":"soluble 经古法语来自晚期拉丁 solubilis「可被溶解的」，由 solvere「松开、解开、溶解」加 -bilis「能够」构成，十四世纪起在英语中有记录。年代均为约数。"},"items":[{"era":"LATIN SOLVERE","en":"Solvere meant 'to loosen, untie, release, dissolve'. It is built from se- 'apart' plus luere 'to loosen', and the same verb also gives solve, solution and dissolve.","cn":"solvere 意为「松开、解开、释放、溶解」，由 se-「分开」加 luere「松开」构成，同一动词也衍生出 solve、solution 与 dissolve。"},{"era":"LATIN SOLUTUS","en":"The past participle solutus 'loosened, dissolved' supplied the stem solut-, which appears in solution, solute and absolutus 'set free'.","cn":"过去分词 solutus「松开的、溶解的」提供了 solut- 词干，出现在 solution、solute 与 absolutus「释放」中。"},{"era":"LATE LATIN SOLUBILIS","en":"Late Latin solubilis added -bilis 'able to be' to the same stem, giving a word that could describe a substance as dissolvable.","cn":"晚期拉丁 solubilis 在同一词干后加 -bilis「能够被……」，用来形容某物质可被溶解。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French soluble passed into English in the fourteenth century, first for substances that melt or break up in water.","cn":"古法语 soluble 在十四世纪进入英语，最初用于在水中熔化或散开的物质。"},{"era":"CHEMISTRY","en":"From the seventeenth century chemists fixed the word to the relation between a substance and a named solvent, which produced stable phrases such as soluble in water and soluble in alcohol.","cn":"从十七世纪起，化学家把这个词固定为物质与指定溶剂之间的关系，于是出现「溶于水」「溶于酒精」这类稳定说法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin shape of luere is reconstructed as a root meaning 'to loosen', and the exact first English citation is not recorded; the reconstruction is offered as a form, not as a demonstrated word.","cn":"来源不确定（更深词源）：luere 在拉丁语之前的形态被重构为一个表示「松开」的词根，英语最早书证的确切年代没有记录；该形式是重构形式，并非已证实的词。"}]},"similar":{"note":{"en":"Group one holds words from the solvere stock, where prefixes change what is being loosened; group two holds words that sound like they measure dissolving but do not.","cn":"第一组是同出 solvere 词干的词，前缀改变「被松开」的对象；第二组是听起来像在描述溶解、实际并非如此的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"solve","ipa":"/sɒlv/","tag":"the general verb","definition":"The bare verb 'to loosen': to find the answer to a problem, with no chemical sense.","definitionCN":"最朴素的「松开」动词：找出问题的答案，不含化学义。"},{"word":"dissolve","ipa":"/dɪˈsɒlv/","tag":"the process, not the property","definition":"Dis- 'apart' plus solvere: the act by which a solid comes apart in a liquid; it names an event, while soluble names a capacity.","definitionCN":"dis-「分开」加 solvere：固体在液体中散开的过程，指事件；soluble 则指能力。"},{"word":"solution","ipa":"/səˈluːʃn/","tag":"the result","definition":"The mixture produced by dissolving, or the answer produced by solving; the noun sits after the action.","definitionCN":"溶解后得到的混合物，或解题得到的答案；名词位于动作之后。"},{"word":"absolute","ipa":"/ˈæbsəluːt/","tag":"same root, set free","definition":"Ab- 'away' plus solvere: loosened from every limit, hence complete and unrestricted; it shares the root but not the sense.","definitionCN":"ab-「离开」加 solvere：从一切限制中松开，故指完全、无条件；词根相同而词义不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"miscible","ipa":"/ˈmɪsəbl/","tag":"two liquids","definition":"Used of liquids that mix into each other, as water and alcohol; it does not describe a solid entering a liquid.","definitionCN":"用于彼此混合的液体，如水与酒精；不描述固体进入液体。"},{"word":"dissolvable","ipa":"/dɪˈsɒlvəbl/","tag":"process adjective","definition":"Able to be dissolved, closer to the action of dissolving than to a measured chemical property.","definitionCN":"能被溶解，偏向溶解动作，而非可测量的化学性质。"},{"word":"solvable","ipa":"/ˈsɒlvəbl/","tag":"problems only","definition":"Able to be solved; it never carries the chemical sense that soluble carries.","definitionCN":"能够被解决；从不带 soluble 那样的化学义。"},{"word":"permeable","ipa":"/ˈpɜːmiəbl/","tag":"lets fluid pass","definition":"Describes a material that a fluid can pass through, not a substance that enters a liquid and becomes part of it.","definitionCN":"描述流体可以穿过的材料，而非进入液体并成为其一部分的物质。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Solvere 'to loosen': the solid is loosened apart inside the liquid.","cn":"solvere「松开」：固体在液体内部被拆散。"},{"en":"The family runs solve, dissolve, solution, solute and solubility.","cn":"同族词包括 solve、dissolve、solution、solute 与 solubility。"},{"en":"Fixed phrases name the solvent: soluble in water, soluble in alcohol.","cn":"固定搭配会点明溶剂：溶于水、溶于酒精。"},{"en":"The opposite is insoluble, built with the negative prefix in-.","cn":"反义词是 insoluble，用否定前缀 in- 构成。"},{"en":"Chemistry pairs the word with the two everyday solids, salt and sugar.","cn":"化学常把这个词与盐、糖这两种日常固体配在一起。"}],"abstract":[{"en":"Picture a knot giving way under one fingertip.","cn":"想象一个结在一根手指下松开。"},{"en":"Picture a lump of sugar leaving no trace at the bottom of a glass.","cn":"想象一块糖在杯底不留一点痕迹。"},{"en":"Picture two people untying a rope they both still hold.","cn":"想象两个人解开一根两人都还握着的绳。"}]},"examples":[{"en":"The label warns that the powder is soluble in water and should be kept dry.","cn":"标签提醒这种粉末可溶于水，应保持干燥。"},{"en":"Because the salt is soluble, it disappears completely in hot water.","cn":"因为这种盐可溶，它在热水中会完全消失。"},{"en":"The committee treated the budget gap as a soluble problem rather than a permanent one.","cn":"委员会把预算缺口当成可解决的问题，而非永久难题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「so（如此）+ luble（松）」——如此松，一进水就散开：可溶的、可解决的","word":"soluble"},"root":"拉丁 solubilis「可被溶解的」= solvere（松开、解开、溶解）+ -bilis（能够）；solvere 由 se-（分开）+ luere（松开）构成，luere 的更早形态为重构形式。英语经古法语 soluble 进入。","sensesIntro":{"en":"Eight senses follow one loosening: a solid is loosened in a liquid, the solvent is named, a knot is untied, a problem and a riddle are untied in the mind, a quarrel is loosened, a fertiliser is dissolved into irrigation water, and a feeling is finally tested for whether it can dissolve.","cn":"八个义项跟着同一次「松开」：固体在液体里被拆散，溶剂被点名，绳结被解开，问题与谜语在脑中解开，争吵被化开，肥料溶进灌溉水，最后是一种情绪被检验能否化解。"},"semanticMap":{"core":{"en":"CORE IMAGE: a solid losing its edges inside a liquid until nothing visible is left.","cn":"核心意象：一块固体在液体里失去棱角，直到看不见残留。"},"chain":["SOLID COMES APART","SOLVENT NAMED","KNOT UNTIED","PROBLEM SOLVED","FERTILISER DISSOLVED","FEELING SOFTENED"],"branches":[{"senses":"01 · 02","en":"DISSOLVING: the bare capacity and the solvent-specific relation are two readings of the same test.","cn":"溶解：笼统的能力与指明溶剂的关系，是同一次检验的两种读法。"},{"senses":"03 · 04","en":"UNTIED IN THE MIND: a difficulty and a riddle are knots that come loose.","cn":"在脑中解开：困难与谜语都是可以松开的结。"},{"senses":"05 · 06","en":"LOOSENED BONDS: opposed claims and a physical knot share the oldest image.","cn":"松开的束缚：对立的主张与实在的绳结共享最古老的意象。"},{"senses":"07","en":"DISSOLVED INTO WATER: the farm sense narrows dissolving to a fertiliser carried by irrigation.","cn":"溶进水：农业义把溶解收窄为随灌溉水走的肥料。"},{"senses":"08","en":"SOFTENED FEELING: grief and anger are treated as substances that may or may not dissolve.","cn":"软化的情绪：悲伤与怒气被当作可能溶、也可能不溶的物质。"}]},"affixes":{"intro":{"en":"Soluble is a Latin adjective built from a prefix, a verb root and a suffix, and every piece also builds other English words.","cn":"soluble 是一个拉丁形容词，由前缀、动词词根与后缀构成，每一部分也都参与构成其他英语词。"},"latinIntro":{"en":"Latin solvere gives solve, dissolve, solution and absolute; -bilis marks what can be done, and it survives as -able and -ible in English.","cn":"拉丁 solvere 衍生 solve、dissolve、solution 与 absolute；-bilis 表示「能够被……」，在英语中留下 -able 与 -ible。"},"items":[{"word":"se-","structure":"se- (Latin prefix, 'apart')","meaning":"apart; away","meaningCN":"分开；离开","example":"The prefix supplies the idea of separation.","exampleCN":"这个前缀提供「分开」的意思。"},{"word":"luere","structure":"luere (Latin verb, 'to loosen')","meaning":"to loosen; to release","meaningCN":"松开；释放","example":"The root carries the loosening itself.","exampleCN":"这个词根承载「松开」这个动作。"},{"word":"solvere","structure":"se- + luere","meaning":"to loosen, untie, dissolve","meaningCN":"松开；解开；溶解","example":"The verb covers knots and salts alike.","exampleCN":"这个动词同时覆盖绳结与盐类。"},{"word":"solubilis","structure":"solvere + -bilis (able to be)","meaning":"able to be dissolved","meaningCN":"能够被溶解的","example":"The suffix turns the act into a capacity.","exampleCN":"这个后缀把动作变成能力。"},{"word":"soluble","structure":"solubilis -> soluble through French","meaning":"dissolvable; solvable","meaningCN":"可溶的；可解决的","example":"Sugar is soluble in warm water.","exampleCN":"糖能溶于温水。"},{"word":"solubility","structure":"soluble + -ity (state or quality)","meaning":"the quality of being soluble","meaningCN":"可溶性","example":"Solubility rises with temperature.","exampleCN":"溶解度随温度升高。"},{"word":"solution","structure":"solvere + -tion (action or result)","meaning":"a dissolved mixture; an answer","meaningCN":"溶液；解答","example":"The solution cleared after stirring.","exampleCN":"搅拌后溶液变清了。"},{"word":"solute","structure":"solutus (past participle used as a noun)","meaning":"the substance that is dissolved","meaningCN":"被溶解的物质","example":"The solute dissolved within a minute.","exampleCN":"溶质一分钟内就溶解了。"},{"word":"dissolve","structure":"dis- + solvere","meaning":"to come apart in a liquid","meaningCN":"在液体中散开、溶解","example":"The tablet dissolves in half a glass of water.","exampleCN":"这片药在半杯水里溶解。"},{"word":"insoluble","structure":"in- (not) + soluble","meaning":"not able to be dissolved","meaningCN":"不能溶解的","example":"The oil is insoluble in water.","exampleCN":"油不溶于水。"}],"latinEntries":[{"word":"solvere","structure":"solvere, solvi, solutum (verb, third conjugation)","meaning":"to loosen, untie, dissolve","meaningCN":"松开；解开；溶解"},{"word":"solubilis","structure":"solubilis, solubile (adjective, third declension)","meaning":"that may be dissolved","meaningCN":"可被溶解的"},{"word":"solutus","structure":"solutus, soluta, solutum (past participle used as adjective)","meaning":"loosened, dissolved","meaningCN":"松开的；溶解的"},{"word":"solutio","structure":"solutio, solutionis (f., third declension)","meaning":"a loosening, a solution","meaningCN":"松开；溶解；溶液"}]}},{"word":"insoluble","ipa_uk":"/ɪnˈsɒljəbl/","ipa_us":"/ɪnˈsɑːljəbl/","definition_zh":"不溶的；不能溶解的；（问题、矛盾）无法解决的","definition_en":"not able to be dissolved in a liquid, or not able to be solved or settled","core_image":"一勺细粉落进水里，沉到底部，搅了很久仍是清清楚楚的一层","scene":"水槽里，工人把一袋白色粉末倒进清水，粉末沉到槽底，怎么搅也不散开。The powder stayed insoluble no matter how long the water was stirred.","sceneCN":"这里 insoluble 指物质不能在液体中溶解（第 1 个义项：不能溶于液体）；句意为无论搅多久，这种粉末都不溶解。图中可辨识物件：水槽、白色粉末、搅拌棒、沉底的粉层。","pos":[{"tag":"adj.","zh":"不溶的；不能溶解的"},{"tag":"adj.","zh":"（问题、矛盾）无法解决的；不能化解的"}],"collocations":[{"phrase":"insoluble in water","zh":"不溶于水"},{"phrase":"insoluble residue","zh":"不溶残渣"},{"phrase":"insoluble problem","zh":"无法解决的问题"},{"phrase":"insoluble salt","zh":"难溶盐"},{"phrase":"insoluble conflict","zh":"无法调和的冲突"},{"phrase":"insoluble fibre","zh":"不可溶性膳食纤维"}],"forms":[{"label":"原级","form":"insoluble"},{"label":"比较级","form":"more insoluble"},{"label":"最高级","form":"most insoluble"},{"label":"名词（不可溶性）","form":"insolubility"},{"label":"肯定形式","form":"soluble"},{"label":"近义形容词（问题义）","form":"unsolvable"}],"derivatives":[{"word":"solubility","pos":"n.","zh":"可溶性；溶解度"},{"word":"insolubility","pos":"n.","zh":"不可溶性"},{"word":"solute","pos":"n.","zh":"溶质"},{"word":"solution","pos":"n.","zh":"溶液；解答"},{"word":"soluble","pos":"adj.","zh":"可溶的；可解决的"}],"senses":[{"no":"01","title":"Will not dissolve in a liquid","titleCN":"不能在液体中溶解","definition":"not capable of being dissolved in a liquid, so that the substance stays separate and visible","definitionCN":"不能溶解于液体，物质保持分离、看得见","example":"The oil remained insoluble in water and floated on top.","exampleCN":"油不溶于水，浮在上面。","why":"the negative prefix in- reverses soluble, so the word denies the loosening of particles that soluble describes.","whyCN":"否定前缀 in- 反转 soluble，这个词否认了 soluble 所描述的微粒散开。"},{"no":"02","title":"Insoluble in a named solvent","titleCN":"对某种指定溶剂不溶","definition":"failing to dissolve in the particular liquid that is named, even though it may dissolve elsewhere","definitionCN":"在被点名的液体中不溶解，尽管在别处可能溶解","example":"This pigment is insoluble in alcohol but soluble in acetone.","exampleCN":"这种颜料不溶于酒精，却溶于丙酮。","why":"since dissolving is a relation between two substances, a refusal is also a relation and needs the solvent named.","whyCN":"既然溶解是两物之间的关系，拒绝溶解也是一种关系，同样需要点明溶剂。"},{"no":"03","title":"A solid that stays as residue","titleCN":"沉淀下来的不溶固体或残渣","definition":"remaining as a solid residue after a liquid has been filtered or poured off","definitionCN":"液体被滤过或倒掉后仍留成固体残渣","example":"The insoluble residue was collected on the filter paper.","exampleCN":"不溶残渣被收集在滤纸上。","why":"what cannot dissolve must end up somewhere, and in the laboratory it ends up as the residue on the paper.","whyCN":"不能溶解的东西总得有个去处，在实验室里它就成了纸上的残渣。"},{"no":"04","title":"A problem with no apparent answer","titleCN":"看似无解的问题","definition":"unable to be solved or settled, said of a difficulty that resists every proposed remedy","definitionCN":"无法解决或了结，指抵挡一切方案的那种困难","example":"The housing shortage seemed insoluble without new land.","exampleCN":"没有新土地，住房短缺似乎无解。","why":"the mind unties problems as a liquid unties salts, so a problem that will not come apart is called insoluble.","whyCN":"头脑解问题正如液体解盐，解不开的问题就被叫作 insoluble。"},{"no":"05","title":"A dispute that cannot be reconciled","titleCN":"无法调和的争端","definition":"unable to be brought into agreement, said of opposed claims or interests","definitionCN":"无法使之一致，指对立的主张或利益","example":"Their claims were insoluble because both demanded the same field.","exampleCN":"两方都索要同一块地，他们的主张无法调和。","why":"two positions that cannot be untied remain locked, which is exactly the image behind the word.","whyCN":"两个解不开的立场会一直互锁，这正是这个词背后的画面。"},{"no":"06","title":"A mystery that cannot be explained","titleCN":"无法解释的谜团","definition":"unable to be explained or accounted for, said of a disappearance, a riddle or an event","definitionCN":"无法被解释或说明，指失踪、谜语或某个事件","example":"The disappearance remained insoluble for decades.","exampleCN":"那起失踪案数十年没有答案。","why":"a riddle is a knot in thought; if no clue loosens it, the knot stays insoluble.","whyCN":"谜语是思路上的结，若没有线索能松开它，这个结就始终解不开。"},{"no":"07","title":"A debt that cannot be discharged","titleCN":"无法清偿的债务","definition":"unable to be paid off or discharged, used of an obligation that no arrangement can clear","definitionCN":"无法还清或了结，用于任何安排都清不掉的义务","example":"The old debt proved insoluble and was written off.","exampleCN":"那笔旧债无法清偿，最终被注销。","why":"a debt is a bond, and to discharge it is to untie it; a bond that cannot be untied is insoluble in the older legal sense.","whyCN":"债务是一种束缚，清偿就是解开；解不开的束缚在旧日法律意义上就是 insoluble。"},{"no":"08","title":"A knot that cannot be untied, an old use","titleCN":"古义：绳结解不开","definition":"unable to be undone, said of a knot, a band or a fastening in older usage","definitionCN":"旧时用法中指绳结、束带或系缚无法解开","example":"The insoluble knot had to be cut with a knife.","exampleCN":"那个死结只能用刀割开。","why":"the physical knot is the oldest sense, and every later use keeps the same image of a bond that will not loosen.","whyCN":"实体的绳结是最古老的义项，此后每个用法都保留「束缚不肯松开」这一意象。"}],"etymology":{"intro":{"en":"Insoluble joins the negative prefix in- 'not' to soluble, from Latin insolubilis 'that cannot be loosened or dissolved'. The word is recorded in English from the fourteenth century, with the figurative sense of an unanswerable problem following in the sixteenth. Dates are approximate.","cn":"insoluble 由否定前缀 in-「不」加 soluble 构成，来自拉丁 insolubilis「不能松开或溶解的」。英语自十四世纪有记录，十六世纪出现「问题无解」的比喻义。年代均为约数。"},"items":[{"era":"LATIN SOLVERE","en":"Solvere 'to loosen, untie, dissolve' is built from se- 'apart' and luere 'to loosen'; the same verb yields solve, solution and dissolve.","cn":"solvere「松开、解开、溶解」由 se-「分开」与 luere「松开」构成，同一动词衍生 solve、solution 与 dissolve。"},{"era":"LATIN INSOLUBILIS","en":"In- 'not' plus solubilis 'able to be dissolved' produced insolubilis, used of knots that would not come undone as well as of substances that would not dissolve.","cn":"in-「不」加 solubilis「可被溶解的」构成 insolubilis，既用于解不开的绳结，也用于不能溶解的物质。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French insoluble brought the word into English in the fourteenth century, at first almost entirely in the physical sense.","cn":"古法语 insoluble 在十四世纪把这个词带入英语，最初几乎全是实体义。"},{"era":"SCIENTIFIC USE","en":"Seventeenth-century chemistry made the word a standard label for solids that a solvent leaves untouched, and the laboratory phrase insoluble residue dates from this period.","cn":"十七世纪的化学把这个词变成溶剂动不了的固体的标准标签，实验室里把这类残渣称为「不溶残渣」，这一说法即出自这一时期。"},{"era":"FIGURATIVE USE","en":"By the sixteenth century insoluble was applied to problems and disputes that no remedy could settle, borrowing the chemical image for the mind.","cn":"到十六世纪，insoluble 被用于任何办法都了结不了的问题与争端，把化学意象借给了头脑。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first citation): the pre-Latin form of luere is a reconstruction, and no exact date is recorded for the first English use of the figurative sense.","cn":"来源不确定（更深词源与首见书证）：luere 在拉丁语之前的形式属于重构，比喻义在英语中最早使用的确切年代没有记录。"}]},"similar":{"note":{"en":"Group one holds the negative forms that look interchangeable but answer different questions; group two holds words for things that resist solution or passage.","cn":"第一组是看起来可互换、实际回答不同问题的否定形式；第二组是表示抗拒溶解或通过之物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"soluble","ipa":"/ˈsɒljəbl/","tag":"the positive pair","definition":"The exact opposite in the chemical sense; it also carries the sense of a solvable problem, which insoluble mirrors.","definitionCN":"化学义上完全相反；它也带「问题可解」义，insoluble 与之对应。"},{"word":"unsolvable","ipa":"/ˌʌnˈsɒlvəbl/","tag":"problems only","definition":"A plain English negative used only for problems and puzzles, with no chemical sense at all.","definitionCN":"纯英语否定形式，只用于问题与谜题，完全没有化学义。"},{"word":"insolvable","ipa":"/ɪnˈsɒlvəbl/","tag":"different word, problems only","definition":"A separate adjective meaning 'not solvable', built on solvable rather than on soluble; it never describes a substance.","definitionCN":"另一个形容词，意为「不可解」，由 solvable 而非 soluble 构成；从不形容物质。"},{"word":"indissoluble","ipa":"/ˌɪndɪˈsɒljəbl/","tag":"bonds that hold","definition":"Built on dissolve: it describes ties, vows or unions that cannot be broken, not salts that will not dissolve.","definitionCN":"由 dissolve 构成：描述无法解除的联系、誓言或结合，而非不溶解的盐。"}]},{"heading":"NEAR MEANING","entries":[{"word":"intractable","ipa":"/ɪnˈtræktəbl/","tag":"hard to manage","definition":"Describes a problem or person that is hard to manage, but not necessarily impossible; insoluble is stronger.","definitionCN":"形容难以处理的问题或人，但未必不可能；insoluble 语气更强。"},{"word":"impermeable","ipa":"/ɪmˈpɜːmiəbl/","tag":"no passage","definition":"Describes a barrier that fluid cannot pass through; it is about passage, not about dissolving.","definitionCN":"形容流体无法穿过的屏障；说的是通过，不是溶解。"},{"word":"unresolvable","ipa":"/ˌʌnrɪˈzɒlvəbl/","tag":"no resolution","definition":"Used of conflicts or doubts that cannot be resolved, close to the dispute sense of insoluble.","definitionCN":"用于无法化解的冲突或疑虑，接近 insoluble 的争端义。"},{"word":"stubborn","ipa":"/ˈstʌbən/","tag":"plain everyday word","definition":"An everyday adjective for something that will not give way, used of people, stains and problems alike.","definitionCN":"日常形容词，指不肯让步之物，可用于人、污渍与问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"In- 'not' on top of soluble: the loosening is denied.","cn":"in-「不」加在 soluble 之上：拒绝松开。"},{"en":"The pair runs soluble and insoluble, solubility and insolubility.","cn":"成对出现的是 soluble 与 insoluble、solubility 与 insolubility。"},{"en":"Laboratory phrases mark the solid sense: insoluble residue, insoluble salt.","cn":"实验室说法标出实体义：不溶残渣、难溶盐。"},{"en":"Everyday phrases mark the figurative sense: an insoluble problem, an insoluble conflict.","cn":"日常说法标出比喻义：无解的问题、无法调和的冲突。"},{"en":"Do not confuse it with insolvable, which is built on solvable and applies only to questions.","cn":"不要与 insolvable 混同，后者由 solvable 构成，只用于问题。"}],"abstract":[{"en":"Picture powder that keeps its shape on the bottom of a glass.","cn":"想象粉末在杯底始终保持着原来的形状。"},{"en":"Picture a knot pulled tight until no finger can find a loop.","cn":"想象一个结被拉到最紧，手指再也找不到可以插入的环。"},{"en":"Picture two negotiators holding the same map and refusing to move their pens.","cn":"想象两位谈判者拿着同一张地图，谁也不肯挪笔。"}]},"examples":[{"en":"Calcium carbonate is insoluble in water but reacts with acid.","cn":"碳酸钙不溶于水，但会与酸反应。"},{"en":"The report called the shortage of trained nurses an insoluble problem.","cn":"报告称训练有素的护士短缺是一个无法解决的问题。"},{"en":"The two communities held insoluble claims to the same water source.","cn":"两个社区对同一水源的主张无法调和。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（不）+ soluble（可溶）」——不溶的；再引申为「解不开的」","word":"insoluble"},"root":"拉丁 insolubilis「不能松开、不能溶解的」= in-（不）+ solubilis（可被溶解的）；solubilis 出自 solvere（松开、解开），由 se-（分开）+ luere（松开）构成。英语经古法语进入。","sensesIntro":{"en":"Eight senses follow one refusal to loosen: powder stays on the bottom, a named solvent gets no answer, residue remains on the paper, a problem and a dispute will not untie, a mystery keeps its secret, a debt cannot be discharged, and finally an old knot has to be cut.","cn":"八个义项跟着同一次「拒绝松开」：粉末留在杯底，指定溶剂得不到回应，残渣留在滤纸上，问题与争端解不开，谜团守着秘密，债务清不掉，最后是一个旧绳结只能用刀割断。"},"semanticMap":{"core":{"en":"CORE IMAGE: a solid that stays whole on the bottom while the liquid moves around it.","cn":"核心意象：固体完完整整留在底部，液体在它周围流动。"},"chain":["WILL NOT DISSOLVE","SOLVENT REFUSED","RESIDUE LEFT","PROBLEM UNSOLVED","DEBT UNDISCHARGED","KNOT UNCUT"],"branches":[{"senses":"01 · 02","en":"REFUSED DISSOLVING: the bare denial and the solvent-specific denial are one refusal seen twice.","cn":"拒绝溶解：笼统的否定与对指定溶剂的否定，是同一次拒绝的两种看法。"},{"senses":"03","en":"RESIDUE: what will not dissolve has to remain somewhere, and the laboratory makes that place visible.","cn":"残渣：不溶之物总得留在某处，实验室让这个去处看得见。"},{"senses":"04 · 05","en":"LOCKED IN THE MIND: a problem and a dispute are knots no remedy can loosen.","cn":"锁在脑中：问题与争端都是任何办法也松不开的结。"},{"senses":"06 · 07","en":"UNEXPLAINED AND UNPAID: a mystery keeps its secret and a debt keeps its bond.","cn":"无法解释与无法清偿：谜团守着秘密，债务守着束缚。"},{"senses":"08","en":"THE OLDEST KNOT: the physical knot that must be cut is the root image of every later sense.","cn":"最古老的结：只能用刀割断的实体绳结，是此后一切义项的根源意象。"}]},"affixes":{"intro":{"en":"Insoluble is a negative built on a Latin adjective, and both the negative prefix and the Latin base also build other common words.","cn":"insoluble 是在一个拉丁形容词上构成的否定词，否定前缀与拉丁词基都还构成其他常用词。"},"latinIntro":{"en":"The prefix in- 'not' appears as il-, im- and ir- before other consonants; Latin solvere 'to loosen' supplies solution, dissolve and absolute.","cn":"否定前缀 in- 在其他辅音前会变成 il-、im- 与 ir-；拉丁 solvere「松开」提供 solution、dissolve 与 absolute。"},"items":[{"word":"in-","structure":"in- (Latin negative prefix, 'not')","meaning":"not","meaningCN":"不；非","example":"The prefix turns the positive adjective into its denial.","exampleCN":"这个前缀把肯定形容词变成它的否定。"},{"word":"il-","structure":"il- (form of in- before l)","meaning":"not, before a word beginning with l","meaningCN":"不（用于以 l 开头的词前）","example":"The same prefix appears as il- in illegal.","exampleCN":"同一前缀在 illegal 中写作 il-。"},{"word":"im-","structure":"im- (form of in- before m, b, p)","meaning":"not, before a labial consonant","meaningCN":"不（用于唇音辅音前）","example":"The variant appears in impermeable.","exampleCN":"这一变体出现在 impermeable 中。"},{"word":"solvere","structure":"solvere (Latin verb, third conjugation)","meaning":"to loosen, untie, dissolve","meaningCN":"松开；解开；溶解","example":"The verb supplies the whole family.","exampleCN":"这个动词提供整个词族。"},{"word":"solubilis","structure":"solvere + -bilis (able to be)","meaning":"able to be dissolved","meaningCN":"能够被溶解的","example":"The base adjective names a capacity.","exampleCN":"基础形容词命名的是一种能力。"},{"word":"insoluble","structure":"in- + soluble","meaning":"not able to be dissolved","meaningCN":"不能溶解的","example":"The powder is insoluble in water.","exampleCN":"这种粉末不溶于水。"},{"word":"insolubility","structure":"insoluble + -ity (state)","meaning":"the state of not dissolving","meaningCN":"不可溶的状态","example":"Its insolubility limits its use in drinks.","exampleCN":"它的不可溶性限制了它在饮料中的用途。"},{"word":"soluble","structure":"solubilis -> soluble","meaning":"able to be dissolved","meaningCN":"可溶的","example":"Sugar is soluble in water.","exampleCN":"糖溶于水。"},{"word":"solution","structure":"solvere + -tion (result)","meaning":"a dissolved mixture","meaningCN":"溶液","example":"The solution was filtered twice.","exampleCN":"这溶液被过滤了两次。"},{"word":"dissolve","structure":"dis- + solvere","meaning":"to break apart in a liquid","meaningCN":"在液体中散开、溶解","example":"Salt dissolves quickly in hot water.","exampleCN":"盐在热水中很快溶解。"}],"latinEntries":[{"word":"solvere","structure":"solvere, solvi, solutum (verb, third conjugation)","meaning":"to loosen, untie, dissolve","meaningCN":"松开；解开；溶解"},{"word":"solubilis","structure":"solubilis, solubile (adjective, third declension)","meaning":"that may be dissolved","meaningCN":"可被溶解的"},{"word":"insolubilis","structure":"insolubilis, insolubile (adjective, third declension)","meaning":"that cannot be loosened or dissolved","meaningCN":"不能松开或溶解的"},{"word":"insolubilitas","structure":"insolubilitas, insolubilitatis (f., third declension)","meaning":"the quality of not being dissolvable","meaningCN":"不可溶性"}]}},{"word":"solubility","ipa_uk":"/ˌsɒljəˈbɪləti/","ipa_us":"/ˌsɑːljəˈbɪləti/","definition_zh":"可溶性；溶解度；（问题的）可解决性","definition_en":"the ability of a substance to dissolve in a liquid, or the amount of it that a given amount of liquid can take","core_image":"一支温度计插在烧杯里，杯中的糖随水温上升一点点消失得更多","scene":"实验记录本摊在桌上，学生对着一排烧杯逐次升温，记下每杯里糖消失的数量。The solubility of sugar rises steadily with temperature.","sceneCN":"这里 solubility 指某物质在特定溶剂中能被溶解的能力与数量（第 1 个义项：溶解的能力）；句意为糖的溶解度随温度稳定上升。图中可辨识物件：烧杯、温度计、记录本、糖。","pos":[{"tag":"n.","zh":"可溶性；溶解度（不可数）"},{"tag":"n.","zh":"（问题的）可解决性；可解程度"}],"collocations":[{"phrase":"high solubility","zh":"高溶解度"},{"phrase":"low solubility","zh":"低溶解度"},{"phrase":"solubility in water","zh":"在水中的溶解度"},{"phrase":"solubility limit","zh":"溶解度极限"},{"phrase":"temperature-dependent solubility","zh":"随温度变化的溶解度"},{"phrase":"the solubility of a salt","zh":"某种盐的溶解度"}],"forms":[{"label":"不可数名词","form":"solubility"},{"label":"复数（不同物质的溶解度）","form":"solubilities"},{"label":"形容词","form":"soluble"},{"label":"否定名词","form":"insolubility"},{"label":"相关名词","form":"solute"},{"label":"相关名词","form":"solution"}],"derivatives":[{"word":"soluble","pos":"adj.","zh":"可溶的；可解决的"},{"word":"insoluble","pos":"adj.","zh":"不溶的；无法解决的"},{"word":"insolubility","pos":"n.","zh":"不可溶性"},{"word":"solute","pos":"n.","zh":"溶质"},{"word":"solution","pos":"n.","zh":"溶液；解答"}],"senses":[{"no":"01","title":"The ability of a substance to dissolve","titleCN":"物质能被溶解的能力","definition":"the capacity of a solid or gas to enter a liquid and become part of it","definitionCN":"固体或气体进入液体并成为其中一部分的能力","example":"The solubility of sugar rises sharply with temperature.","exampleCN":"糖的可溶性随温度急剧上升。","why":"the noun adds -ity 'state or quality' to soluble, so it names the quality rather than the substance that has it.","whyCN":"这个名词在 soluble 后加 -ity「状态、性质」，命名的是性质，而不是拥有性质的物质。"},{"no":"02","title":"The measured amount that dissolves","titleCN":"可测定的溶解数量（溶解度）","definition":"the quantity of a substance that a fixed amount of solvent can take at a given temperature","definitionCN":"在一定温度下，固定量溶剂所能容纳的物质量","example":"The solubility of table salt is about thirty-six grams per hundred grams of water.","exampleCN":"食盐的溶解度约为每一百克水三十六克。","why":"once chemists weigh the substance and the solvent, the quality becomes a number, and the same noun covers both.","whyCN":"化学家一旦称量溶质与溶剂，性质就变成数字，同一个名词覆盖两者。"},{"no":"03","title":"A relation to a named solvent","titleCN":"对指定溶剂的溶解性","definition":"the degree to which a substance dissolves in the particular liquid named","definitionCN":"某物质在被点名的液体中溶解的程度","example":"Its solubility in alcohol makes it useful for tinctures.","exampleCN":"它在酒精中的溶解性使它适用于酊剂。","why":"a capacity is always a capacity in something, so the noun regularly takes the name of the solvent.","whyCN":"能力总是对某物而言的能力，因此这个名词常带溶剂名。"},{"no":"04","title":"The property studied in pharmacy","titleCN":"药物学关注的溶解性质","definition":"the extent to which a drug dissolves in body fluids, which governs how quickly it reaches the blood","definitionCN":"药物在体液中溶解的程度，决定它多快进入血液","example":"The drug's low solubility limits how much reaches the blood.","exampleCN":"这种药溶解度低，限制了进入血液的药量。","why":"pharmacy applies the chemical measure to a tablet in the body, so the quality becomes a predictor of effect.","whyCN":"药物学把化学量度用到了体内的药片上，于是这一性质成了药效的预测指标。"},{"no":"05","title":"The quality of a problem being solvable","titleCN":"问题可以被解决的程度","definition":"the degree to which a difficulty or dispute admits a workable answer","definitionCN":"困难或争端能获得可行答案的程度","example":"The solubility of the dispute depended on a neutral chair.","exampleCN":"这场争端能否化解，取决于一位中立的会议主持。","why":"the figurative sense transfers the chemical measure to problems: some loosen easily and some hardly at all.","whyCN":"比喻义把化学量度搬到问题上：有些容易松开，有些几乎松不开。"},{"no":"06","title":"How far a plan can be made to work","titleCN":"方案可以被化解、被推动的程度","definition":"the extent to which a plan, difficulty or objection can be worked through rather than left standing","definitionCN":"某个方案、困难或反对意见能被处理掉而非一直搁着的程度","example":"The plan's solubility was doubted by every engineer on the board.","exampleCN":"董事会的每位工程师都怀疑这个方案有解。","why":"planning treats obstacles as soluble matter, so the noun measures how much of the obstacle can be absorbed.","whyCN":"规划把障碍当作可溶之物，这个名词便衡量障碍能被吸收多少。"},{"no":"07","title":"The property of an equation being solvable","titleCN":"方程可解的性质","definition":"the property of an equation or logical problem that allows an answer to be found by rule","definitionCN":"方程或逻辑问题能按规则求出答案的性质","example":"The solubility of the equation was proved in a single page.","exampleCN":"这个方程的可解性用一页纸就被证明了。","why":"mathematics borrowed the language of loosening for equations long before chemistry standardized the noun.","whyCN":"数学早在化学规范这个名词之前，就借用了「松开」的说法来讲方程。"},{"no":"08","title":"How far a hard feeling can soften","titleCN":"抽象义：难解心绪能被化解的程度","definition":"the degree to which grief, anger or resentment can be eased over time","definitionCN":"悲伤、怒气或怨恨随时间能被缓解的程度","example":"The solubility of grief is not a matter of weeks.","exampleCN":"悲伤能否化开，不是几周的事。","why":"the abstract use asks how much of a feeling a situation can absorb, which is the chemical image applied inward.","whyCN":"抽象用法追问一种处境能吸收多少情绪，正是化学意象转向内心。"}],"etymology":{"intro":{"en":"Solubility is soluble plus -ity 'state or quality', modelled on Late Latin solubilitas. The English word is recorded from the seventeenth century, when chemistry began measuring how much of a substance a solvent could take. Dates are approximate.","cn":"solubility 是 soluble 加 -ity「状态、性质」构成，仿晚期拉丁 solubilitas。英语自十七世纪有记录，正值化学开始测量溶剂能容纳多少物质。年代均为约数。"},"items":[{"era":"LATIN SOLVERE","en":"Solvere 'to loosen, untie, dissolve' joins se- 'apart' to luere 'to loosen'; its participle solutus gives the stem behind solution and solute.","cn":"solvere「松开、解开、溶解」由 se-「分开」加 luere「松开」构成；其分词 solutus 提供 solution 与 solute 的词干。"},{"era":"LATIN SOLUBILIS","en":"Solubilis 'able to be dissolved' added -bilis to the same stem, and Late Latin formed the abstract noun solubilitas from it.","cn":"solubilis「可被溶解的」在同一词干后加 -bilis，晚期拉丁由此构成抽象名词 solubilitas。"},{"era":"ENGLISH NOUN","en":"English built solubility on soluble with -ity in the seventeenth century, at first for the tendency of a body to dissolve.","cn":"英语在十七世纪用 -ity 在 soluble 上构成 solubility，最初指物体溶解的倾向。"},{"era":"MEASUREMENT","en":"As chemists fixed temperature and weighed both solvent and solute, solubility came to name a measurable quantity as well as a quality.","cn":"当化学家固定温度并称量溶剂与溶质后，solubility 既指性质，也指可测量的数量。"},{"era":"FIGURATIVE USE","en":"The word has long been applied to problems and disputes, where it measures how far a difficulty can be loosened rather than how much solid a liquid can take.","cn":"这个词长期也被用于问题与争端，那里衡量的是困难能被松开多少，而非液体能容纳多少固体。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin form of luere is reconstructed, and the earliest English citation for the figurative sense is not precisely dated.","cn":"来源不确定（更深词源）：luere 在拉丁语之前的形式属于重构；比喻义最早英语书证没有确切年代。"}]},"similar":{"note":{"en":"Group one holds the chemical family that is constantly swapped in speech; group two holds measured properties that look similar on a data sheet.","cn":"第一组是口语中常被互换的化学词族；第二组是在数据表上看起来相似的可测性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"soluble","ipa":"/ˈsɒljəbl/","tag":"the adjective, not the measure","definition":"The adjective says that something can dissolve; the noun says how much or how readily it does so.","definitionCN":"形容词说某物能溶解；名词说它溶多少、溶得多容易。"},{"word":"solute","ipa":"/ˈsəʊljuːt/","tag":"the substance itself","definition":"The solid or gas that is dissolved; it is the object measured, not the measurement.","definitionCN":"被溶解的固体或气体，是被测量的对象，不是测量本身。"},{"word":"solution","ipa":"/səˈluːʃn/","tag":"the mixture","definition":"The liquid mixture that results from dissolving; a solution has a solubility, but is not one.","definitionCN":"溶解后得到的液体混合物；溶液有溶解度，但它本身不是溶解度。"},{"word":"solvable","ipa":"/ˈsɒlvəbl/","tag":"problems only","definition":"An adjective for problems that can be solved; it looks close but has no chemical use.","definitionCN":"形容可以解决的问题；形近，但无化学用法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"miscibility","ipa":"/ˌmɪsəˈbɪləti/","tag":"liquid with liquid","definition":"The ability of two liquids to mix, as water and ethanol; solubility is normally about a solid or gas in a liquid.","definitionCN":"两种液体相互混合的能力，如水与乙醇；solubility 通常指固体或气体溶于液体。"},{"word":"concentration","ipa":"/ˌkɒnsənˈtreɪʃn/","tag":"how much is already in the liquid","definition":"The amount of solute present in a given volume; solubility is the ceiling that concentration can reach.","definitionCN":"给定体积中已含溶质的量；solubility 是浓度能达到的上限。"},{"word":"permeability","ipa":"/ˌpɜːmiəˈbɪləti/","tag":"flow through a material","definition":"The ease with which a fluid passes through a solid; it concerns passage, not dissolving.","definitionCN":"流体穿过固体的容易程度；说的是通过，不是溶解。"},{"word":"viscosity","ipa":"/vɪˈskɒsəti/","tag":"resistance to flow","definition":"The thickness of a liquid; a syrup can have low solubility and high viscosity at the same time.","definitionCN":"液体的黏稠程度；糖浆可以同时溶解度低而黏度高。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Soluble plus -ity: the ending turns the ability into a name.","cn":"soluble 加 -ity：这个结尾把能力变成名称。"},{"en":"The family runs soluble, solubility, insoluble, insolubility, solute, solution.","cn":"同族词包括 soluble、solubility、insoluble、insolubility、solute、solution。"},{"en":"Data phrases mark the measured sense: high solubility, low solubility, solubility limit.","cn":"数据说法标出测量义：高溶解度、低溶解度、溶解度极限。"},{"en":"The solvent follows the noun: solubility in water, solubility in alcohol.","cn":"名词后面跟着溶剂：在水中的溶解度、在酒精中的溶解度。"},{"en":"Chemistry sets solubility against concentration, the ceiling against the current level.","cn":"化学把溶解度与浓度对立：上限对当前水平。"}],"abstract":[{"en":"Picture a thermometer climbing while more and more sugar disappears.","cn":"想象温度计一路上升，越来越多的糖随之消失。"},{"en":"Picture a glass already full of dissolved sweet, refusing one more spoon.","cn":"想象一杯已经溶满甜味的液体，再多一勺也装不下。"},{"en":"Picture a hard quarrel that loosens a little each time the two sides meet.","cn":"想象一场僵持的争吵，每次双方见面就松开一点。"}]},"examples":[{"en":"The lab reports the solubility of each new compound before animal trials begin.","cn":"实验室在动物试验开始前报告每种新化合物的溶解度。"},{"en":"Low solubility in water makes the mineral hard to leach from soil.","cn":"在水中的低溶解度使这种矿物难以从土壤中淋出。"},{"en":"The mediator spoke about the solubility of the conflict, not its causes.","cn":"调解人谈的是这场冲突能否化解，而不是它的起因。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「solu（松开）+ bility（能）」——能松开的程度：溶解度、可解决性","word":"solubility"},"root":"拉丁 solubilitas「可溶性」= solubilis（可被溶解的）+ -itas（性质）；solubilis 出自 solvere（松开、解开），由 se-（分开）+ luere（松开）构成。英语以 soluble + -ity 构成。","sensesIntro":{"en":"Eight senses measure one loosening: how readily a solid dissolves, how much of it a solvent takes, which solvent is named, how a drug behaves in the body, how far a problem, a plan, an equation and finally a hard feeling can be loosened.","cn":"八个义项都在衡量同一次松开：固体多容易溶解，溶剂能容纳多少，被点名的是哪种溶剂，药物在体内如何表现，以及一个问题、一个方案、一个方程，最后一种难解心绪能被松开多少。"},"semanticMap":{"core":{"en":"CORE IMAGE: a scale beside a glass, showing how much of a solid the liquid has taken.","cn":"核心意象：杯子旁边放着一把量尺，显示液体已经容纳了多少固体。"},"chain":["DISSOLVING CAPACITY","MEASURED AMOUNT","NAMED SOLVENT","DRUG IN THE BODY","PROBLEM MEASURED","FEELING ABSORBED"],"branches":[{"senses":"01 · 02","en":"CAPACITY AND NUMBER: the same quality is read first as an ability and then as a measured amount.","cn":"能力与数量：同一性质先被读作能力，再被读作可测的数量。"},{"senses":"03 · 04","en":"SPECIFIC LIQUIDS: naming the solvent and naming the body fluid both tie the measure to a particular medium.","cn":"特定液体：点名溶剂与点名体液，都把量度系在特定介质上。"},{"senses":"05 · 06","en":"PROBLEMS AND PLANS: difficulties and proposals are weighed by how much of them can be absorbed.","cn":"问题与方案：困难与提议都按「能被吸收多少」来称量。"},{"senses":"07","en":"EQUATIONS: mathematics measures loosening by whether a rule can find the answer.","cn":"方程：数学以规则能否求出答案来衡量松开的程度。"},{"senses":"08","en":"FEELINGS: grief is tested for how much a situation can dissolve.","cn":"情绪：悲伤被检验的是处境能化开多少。"}]},"affixes":{"intro":{"en":"Solubility is a Latin-derived adjective plus a Latin suffix, and the pieces still build the whole chemical family.","cn":"solubility 是一个拉丁来源的形容词加上一个拉丁后缀，各部分仍在构成整个化学词族。"},"latinIntro":{"en":"-itas becomes -ity in English and names a state or quality; solvere 'to loosen' stands behind soluble, solution, solute and dissolve.","cn":"-itas 在英语中变为 -ity，表示状态或性质；solvere「松开」是 soluble、solution、solute 与 dissolve 的共同来源。"},"items":[{"word":"-ity","structure":"-ity (from Latin -itas, state or quality)","meaning":"the state of being something","meaningCN":"处于某种状态、具有某种性质","example":"The suffix turns soluble into the name of a quality.","exampleCN":"这个后缀把 soluble 变成一种性质的名称。"},{"word":"-bilis","structure":"-bilis (Latin suffix, 'able to be')","meaning":"able to be","meaningCN":"能够被……","example":"It produced solubilis from solvere.","exampleCN":"它在 solvere 上构成 solubilis。"},{"word":"luere","structure":"luere (Latin verb, 'to loosen')","meaning":"to loosen","meaningCN":"松开","example":"The root is the image inside the whole family.","exampleCN":"这个词根是整个词族里的那幅画面。"},{"word":"solvere","structure":"se- + luere","meaning":"to loosen, dissolve","meaningCN":"松开；溶解","example":"The verb is the source of the family.","exampleCN":"这个动词是词族的源头。"},{"word":"soluble","structure":"solvere + -bilis -> soluble","meaning":"able to be dissolved","meaningCN":"可溶解的","example":"The salt is soluble in warm water.","exampleCN":"这种盐可溶于温水。"},{"word":"solubility","structure":"soluble + -ity","meaning":"the quality of being soluble","meaningCN":"可溶性；溶解度","example":"Solubility falls as the water cools.","exampleCN":"水温下降时溶解度降低。"},{"word":"insolubility","structure":"in- + solubility","meaning":"the state of not dissolving","meaningCN":"不可溶性","example":"Insolubility kept the powder out of the mixture.","exampleCN":"不可溶性使这种粉末无法进入混合物。"},{"word":"solute","structure":"solutus, participle as noun","meaning":"the substance dissolved","meaningCN":"溶质","example":"The solute was weighed to the nearest milligram.","exampleCN":"溶质被称量到毫克。"},{"word":"solution","structure":"solvere + -tion","meaning":"a dissolved mixture","meaningCN":"溶液","example":"The solution turned clear after heating.","exampleCN":"加热后溶液变清。"},{"word":"dissolve","structure":"dis- + solvere","meaning":"to come apart in a liquid","meaningCN":"在液体中溶解","example":"The crystals dissolve slowly in cold water.","exampleCN":"晶体在冷水中缓慢溶解。"}],"latinEntries":[{"word":"solvere","structure":"solvere, solvi, solutum (verb, third conjugation)","meaning":"to loosen, dissolve","meaningCN":"松开；溶解"},{"word":"solubilis","structure":"solubilis, solubile (adjective, third declension)","meaning":"that may be dissolved","meaningCN":"可被溶解的"},{"word":"solubilitas","structure":"solubilitas, solubilitatis (f., third declension)","meaning":"dissolvability","meaningCN":"可溶性"},{"word":"solutio","structure":"solutio, solutionis (f., third declension)","meaning":"a loosening; a solution","meaningCN":"松开；溶液"}]}},{"word":"solute","ipa_uk":"/ˈsəʊljuːt/","ipa_us":"/ˈsoʊljuːt/","definition_zh":"溶质；被溶解的物质","definition_en":"a substance that is dissolved in a liquid to form a solution","core_image":"一撮盐落进清水，盐粒不见了，水却从此有了咸味","scene":"化学课上，学生把一勺盐倒进烧杯里的清水，盐粒很快不见，水尝起来变咸。The salt acted as the solute and disappeared into the water.","sceneCN":"这里 solute 指被溶剂溶解的物质（第 1 个义项：溶质）；句意为盐作为溶质消失在水中。图中可辨识物件：烧杯、清水、盐勺、搅拌棒。","pos":[{"tag":"n.","zh":"溶质；被溶解的物质（可数）"},{"tag":"adj.","zh":"松开的；松弛的（古旧用法）"}],"collocations":[{"phrase":"solute concentration","zh":"溶质浓度"},{"phrase":"solute particles","zh":"溶质颗粒"},{"phrase":"solute and solvent","zh":"溶质与溶剂"},{"phrase":"dissolved solute","zh":"已溶解的溶质"},{"phrase":"solute transport","zh":"溶质运移"},{"phrase":"the mass of solute","zh":"溶质的质量"}],"forms":[{"label":"单数","form":"solute"},{"label":"复数","form":"solutes"},{"label":"相关名词（溶剂）","form":"solvent"},{"label":"相关名词（溶液）","form":"solution"},{"label":"相关形容词","form":"soluble"},{"label":"相关名词（溶解）","form":"dissolution"}],"derivatives":[{"word":"solvent","pos":"n./adj.","zh":"溶剂／有清偿能力的"},{"word":"solution","pos":"n.","zh":"溶液；解答"},{"word":"soluble","pos":"adj.","zh":"可溶的"},{"word":"solubility","pos":"n.","zh":"溶解度"},{"word":"dissolve","pos":"v.","zh":"溶解"}],"senses":[{"no":"01","title":"The substance that is dissolved","titleCN":"被溶解的物质","definition":"the solid, liquid or gas that is taken up by a solvent and becomes part of a solution","definitionCN":"被溶剂接纳并成为溶液一部分的固体、液体或气体","example":"In salt water, salt is the solute and water is the solvent.","exampleCN":"在盐水中，盐是溶质，水是溶剂。","why":"solute comes from the Latin participle solutus 'dissolved', so the noun names the thing that has already been loosened into the liquid.","whyCN":"solute 出自拉丁分词 solutus「已溶解的」，因此这个名词命名的是已经被拆散进液体里的那个东西。"},{"no":"02","title":"The particles dispersed in a solution","titleCN":"分散在溶液中的溶质微粒","definition":"the individual molecules or ions of the dissolved substance as they are distributed through the liquid","definitionCN":"被溶解物质以单个分子或离子形式分布在液体各处","example":"Each solute particle is surrounded by a shell of solvent molecules.","exampleCN":"每个溶质微粒都被一层溶剂分子包围。","why":"once dissolved, the substance exists as separate particles, and the same noun marks them as the dissolved party.","whyCN":"溶解之后物质以分离的微粒存在，同一个名词把它们标记为「被溶的一方」。"},{"no":"03","title":"The weighed quantity in a calculation","titleCN":"化学计算中的溶质量","definition":"the amount of the dissolved substance, measured in mass or moles, that enters a calculation","definitionCN":"以质量或摩尔数计、进入计算的被溶解物质量","example":"The chemist weighed the solute before adding it to the flask.","exampleCN":"化学家在把溶质加入烧瓶前先称了它的质量。","why":"a solution problem begins with how much solute there is, so the noun shifts from the substance to its measured amount.","whyCN":"溶液计算的第一步就是有多少溶质，于是名词从物质本身转向它的计量。"},{"no":"04","title":"The solute share of a mixture","titleCN":"溶质在混合物中所占的比例","definition":"the proportion of a solution made up by the dissolved substance, as opposed to the solvent","definitionCN":"溶液中由被溶解物质所占的比例，与溶剂相对","example":"A high solute concentration lowers the freezing point.","exampleCN":"溶质浓度高会降低凝固点。","why":"the noun is frequent in compounds that measure the dissolved share, because that share controls most properties of the solution.","whyCN":"这个名词常出现在衡量「被溶部分」的复合词里，因为这一比例决定溶液的多数性质。"},{"no":"05","title":"Dissolved substances in body fluid","titleCN":"体液中的溶解物","definition":"the salts, sugars and other dissolved substances carried in blood or other body fluids","definitionCN":"血液或其他体液中携带的盐、糖等溶解物质","example":"Electrolytes are the main solutes in blood plasma.","exampleCN":"电解质是血浆中的主要溶质。","why":"physiology borrows the chemical noun because body fluid is literally a solution with dissolved particles in it.","whyCN":"生理学借用这个化学名词，因为体液本来就是含溶解微粒的溶液。"},{"no":"06","title":"The component being measured","titleCN":"分析化学中待测的溶解组分","definition":"the dissolved component that an analytical instrument is set to detect or quantify","definitionCN":"分析仪器被设定去检测或定量的那个溶解组分","example":"The solute was detected by its absorption peak.","exampleCN":"该溶质通过其吸收峰被检测出来。","why":"in analysis the solute is the target, so the word marks the component that the measurement is about.","whyCN":"在分析中溶质是目标，因此这个词标记的是测量所针对的那个组分。"},{"no":"07","title":"Absorbed into a larger whole","titleCN":"比喻：被更大整体吸收的成分","definition":"something taken in and absorbed by a larger system until it is no longer distinct","definitionCN":"被更大系统接纳、吸收，直到不再独立可辨的东西","example":"Each reform was absorbed like a solute into the old administration.","exampleCN":"每一项改革都像溶质一样被旧行政体系吸收。","why":"the chemical image of a solid vanishing into a liquid gives the figurative sense of anything absorbed until it loses its outline.","whyCN":"固体消失在液体里的化学画面，给出「被吸收到失去轮廓」的比喻义。"},{"no":"08","title":"Loosened or relaxed, an old use","titleCN":"古旧形容词义：松开的、松弛的","definition":"loosened, relaxed or released, used as an adjective in older English","definitionCN":"旧英语中作形容词，指松开的、放松的、被释放的","example":"Old medical texts called a relaxed muscle solute.","exampleCN":"旧医学文献把放松的肌肉称作 solute。","why":"the adjective is the original participle meaning 'loosened', and the chemical noun is a later specialized use of the same form.","whyCN":"形容词是最初的分词义「松开的」，化学名词是同一形式后来专门化的结果。"}],"etymology":{"intro":{"en":"Solute is the Latin past participle solutus 'loosened, dissolved' used as a noun. The adjective is recorded in English from the fifteenth century, while the chemical noun for a dissolved substance dates only from the late nineteenth century. Dates are approximate.","cn":"solute 是拉丁过去分词 solutus「松开的、溶解的」作名词使用。形容词义自十五世纪见于英语，而指「被溶解物质」的化学名词到十九世纪末才出现。年代均为约数。"},"items":[{"era":"LATIN SOLVERE","en":"Solvere 'to loosen, untie, dissolve' is built from se- 'apart' plus luere 'to loosen'; it also gives solve, solution and dissolve.","cn":"solvere「松开、解开、溶解」由 se-「分开」加 luere「松开」构成，也衍生 solve、solution 与 dissolve。"},{"era":"LATIN SOLUTUS","en":"The past participle solutus meant 'loosened, released, dissolved', and English first borrowed it as an adjective with that literal sense.","cn":"过去分词 solutus 意为「松开的、释放的、溶解的」，英语最初把它作为形容词借入，保留字面义。"},{"era":"SCIENTIFIC NOUN","en":"Late nineteenth-century chemistry turned the participle into a countable noun for the substance that a solvent takes up, pairing it with solvent.","cn":"十九世纪末的化学把这个分词变成可数名词，指被溶剂接纳的物质，并与 solvent 配对。"},{"era":"PHYSIOLOGY","en":"Twentieth-century physiology extended the noun to dissolved salts and sugars in body fluids, where the same contrast with solvent holds.","cn":"二十世纪的生理学把这个名词扩展到体液中的溶解盐类与糖，同样保持与溶剂的对照。"},{"era":"ANALYSIS AND FIGURE","en":"Analytical chemistry made the solute the target of detection, and general writing borrowed the image for anything absorbed into a larger whole.","cn":"分析化学把溶质变成检测目标，普通写作则借这个意象指任何被更大整体吸收的东西。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin shape of luere is reconstructed, and no exact date is recorded for the first chemical use of the noun.","cn":"来源不确定（更深词源）：luere 在拉丁语之前的形式属于重构；这个名词最早的化学用法没有确切年代记录。"}]},"similar":{"note":{"en":"Group one holds the two roles in a solution and the words built on the same root; group two holds other things suspended or carried in a liquid.","cn":"第一组是溶液中的两个角色以及同根词；第二组是悬浮或携带在液体中的其他东西。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"solvent","ipa":"/ˈsɒlvent/","tag":"the other role","definition":"The liquid that does the dissolving; solute and solvent are defined only against each other.","definitionCN":"执行溶解的液体；溶质与溶剂只在相互对照中才有定义。"},{"word":"solution","ipa":"/səˈluːʃn/","tag":"the whole mixture","definition":"The combined liquid and dissolved substance; it contains both solute and solvent.","definitionCN":"液体与溶解物质的结合体，同时包含溶质与溶剂。"},{"word":"soluble","ipa":"/ˈsɒljəbl/","tag":"the adjective","definition":"Describes the substance's ability to dissolve, while solute names the substance after it has done so.","definitionCN":"描述物质的溶解能力，而 solute 命名溶解之后的物质。"},{"word":"solvate","ipa":"/ˈsɒlveɪt/","tag":"solvent bound to solute","definition":"A compound or complex in which solvent molecules are attached to solute particles; it is a stage, not a role.","definitionCN":"溶剂分子附着在溶质微粒上的化合物或络合物；它是一个阶段，不是角色。"}]},{"heading":"NEAR MEANING","entries":[{"word":"precipitate","ipa":"/prɪˈsɪpɪteɪt/","tag":"solid that came out","definition":"A solid that leaves a solution instead of staying dissolved, the opposite movement from a solute.","definitionCN":"从溶液中析出、不再溶解的固体，与溶质的去向相反。"},{"word":"suspension","ipa":"/səˈspenʃn/","tag":"not dissolved","definition":"Fine particles held in a liquid without dissolving; a suspension can be filtered out, a solute cannot.","definitionCN":"悬浮在液体中而未溶解的细颗粒；悬浮物可被滤出，溶质不能。"},{"word":"electrolyte","ipa":"/ɪˈlektrəlaɪt/","tag":"a kind of solute","definition":"A solute that conducts electricity when dissolved, such as a salt; every electrolyte is a solute, not every solute an electrolyte.","definitionCN":"溶解后导电的溶质，如盐类；电解质都是溶质，但溶质不都是电解质。"},{"word":"mixture","ipa":"/ˈmɪkstʃə/","tag":"broader category","definition":"Any combination of substances that keep their identities; a solution is one kind of mixture.","definitionCN":"任何保持各自性质的物质组合；溶液是混合物的一种。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Solutus 'dissolved': the solute is the thing already loosened into the liquid.","cn":"solutus「已溶解的」：溶质是已经被拆散进液体的那个东西。"},{"en":"The pair is fixed: solute and solvent, one dissolved and one dissolving.","cn":"配对固定：溶质与溶剂，一个被溶，一个在溶。"},{"en":"The family runs solute, solvent, solution, soluble, solubility.","cn":"同族词包括 solute、solvent、solution、soluble、solubility。"},{"en":"Laboratory phrases mark the measured sense: solute concentration, mass of solute.","cn":"实验室说法标出计量义：溶质浓度、溶质质量。"},{"en":"A solute can be filtered out only after it stops being dissolved, which is why precipitate is its opposite.","cn":"溶质只有在不再溶解之后才滤得出来，因此「沉淀物」是它的反向词。"}],"abstract":[{"en":"Picture a pinch of salt losing its shape and keeping its taste.","cn":"想象一撮盐失去形状，却留下味道。"},{"en":"Picture a new word entering a language and slowly ceasing to sound foreign.","cn":"想象一个新词进入一种语言，慢慢不再显得外来。"},{"en":"Picture a crowd absorbing one visitor until nobody can point him out.","cn":"想象人群吸收了一位来客，最后没人能指出他来。"}]},"examples":[{"en":"The solute must be dry before it is weighed, or the mass will be too high.","cn":"溶质称量前必须干燥，否则质量会偏高。"},{"en":"Sugar is the solute in syrup, and water is the solvent.","cn":"糖浆中糖是溶质，水是溶剂。"},{"en":"The kidney removes solutes from the blood and returns them to the body in measured amounts.","cn":"肾脏把溶质从血液中滤出，再按量把其中一部分送回体内。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「solu（松开）+ te」——被水松开、化进去的那一方：溶质","word":"solute"},"root":"拉丁 solutus「松开的、溶解的」，是 solvere（松开、解开、溶解）的过去分词；solvere 由 se-（分开）+ luere（松开）构成。化学名词义出现于十九世纪末。","sensesIntro":{"en":"Eight senses follow one dissolved substance: it is named as the thing taken up, seen as separate particles, weighed in a calculation, counted as a share, found in body fluid, targeted by an instrument, imagined as anything absorbed into a whole, and finally traced back to an old adjective meaning 'loosened'.","cn":"八个义项跟着同一种被溶解的物质：它先被命名为被接纳之物，再被看作分离的微粒、被称量进计算、被计作一个比例、在体液中被找到、被仪器锁定为目标、被想象成任何被整体吸收之物，最后追溯到旧形容词义「松开的」。"},"semanticMap":{"core":{"en":"CORE IMAGE: a grain of salt that disappears into clear water yet changes its taste.","cn":"核心意象：一粒盐消失在清水里，却改变了水的味道。"},"chain":["SUBSTANCE TAKEN UP","SEPARATE PARTICLES","WEIGHED AMOUNT","DISSOLVED SHARE","BODY FLUID","ABSORBED WHOLE"],"branches":[{"senses":"01 · 02","en":"THE DISSOLVED THING: the role in the mixture and the particles that carry it are the same substance seen at two scales.","cn":"被溶之物：在混合物中的角色与承载它的微粒，是同一物质在两个尺度上的样子。"},{"senses":"03 · 04","en":"MEASURED SOLUTE: mass and proportion turn the substance into a quantity a chemist can use.","cn":"被计量的溶质：质量与比例把物质变成化学家可用的数量。"},{"senses":"05 · 06","en":"FOUND IN THE BODY AND IN THE INSTRUMENT: physiology and analysis each make the solute the object of attention.","cn":"在体内与在仪器中被找到：生理学与分析化学都把溶质变成关注对象。"},{"senses":"07","en":"ABSORBED INTO A WHOLE: anything taken in until its outline disappears repeats the chemical image.","cn":"被整体吸收：任何被接纳到轮廓消失的东西，都在重复这一化学画面。"},{"senses":"08","en":"LOOSENED: the old adjective keeps the original participle sense behind the modern noun.","cn":"松开的：旧形容词把最初的分词义保留在现代名词背后。"}]},"affixes":{"intro":{"en":"Solute is a Latin participle turned into a noun, and the root that built it also builds the rest of the solution vocabulary.","cn":"solute 是一个拉丁分词转成的名词，构成它的词根也构成整套溶液词汇。"},"latinIntro":{"en":"Solvere gives solute, solution, soluble and dissolve; the prefix se- marks separation, and -utus is the participle ending.","cn":"solvere 衍生 solute、solution、soluble 与 dissolve；前缀 se- 标记分开，-utus 是分词词尾。"},"items":[{"word":"se-","structure":"se- (Latin prefix, 'apart')","meaning":"apart","meaningCN":"分开","example":"The prefix marks the separation of particles.","exampleCN":"这个前缀标记微粒的分开。"},{"word":"luere","structure":"luere (Latin verb, 'to loosen')","meaning":"to loosen","meaningCN":"松开","example":"The root carries the loosening image.","exampleCN":"这个词根带着「松开」的意象。"},{"word":"solvere","structure":"se- + luere","meaning":"to loosen, dissolve","meaningCN":"松开；溶解","example":"The verb is the source of the family.","exampleCN":"这个动词是词族的源头。"},{"word":"-utus","structure":"-utus (Latin past participle ending)","meaning":"having been acted on","meaningCN":"已被作用过的","example":"The ending makes the word a participle, not a new root.","exampleCN":"这个词尾使该词成为分词，而不是新词根。"},{"word":"solute","structure":"solutus -> solute","meaning":"the dissolved substance","meaningCN":"被溶解的物质","example":"Salt is the solute in sea water.","exampleCN":"盐是海水中的溶质。"},{"word":"solutes","structure":"solute + -s (plural)","meaning":"more than one dissolved substance","meaningCN":"多种溶质","example":"Several solutes were present in the sample.","exampleCN":"样品中含有多种溶质。"},{"word":"solvent","structure":"solvere + -ent (one that does)","meaning":"the liquid that dissolves","meaningCN":"执行溶解的液体","example":"Water is the solvent in most biological reactions.","exampleCN":"水是多数生物反应中的溶剂。"},{"word":"solution","structure":"solvere + -tion (result)","meaning":"the resulting mixture","meaningCN":"溶液","example":"The solution was stirred for ten minutes.","exampleCN":"溶液被搅拌了十分钟。"},{"word":"soluble","structure":"solvere + -bilis (able to be)","meaning":"able to be dissolved","meaningCN":"可溶解的","example":"The compound is soluble in ethanol.","exampleCN":"这种化合物可溶于乙醇。"},{"word":"dissolve","structure":"dis- + solvere","meaning":"to break apart in a liquid","meaningCN":"在液体中溶解","example":"Stir until the sugar dissolves.","exampleCN":"搅到糖溶解为止。"}],"latinEntries":[{"word":"solvere","structure":"solvere, solvi, solutum (verb, third conjugation)","meaning":"to loosen, dissolve","meaningCN":"松开；溶解"},{"word":"solutus","structure":"solutus, soluta, solutum (past participle)","meaning":"loosened, dissolved","meaningCN":"松开的；溶解的"},{"word":"solutio","structure":"solutio, solutionis (f., third declension)","meaning":"a loosening; a solution","meaningCN":"松开；溶液"},{"word":"solubilis","structure":"solubilis, solubile (adjective, third declension)","meaning":"that may be dissolved","meaningCN":"可被溶解的"}]}},{"word":"concentrated","ipa_uk":"/kənˈsentreɪtɪd/","ipa_us":"/ˈkɑːnsəntreɪtɪd/","definition_zh":"浓缩的；浓度高的；集中的；专心的；聚焦的","definition_en":"made stronger or denser by removing water or spreading less widely, or brought to bear on one point","core_image":"一大锅清汤被小火慢慢收干，最后只剩一小碗味道极浓的汁","scene":"厨房里，厨师把一大锅汤小火收干，最后盛出一小碗味道极浓的汁。The cook concentrated the broth until one cup held the flavour of the whole pot.","sceneCN":"这里 concentrated 指去掉水分使浓度提高（第 1 个义项：浓缩的）；句意为厨师把汤收干，直到一杯汁含有一整锅的味道。图中可辨识物件：汤锅、炉火、小碗、汤勺。","pos":[{"tag":"adj.","zh":"浓缩的；浓度高的"},{"tag":"adj.","zh":"集中的；专心的；聚焦的"}],"collocations":[{"phrase":"concentrated effort","zh":"集中的努力"},{"phrase":"concentrated acid","zh":"浓酸"},{"phrase":"concentrated juice","zh":"浓缩果汁"},{"phrase":"concentrated power","zh":"集中的权力"},{"phrase":"concentrated population","zh":"集中的人口"},{"phrase":"concentrated beam","zh":"聚焦光束"}],"forms":[{"label":"原级","form":"concentrated"},{"label":"比较级","form":"more concentrated"},{"label":"最高级","form":"most concentrated"},{"label":"动词","form":"concentrate"},{"label":"名词","form":"concentration"},{"label":"反义形容词（稀释的）","form":"diluted"}],"derivatives":[{"word":"concentrate","pos":"v./n.","zh":"集中；浓缩／浓缩物"},{"word":"concentration","pos":"n.","zh":"浓度；专注；集中"},{"word":"concentrator","pos":"n.","zh":"浓缩器；集中装置"},{"word":"concentric","pos":"adj.","zh":"同心的（同出 center 词根）"},{"word":"deconcentrate","pos":"v.","zh":"使分散；下放权力"}],"senses":[{"no":"01","title":"Made denser by removing water","titleCN":"去掉水分后变得更浓","definition":"reduced in volume by removing water or another liquid so that the remaining substance is stronger","definitionCN":"通过除去水或其他液体而缩小体积，使剩余部分更浓","example":"The concentrated syrup is diluted before bottling.","exampleCN":"浓缩糖浆在装瓶前会被稀释。","why":"concentrated is the participle of concentrate, from con- 'together' plus centrum 'center', so the parts are driven toward one center and the volume shrinks.","whyCN":"concentrated 是 concentrate 的分词，来自 con-「共同」加 centrum「中心」，即把各部分赶向一个中心，体积随之缩小。"},{"no":"02","title":"Containing a high proportion of the active substance","titleCN":"有效成分含量高的、浓烈的","definition":"having a large amount of an active ingredient in a small volume, so that a little does a great deal","definitionCN":"小体积内含大量有效成分，一点点就能起很大作用","example":"A drop of concentrated acid burned the bench.","exampleCN":"一滴浓酸把实验台烧出了痕。","why":"once the water is removed, the active part makes up most of what is left, which is the measurable form of the first sense.","whyCN":"水分去掉后，有效部分占了剩下的大部分，这是第一义的可测量形式。"},{"no":"03","title":"Gathered into one area","titleCN":"集中在同一地区的","definition":"existing mainly in one place rather than spread out over a wide area","definitionCN":"主要存在于一处，而非分散在广阔区域","example":"Industry remained concentrated in three coastal cities.","exampleCN":"工业仍集中在三座沿海城市。","why":"the same movement toward a center applies to people and factories, so concentration becomes a matter of geography.","whyCN":"同一种「向中心靠拢」的运动也适用于人与工厂，于是集中成了地理问题。"},{"no":"04","title":"Held in few hands","titleCN":"权力或资源集中在少数人手中","definition":"gathered into a small number of hands or institutions rather than widely shared","definitionCN":"被收拢到少数人或不多的机构手中，而非广泛分享","example":"Concentrated power made the board hard to challenge.","exampleCN":"集中的权力使董事会难以被挑战。","why":"power that is brought to one center can act as a single force, which is why concentration is also a political word.","whyCN":"被收拢到一个中心的权力能作为单一力量行动，因此 concentration 也是政治词汇。"},{"no":"05","title":"Fully focused in attention","titleCN":"全神贯注的","definition":"carried out with attention fixed on one task, with distractions shut out","definitionCN":"注意力固定在一件事上、排除干扰地进行","example":"A concentrated effort finished the report in one evening.","exampleCN":"一次专注的努力在一个晚上完成了报告。","why":"the mind is told to gather itself to one center, so concentration becomes the everyday word for attention.","whyCN":"头脑被要求向一个中心聚拢，于是 concentration 成了「专注」的日常说法。"},{"no":"06","title":"Brought into a narrow beam","titleCN":"光线或能量被聚焦的","definition":"directed into a narrow beam or small area so that its effect is stronger","definitionCN":"被导入狭窄光束或小范围，使效果更强","example":"The lens produced a concentrated beam of light.","exampleCN":"透镜产生了一束聚焦的光。","why":"light obeys the same geometry as anything else gathered to a point, so optics uses the participle literally.","whyCN":"光遵守与一切向一点聚拢之物相同的几何，因此光学直接使用这个分词。"},{"no":"07","title":"Fixed on a single object","titleCN":"注意力落在某一对象上","definition":"directed toward one particular thing, often followed by on, as attention or study is","definitionCN":"朝向某一个特定事物，常后接表示关涉的介词，如注意力或研究","example":"Her attention was concentrated on the single page.","exampleCN":"她的注意力全落在那一页上。","why":"concentration needs an object, and the participle with on names the point at which the gathering arrives.","whyCN":"集中总要有对象，带关涉介词的分词就点明聚拢所抵达的那一点。"},{"no":"08","title":"Collected into one strong whole","titleCN":"抽象义：分散之物被收成一束","definition":"used figuratively of scattered material, effort or argument gathered into one forceful whole","definitionCN":"比喻指零散的材料、努力或论证被收拢成一个有力的整体","example":"Ten years of scattered notes became one concentrated argument.","exampleCN":"十年零散的笔记变成一个高度凝练的论证。","why":"the abstract sense keeps the geometry but drops the liquid: what is gathered is meaning rather than matter.","whyCN":"抽象义保留了这一几何关系却去掉了液体：被收拢的是意义，而非物质。"}],"etymology":{"intro":{"en":"Concentrated is the past participle of concentrate, from con- 'together' plus Late Latin centrare 'to center', itself from centrum 'center', from Greek kentron 'sharp point, goad'. The chemical sense of reducing volume dates from the seventeenth century. Dates are approximate.","cn":"concentrated 是 concentrate 的过去分词，来自 con-「共同」加晚期拉丁 centrare「置于中心」，后者出自 centrum「中心」，再上溯希腊 kentron「尖点、刺棒」。缩减体积的化学义始于十七世纪。年代均为约数。"},"items":[{"era":"GREEK KENTRON","en":"Kentron named a sharp point, a goad and the fixed point of a pair of compasses, and Greek geometry used it for the center of a circle.","cn":"kentron 指尖点、刺棒，也指圆规固定的那一点，希腊几何用它表示圆心。"},{"era":"LATIN CENTRUM","en":"Latin took kentron as centrum 'center', the middle point from which distances are measured.","cn":"拉丁把 kentron 借作 centrum「中心」，即测量距离时所依据的中点。"},{"era":"LATIN CONCENTRARE","en":"Con- 'together' plus centrare produced concentrare 'to bring to a common center, to press together'.","cn":"con-「共同」加 centrare 构成 concentrare「使聚到同一中心、压紧」。"},{"era":"CHEMICAL USE","en":"Seventeenth-century chemistry used the participle for liquids reduced by evaporation, so that a small volume carried the strength of a large one.","cn":"十七世纪化学用这个分词指经蒸发缩减的液体，使小体积承载大体积的强度。"},{"era":"FIGURATIVE USE","en":"By the nineteenth century the same participle described attention, power and population gathered to one point rather than spread out.","cn":"到十九世纪，同一分词用来描述注意力、权力与人口被收拢到一点而非散布开来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Greek origin of kentron is unsettled, and any older root proposed for it is a reconstruction rather than a demonstrated form.","cn":"来源不确定（更深词源）：kentron 在希腊语之前的来源没有定论，为其提出的更古老词根属于重构形式，而非已证实的形式。"}]},"similar":{"note":{"en":"Group one holds words built on the center root, which look alike but point in different directions; group two holds adjectives for things packed tightly together.","cn":"第一组是同出「中心」词根、形近而方向不同的词；第二组是形容紧密聚在一起的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"concentrate","ipa":"/kənˈsentrəɪt/","tag":"the verb behind it","definition":"The verb 'to bring to a center': to focus attention or to reduce a liquid by removing water.","definitionCN":"「聚向中心」的动词：集中注意力，或除去水分使液体变浓。"},{"word":"concentric","ipa":"/kənˈsentrɪk/","tag":"same center, different idea","definition":"Describes circles that share one center; it is about geometry, not about strength or attention.","definitionCN":"形容共用同一个圆心的圆；说的是几何，不是强度或注意力。"},{"word":"eccentric","ipa":"/ɪˈsentrɪk/","tag":"away from the center","definition":"Ec- 'out of' plus centrum: off center, hence odd or unconventional in behaviour.","definitionCN":"ec-「离开」加 centrum：偏离中心，因此指行为古怪、不合常规。"},{"word":"center","ipa":"/ˈsentə/","tag":"the base noun","definition":"The middle point itself; every prefixed form is read against this plain noun.","definitionCN":"中点本身；每个带前缀的形式都要对照这个朴素名词来读。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dense","ipa":"/dens/","tag":"packed, not reduced","definition":"Having parts packed closely together; a dense fog is not necessarily a concentrated solution.","definitionCN":"各部分紧密挤压；浓雾未必是浓溶液。"},{"word":"intense","ipa":"/ɪnˈtens/","tag":"strength of feeling","definition":"Very strong in degree, used of light, feeling or activity rather than of a measured solution.","definitionCN":"程度极强，用于光、情感或活动，而非可测量的溶液。"},{"word":"condensed","ipa":"/kənˈdenst/","tag":"shortened or thickened","definition":"Made shorter or thicker, as condensed milk or a condensed report; it stresses compression rather than a center.","definitionCN":"被缩短或变稠，如炼乳或摘要；强调压缩，而非中心。"},{"word":"focused","ipa":"/ˈfəʊkəst/","tag":"attention only","definition":"Brought to a point of attention or a point of light; it rarely carries the chemical sense.","definitionCN":"被收拢到注意力或光的某一点；很少带化学义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Con- 'together' plus centrum 'center': everything is driven to one point.","cn":"con-「共同」加 centrum「中心」：一切都被赶向一点。"},{"en":"The family runs concentrate, concentration, concentrated, concentric, eccentric.","cn":"同族词包括 concentrate、concentration、concentrated、concentric、eccentric。"},{"en":"Fixed phrases split the senses: concentrated juice, concentrated power, concentrated effort.","cn":"固定搭配切分义项：浓缩果汁、集中的权力、专注的努力。"},{"en":"The chemical sense pairs with dilute: concentrated acid against dilute acid.","cn":"化学义与 dilute 配对：浓酸对稀酸。"},{"en":"The adjective keeps the participle ending -ed, so it describes a result already achieved.","cn":"这个形容词保留分词词尾 -ed，因此描述已经完成的结果。"}],"abstract":[{"en":"Picture a whole orchard boiled down into one spoonful of jam.","cn":"想象一整片果园被熬成一勺果酱。"},{"en":"Picture a hundred voices at last singing the same note.","cn":"想象一百个声音终于唱在同一个音上。"},{"en":"Picture a lamp behind one small hole, lighting a single spot on a wall.","cn":"想象灯后只留一个小孔，把光打墙上的一点。"}]},"examples":[{"en":"The factory ships concentrated orange juice and adds water at the other end.","cn":"工厂运出浓缩橙汁，到另一端再加水。"},{"en":"Rainfall is concentrated in two months, so the fields need irrigation later.","cn":"降雨集中在两个月里，因此田里之后需要灌溉。"},{"en":"The final hour of study was more concentrated than the whole afternoon before it.","cn":"最后一小时的学习比之前整个下午都更专注。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「con（共同）+ centr（中心）+ ated」——全往一个中心挤：浓缩的、集中的、专注的","word":"concentrated"},"root":"拉丁 concentrare「聚到同一中心、压紧」的过去分词 concentratus = con-（共同）+ centrum（中心）；centrum 出自希腊 kentron（尖点），其更早来源不确定。英语 concentrate 的过去分词作形容词。","sensesIntro":{"en":"Eight senses follow one gathering to a center: water leaves and a liquid grows strong, the active part dominates, factories and people cluster, power collects in few hands, attention fixes on a task, light is narrowed to a beam, attention lands on one object, and finally scattered meaning is pressed into one argument.","cn":"八个义项跟着同一次「向中心聚拢」：水离开、液体变浓，有效成分占主导，工厂与人聚集，权力收进少数手中，注意力固定在一件事上，光被收成光束，注意力落在某一对象上，最后零散的意义被压成一个论证。"},"semanticMap":{"core":{"en":"CORE IMAGE: a large pot of thin broth reduced by slow heat until one small bowl holds all of its taste.","cn":"核心意象：一大锅清汤被小火收干，直到一小碗盛下全部味道。"},"chain":["WATER REMOVED","ACTIVE PART DOMINANT","GATHERED IN PLACE","POWER IN FEW HANDS","ATTENTION FIXED","MEANING PRESSED"],"branches":[{"senses":"01 · 02","en":"STRONGER LIQUID: removing water and raising the active share are the same reduction seen as process and as result.","cn":"更浓的液体：去掉水与提高有效成分占比，是同一次缩减的过程与结果。"},{"senses":"03 · 04","en":"GATHERED IN SPACE AND IN POWER: factories cluster and authority collects by the same centering movement.","cn":"在空间与权力中聚拢：工厂聚集与权力收拢，是同一种向心运动。"},{"senses":"05 · 07","en":"FIXED ATTENTION: the mind gathers itself and then lands on one named object.","cn":"固定的注意力：头脑先聚拢自身，再落在某个被点明的对象上。"},{"senses":"06","en":"NARROW BEAM: optics uses the same geometry to make light act at one spot.","cn":"收窄的光束：光学用同一几何让光在一点上起作用。"},{"senses":"08","en":"PRESSED MEANING: what is concentrated at the end is not matter but argument.","cn":"被压紧的意义：最后被浓缩的不再是物质，而是论证。"}]},"affixes":{"intro":{"en":"Concentrated is a prefixed Latin participle, and both the prefix and the center root build a large family of English words.","cn":"concentrated 是一个带前缀的拉丁分词，前缀与「中心」词根共同构成一大族英语词。"},"latinIntro":{"en":"Con- 'together' plus centrum 'center' gives concentrate, concentration and concentric; ec- 'out of' gives eccentric, the word that moves the other way.","cn":"con-「共同」加 centrum「中心」构成 concentrate、concentration 与 concentric；ec-「离开」构成 eccentric，即朝反方向移动的词。"},"items":[{"word":"con-","structure":"con- (Latin prefix, 'together, with')","meaning":"together; completely","meaningCN":"共同；彻底","example":"The prefix gathers the parts toward one point.","exampleCN":"这个前缀把各部分聚向一点。"},{"word":"centrum","structure":"centrum, centri (n., second declension)","meaning":"center","meaningCN":"中心","example":"The noun supplies the point everything is gathered to.","exampleCN":"这个名词提供一切聚拢所向的那一点。"},{"word":"concentrare","structure":"con- + centrare","meaning":"to bring to a center","meaningCN":"使聚到中心","example":"The Latin verb begins the whole family.","exampleCN":"这个拉丁动词开启整个词族。"},{"word":"concentrate","structure":"concentrare -> concentrate","meaning":"to gather; to make stronger","meaningCN":"集中；使变浓","example":"The plant concentrates the juice by evaporation.","exampleCN":"工厂用蒸发使果汁变浓。"},{"word":"concentrated","structure":"concentrate + -ed (past participle)","meaning":"made stronger or gathered","meaningCN":"被浓缩的；集中的","example":"The concentrated acid is handled with gloves.","exampleCN":"浓酸要戴手套处理。"},{"word":"concentration","structure":"concentrate + -ion (action or result)","meaning":"the act or state of being concentrated","meaningCN":"浓缩；浓度；专注","example":"The concentration of the solution was measured twice.","exampleCN":"溶液的浓度被测量了两次。"},{"word":"concentric","structure":"con- + centrum + -ic (having the same center)","meaning":"sharing one center","meaningCN":"同心的","example":"The ripples formed concentric rings.","exampleCN":"涟漪形成同心圆。"},{"word":"eccentric","structure":"ec- (out of) + centrum + -ic","meaning":"away from the center","meaningCN":"偏离中心的","example":"The orbit is slightly eccentric.","exampleCN":"这条轨道略微偏心。"},{"word":"concentrator","structure":"concentrate + -or (device or agent)","meaning":"a device that concentrates","meaningCN":"浓缩器","example":"The concentrator removed half the water.","exampleCN":"浓缩器去掉了半数水分。"},{"word":"deconcentrate","structure":"de- (away) + concentrate","meaning":"to spread out again","meaningCN":"使分散；下放","example":"The reform deconcentrated authority to the regions.","exampleCN":"改革把权力下放到各地区。"}],"latinEntries":[{"word":"centrum","structure":"centrum, centri (n., second declension)","meaning":"center","meaningCN":"中心"},{"word":"concentrare","structure":"concentrare, concentravi, concentratum (verb, first conjugation)","meaning":"to bring to a common center","meaningCN":"使聚到同一中心"},{"word":"concentratus","structure":"concentratus, concentrata, concentratum (past participle)","meaning":"gathered to a center","meaningCN":"聚到中心的"},{"word":"concentricus","structure":"concentricus, concentrica, concentricum (adjective)","meaning":"having the same center","meaningCN":"同心的"}]}},{"word":"dilute","ipa_uk":"/dɪˈljuːt/","ipa_us":"/dɪˈluːt/","definition_zh":"稀释；冲淡；削弱（效果、权力）；稀释过的","definition_en":"to make a liquid weaker by adding water or another solvent, or to make something less forceful","core_image":"一小杯浓果汁倒进一大壶凉水，颜色从深褐立刻变浅","scene":"厨房里，服务员把一小杯浓缩果汁倒进一大壶凉水，颜色立刻从深褐变浅。The waiter diluted the strong juice with cold water before serving it.","sceneCN":"这里 dilute 指加水使浓度降低（第 1 个义项：稀释）；句意为服务员上桌前用凉水把浓果汁稀释。图中可辨识物件：浓缩果汁、水壶、玻璃杯、搅拌勺。","pos":[{"tag":"vt.","zh":"稀释；冲淡；使削弱"},{"tag":"adj.","zh":"稀释的；浓度低的"}],"collocations":[{"phrase":"dilute with water","zh":"用水稀释"},{"phrase":"dilute acid","zh":"稀酸"},{"phrase":"dilute a solution","zh":"稀释溶液"},{"phrase":"dilute the effect","zh":"削弱效果"},{"phrase":"dilute ownership","zh":"稀释所有权"},{"phrase":"dilute the message","zh":"冲淡信息"}],"forms":[{"label":"三单（he/she/it）","form":"dilutes"},{"label":"过去式","form":"diluted"},{"label":"过去分词","form":"diluted"},{"label":"现在分词","form":"diluting"},{"label":"名词","form":"dilution"},{"label":"形容词","form":"dilute"}],"derivatives":[{"word":"dilution","pos":"n.","zh":"稀释；稀释物；削弱"},{"word":"diluent","pos":"n./adj.","zh":"稀释剂／稀释的"},{"word":"diluted","pos":"adj.","zh":"稀释过的；被削弱的"},{"word":"undiluted","pos":"adj.","zh":"未稀释的；纯粹的"},{"word":"dilutable","pos":"adj.","zh":"可稀释的"}],"senses":[{"no":"01","title":"To add water and lower concentration","titleCN":"加水以降低浓度","definition":"to add water or another solvent to a liquid so that the amount of active substance in each unit falls","definitionCN":"向液体中加入水或其他溶剂，使每单位中有效物质的量下降","example":"Dilute the acid with three parts water.","exampleCN":"用三份水把这种酸稀释。","why":"dilute comes from Latin diluere 'to wash away', so the core action is washing strength out into a larger volume.","whyCN":"dilute 出自拉丁 diluere「冲走」，核心动作就是把强度冲散到更大的体积里。"},{"no":"02","title":"To weaken a solution before testing","titleCN":"检测前把溶液调稀","definition":"to reduce the strength of a sample so that it falls within the range an instrument or a procedure can handle","definitionCN":"降低样品的强度，使仪器或操作能处理","example":"The technician diluted the sample before testing.","exampleCN":"技术员在检测前把样品稀释了。","why":"a sample that is too strong must be reduced, so laboratory routine turns the first sense into a standard step.","whyCN":"过浓的样品必须减弱，实验室流程就把第一义变成标准步骤。"},{"no":"03","title":"To weaken power or influence","titleCN":"削弱权力或影响力","definition":"to make authority, influence or an advantage less effective by spreading it among more parties","definitionCN":"把权威、影响力或优势分散给更多方，使其效力下降","example":"Adding more members diluted the chairman's influence.","exampleCN":"增加成员削弱了主席的影响力。","why":"influence behaves like a solute: the same amount spread through more volume acts more weakly at any one point.","whyCN":"影响力像溶质：同样的量摊进更大体积，在任一点上的作用就更弱。"},{"no":"04","title":"To weaken taste, colour or feeling","titleCN":"冲淡味道、颜色或情感","definition":"to make a quality fainter by mixing it with something neutral","definitionCN":"通过与中性之物混合使某种性质变淡","example":"Too much water diluted the taste of the tea.","exampleCN":"水太多，把茶味冲淡了。","why":"taste and colour are intensities carried in a liquid, so adding liquid lowers them just as it lowers concentration.","whyCN":"味道与颜色是液体承载的强度，加水会像降低浓度一样把它们压低。"},{"no":"05","title":"Weakened by water, as an adjective","titleCN":"形容词：稀释过的、浓度低的","definition":"having had water added, so that the substance is present at low strength","definitionCN":"已加水，使物质以低强度存在","example":"A dilute solution of bleach is safe on the floor.","exampleCN":"稀释的漂白液用在地面上是安全的。","why":"the adjective is the same form, describing the state that the verb has produced.","whyCN":"形容词是同一形式，描述动词造成的那种状态。"},{"no":"06","title":"To make a promise less forceful","titleCN":"使承诺或主张变得无力","definition":"to take the force out of a statement, promise or claim by adding qualifications or compromises","definitionCN":"通过附加条件或折中，抽掉陈述、承诺或主张的力量","example":"The final clause diluted the promise of reform.","exampleCN":"最后一条款把改革的承诺冲淡了。","why":"a claim is strong when nothing neutral is mixed in, so hedging works like adding water to a statement.","whyCN":"主张在没有掺入中性成分时最强，因此含糊其辞就像给陈述加水。"},{"no":"07","title":"To reduce each shareholder's stake","titleCN":"稀释每股股权","definition":"to reduce the proportion of a company owned by existing shareholders by issuing more shares","definitionCN":"通过发行更多股份，降低现有股东所占的公司比例","example":"Issuing new shares diluted existing holdings.","exampleCN":"发行新股稀释了现有持股。","why":"ownership is a share of a fixed whole, so adding more shares spreads the same company over more claims.","whyCN":"所有权是对一个固定整体的份额，增发股份就把同一家公司摊到更多索取权上。"},{"no":"08","title":"To spread intensity until it fades","titleCN":"抽象义：把强度摊到更大范围直至变淡","definition":"used figuratively of any intensity that loses force when spread over more time, space or recipients","definitionCN":"比喻指任何强度因摊到更多时间、空间或对象而失去力量","example":"Praise repeated too often is diluted into noise.","exampleCN":"赞美重复太多，就被冲淡成噪音。","why":"the abstract sense keeps the arithmetic of dilution: the same amount divided among more units counts for less in each.","whyCN":"抽象义保留了稀释的算术：同样的量分给更多单位，每一份就更少。"}],"etymology":{"intro":{"en":"Dilute comes from the Latin past participle dilutus, from diluere 'to wash away, dissolve, dilute', built on dis- 'apart' plus -luere, the combining form of lavere 'to wash'. It is recorded in English from the fifteenth century. Dates are approximate.","cn":"dilute 来自拉丁过去分词 dilutus，出自 diluere「冲走、溶解、稀释」，由 dis-「分开」加 -luere 构成，后者是 lavere「洗」的组合形式。英语自十五世纪有记录。年代均为约数。"},"items":[{"era":"LATIN LAVERE","en":"Lavere meant 'to wash'; its combining form -luere appears in diluere and in words about flooding, and its older root is reconstructed as a verb of washing.","cn":"lavere 意为「洗」，其组合形式 -luere 出现在 diluere 以及表示洪水的词中，其更古老词根被重构为一个表示「洗」的动词。"},{"era":"LATIN DILUERE","en":"Dis- 'apart' plus -luere gave diluere 'to wash away, to dissolve, to dilute', the image being strength carried off into a larger body of water.","cn":"dis-「分开」加 -luere 构成 diluere「冲走、溶解、稀释」，画面是强度被带进更大一片水里。"},{"era":"LATIN DILUTUS","en":"The past participle dilutus 'washed away, diluted' is the direct source of the English adjective and of the verb built on it.","cn":"过去分词 dilutus「被冲走的、被稀释的」是英语形容词及由此构成的动词的直接来源。"},{"era":"ENGLISH VERB","en":"From the fifteenth century English dilute meant to weaken a liquid by adding water, first in medicine and then in general use.","cn":"自十五世纪起，英语 dilute 指加水使液体变弱，先在医学中使用，后进入一般用法。"},{"era":"FIGURATIVE USE","en":"By the seventeenth century the verb described weakened power, claims and ownership, where the same arithmetic of spreading holds.","cn":"到十七世纪，这个动词已用于被削弱的权力、主张与所有权，因为「摊开」的算术是一样的。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin shape of the washing root is a reconstruction, and its exact first English citation is not recorded. Note that this root is not the luere 'to loosen' behind soluble.","cn":"来源不确定（更深词源）：表示「洗」的词根在拉丁语之前的形式属于重构，英语最早书证没有确切记录。需注意这个词根并非 soluble 背后表示「松开」的 luere。"}]},"similar":{"note":{"en":"Group one holds look-alikes whose roots are different despite similar spelling; group two holds verbs for making something weaker.","cn":"第一组是拼写相近而词根不同的形近词；第二组是表示使某物变弱的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dilution","ipa":"/dɪˈljuːʃn/","tag":"the noun of the action","definition":"The act or result of diluting; it is the noun built on this verb, not a separate root.","definitionCN":"稀释的动作或结果；由这个动词构成的名词，并非另一个词根。"},{"word":"dissolve","ipa":"/dɪˈsɒlv/","tag":"different root and different act","definition":"To break a solid apart into a liquid; dilute does not dissolve anything, it only lowers the strength of what is already dissolved.","definitionCN":"把固体拆散进液体；dilute 不溶解任何东西，只降低已溶解物的强度。"},{"word":"dilate","ipa":"/daɪˈleɪt/","tag":"looks close, different root","definition":"From Latin latus 'wide': to widen or expand, as a pupil or an artery does; it has nothing to do with washing.","definitionCN":"出自拉丁 latus「宽」：使变宽、扩张，如瞳孔或动脉；与「洗」无关。"},{"word":"deluge","ipa":"/dɪˈluːdʒ/","tag":"same washing root, a flood","definition":"From diluvium, a flood: water overwhelming everything, which is the violent version of the same washing image.","definitionCN":"出自 diluvium「洪水」：水淹没一切，是同一「冲洗」意象的猛烈版本。"}]},{"heading":"NEAR MEANING","entries":[{"word":"weaken","ipa":"/ˈwiːkən/","tag":"general word","definition":"The broad verb for making anything less strong, with no image of water.","definitionCN":"使任何事物变弱的通用动词，不含水的意象。"},{"word":"thin","ipa":"/θɪn/","tag":"consistency, not strength","definition":"To make a liquid less thick, as paint with turpentine; it changes consistency rather than concentration.","definitionCN":"使液体变稀薄，如用松节油调漆；改变的是稠度，而非浓度。"},{"word":"water down","ipa":"/ˌwɔːtə ˈdaʊn/","tag":"the everyday phrase","definition":"The plain phrase for adding water, and also for softening a statement; dilute is its formal counterpart.","definitionCN":"加水的日常说法，也指软化表述；dilute 是其正式对应词。"},{"word":"attenuate","ipa":"/əˈtenjueɪt/","tag":"technical weakening","definition":"To reduce the strength of a signal, a virus or a force; common in physics and medicine rather than in cookery.","definitionCN":"降低信号、病毒或力量的强度；多用于物理与医学，而非厨房。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Diluere 'to wash away': water carries the strength off into a larger volume.","cn":"diluere「冲走」：水把强度带进更大的体积。"},{"en":"The family runs dilute, dilution, diluent, diluted, undiluted.","cn":"同族词包括 dilute、dilution、diluent、diluted、undiluted。"},{"en":"Fixed phrases mark the chemical sense: dilute acid, dilute a solution.","cn":"固定搭配标出化学义：稀酸、稀释溶液。"},{"en":"The figurative phrases mark the rest: dilute the effect, dilute ownership, dilute the message.","cn":"比喻搭配标出其余义项：削弱效果、稀释所有权、冲淡信息。"},{"en":"Remember the root is 'wash', not 'loosen': do not tie it to dissolve or soluble.","cn":"记住词根是「洗」而不是「松开」：不要把它与 dissolve 或 soluble 系在一起。"}],"abstract":[{"en":"Picture a spoon of dark syrup turning a whole jug pale brown.","cn":"想象一勺深色糖浆把整壶水染成浅褐。"},{"en":"Picture applause spread thin over an hour until it sounds like background noise.","cn":"想象掌声摊薄在一小时里，最后听起来像背景噪音。"},{"en":"Picture one strong voice split among a hundred speakers.","cn":"想象一个洪亮的声音被分给一百个人。"}]},"examples":[{"en":"Always dilute the cleaning fluid before pouring it down the drain.","cn":"把清洁液倒进排水口前一定要先稀释。"},{"en":"The new partners diluted the founder's share to less than half.","cn":"新合伙人把创始人的股份稀释到不足一半。"},{"en":"Repeating the slogan at every stop diluted its effect.","cn":"每到一站都重复这句口号，反而削弱了它的效果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「di（分开）+ lute（冲）」——把浓的冲散开：稀释、冲淡、削弱","word":"dilute"},"root":"拉丁 diluere「冲走、稀释」的过去分词 dilutus = dis-（分开）+ -luere（洗，源自 lavere「洗」）；与 soluble 背后表示「松开」的 luere 并非同一词根。","sensesIntro":{"en":"Eight senses follow one washing away: water lowers a concentration, a sample is made testable, power is spread thin, taste and colour fade, the adjective names the weakened state, a promise loses force, shares are spread over more owners, and finally any intensity fades as it is divided.","cn":"八个义项跟着同一次「冲走」：水降低浓度，样品被调到可测，权力被摊薄，味道与颜色变淡，形容词命名被削弱的状态，承诺失去力量，股份被摊到更多持有人，最后任何强度都因被分割而变淡。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small cup of dark juice poured into a large jug of clear water until the colour turns pale.","cn":"核心意象：一小杯深色果汁倒进一大壶清水，颜色直到变浅。"},"chain":["WASHED AWAY","LOWER CONCENTRATION","SAMPLE MADE TESTABLE","POWER SPREAD THIN","TASTE FADES","INTENSITY DIVIDED"],"branches":[{"senses":"01 · 02","en":"LOWERING STRENGTH: domestic dilution and laboratory dilution are one act at two scales.","cn":"降低强度：日常稀释与实验室稀释，是同一动作的两个尺度。"},{"senses":"03 · 07","en":"SPREAD AMONG MORE HOLDERS: influence and shares both lose force when divided among more parties.","cn":"摊给更多持有者：影响力与股份一旦分给更多方，都会失去力量。"},{"senses":"04 · 06","en":"FAINT QUALITIES: taste, colour and the force of a promise all fade when something neutral is mixed in.","cn":"变淡的性质：味道、颜色与承诺的力量，都会因掺入中性之物而减退。"},{"senses":"05","en":"THE WEAKENED STATE: the adjective simply names what the verb has already done.","cn":"被削弱的状态：形容词只是命名动词已经做成的事。"},{"senses":"08","en":"DIVIDED INTENSITY: any strength spread over more time or recipients counts for less at each point.","cn":"被分割的强度：任何强度摊到更多时间或对象上，每一点的分量都更少。"}]},"affixes":{"intro":{"en":"Dilute is a Latin verb made of a prefix and a root of washing, and the same pieces build the rest of its family.","cn":"dilute 是一个由前缀与「洗」词根构成的拉丁动词，同样的部分构成它其余的家族。"},"latinIntro":{"en":"Dis- 'apart' plus -luere 'to wash' gives diluere and its participle dilutus; the same washing root appears in deluge and diluvial, not in dissolve.","cn":"dis-「分开」加 -luere「洗」构成 diluere 及其分词 dilutus；同一「洗」词根出现在 deluge 与 diluvial 中，而不在 dissolve 中。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart, away')","meaning":"apart; away","meaningCN":"分开；离开","example":"The prefix sends the strength away into the water.","exampleCN":"这个前缀把强度送进水里。"},{"word":"lavere","structure":"lavere (Latin verb, 'to wash')","meaning":"to wash","meaningCN":"洗","example":"The root supplies the washing image.","exampleCN":"这个词根提供「洗」的意象。"},{"word":"-luere","structure":"-luere (combining form of lavere)","meaning":"to wash","meaningCN":"洗","example":"Only the combining form appears inside diluere.","exampleCN":"在 diluere 内部只出现组合形式。"},{"word":"diluere","structure":"dis- + -luere","meaning":"to wash away, to dilute","meaningCN":"冲走；稀释","example":"The Latin verb begins the family.","exampleCN":"这个拉丁动词开启词族。"},{"word":"dilute","structure":"dilutus -> dilute","meaning":"to weaken with water","meaningCN":"加水使变弱","example":"Dilute the paint before the second coat.","exampleCN":"上第二遍前把漆稀释。"},{"word":"dilution","structure":"dilute + -ion (action or result)","meaning":"the act or result of diluting","meaningCN":"稀释；稀释结果","example":"Two dilutions brought the sample into range.","exampleCN":"两次稀释把样品调进了量程。"},{"word":"diluent","structure":"dilute + -ent (that which does)","meaning":"a substance used to dilute","meaningCN":"稀释剂","example":"Water is the cheapest diluent here.","exampleCN":"水是这里最便宜的稀释剂。"},{"word":"diluted","structure":"dilute + -ed (past participle)","meaning":"having been made weaker","meaningCN":"已被稀释的","example":"The diluted bleach was safe to use.","exampleCN":"稀释过的漂白液可以安全使用。"},{"word":"undiluted","structure":"un- (not) + diluted","meaning":"not weakened by water","meaningCN":"未稀释的；纯粹的","example":"He drank the juice undiluted.","exampleCN":"他没兑水就把果汁喝了。"},{"word":"deluge","structure":"diluvium, from dis- + -luere","meaning":"a flood","meaningCN":"洪水","example":"The storm brought a deluge to the valley.","exampleCN":"暴风雨给山谷带来一场洪水。"}],"latinEntries":[{"word":"lavere","structure":"lavere, lavi, lautum (verb, third conjugation)","meaning":"to wash","meaningCN":"洗"},{"word":"diluere","structure":"diluere, dilui, dilutum (verb, third conjugation)","meaning":"to wash away, dilute","meaningCN":"冲走；稀释"},{"word":"dilutus","structure":"dilutus, diluta, dilutum (past participle)","meaning":"washed away, diluted","meaningCN":"被冲走的；被稀释的"},{"word":"diluvium","structure":"diluvium, diluvii (n., second declension)","meaning":"a flood","meaningCN":"洪水"}]}},{"word":"dilution","ipa_uk":"/dɪˈljuːʃn/","ipa_us":"/dɪˈluːʃn/","definition_zh":"稀释；稀释液；效力削弱；股权稀释","definition_en":"the act or result of making a liquid weaker, or the weakening of power, value or effect","core_image":"一桶深色染料倒进河水，颜色顺着水流一段段变淡，直到看不见","scene":"河边的工厂把一桶深色染料倒进水流，颜色在下游几百米处几乎看不见了。The dilution of the dye was visible within a few hundred metres of the outflow.","sceneCN":"这里 dilution 指把浓液与水混合、使颜色变淡的过程与结果（第 1 个义项：稀释过程）；句意为染料排出后几百米内就明显被稀释。图中可辨识物件：染料桶、河水、下游水面、取样瓶。","pos":[{"tag":"n.","zh":"稀释；稀释液（可数或不可数）"},{"tag":"n.","zh":"（效力、价值、股权的）削弱、稀释"}],"collocations":[{"phrase":"serial dilution","zh":"梯度稀释"},{"phrase":"a dilution of one in ten","zh":"一比十的稀释"},{"phrase":"dilution of authority","zh":"权力的削弱"},{"phrase":"share dilution","zh":"股份稀释"},{"phrase":"brand dilution","zh":"品牌稀释"},{"phrase":"dilution rate","zh":"稀释率"}],"forms":[{"label":"单数","form":"dilution"},{"label":"复数（多次或多种稀释）","form":"dilutions"},{"label":"动词","form":"dilute"},{"label":"形容词","form":"diluted"},{"label":"名词（稀释剂）","form":"diluent"},{"label":"反义名词","form":"concentration"}],"derivatives":[{"word":"dilute","pos":"v./adj.","zh":"稀释／稀释的"},{"word":"diluted","pos":"adj.","zh":"稀释过的"},{"word":"diluent","pos":"n./adj.","zh":"稀释剂／稀释的"},{"word":"undiluted","pos":"adj.","zh":"未稀释的"},{"word":"dilutable","pos":"adj.","zh":"可稀释的"}],"senses":[{"no":"01","title":"The act of making a liquid weaker","titleCN":"把液体调稀的动作","definition":"the process of adding water or another solvent so that the active substance is spread through a larger volume","definitionCN":"加入水或其他溶剂，使有效物质分布到更大体积中的过程","example":"Repeated dilution brought the acid to a safe strength.","exampleCN":"反复稀释把酸的强度降到安全范围。","why":"dilution is the noun of dilute, from Latin diluere 'to wash away', so it names the washing-out of strength.","whyCN":"dilution 是 dilute 的名词，出自拉丁 diluere「冲走」，命名的是把强度冲走这件事。"},{"no":"02","title":"The weakened state or ratio","titleCN":"稀释后的状态或比例","definition":"the resulting strength of a mixture, often expressed as a ratio of one part to so many parts","definitionCN":"混合后所得的强度，常以一比若干的比例表示","example":"The sample was tested at a dilution of one in ten.","exampleCN":"样品按一比十的稀释度接受检测。","why":"once the act is done, the word also names the measurable outcome, because chemistry reports both in the same noun.","whyCN":"动作做完后，这个词也命名可测的结果，因为化学用同一个名词报告两者。"},{"no":"03","title":"A prepared weak liquid","titleCN":"配好的稀释液","definition":"a quantity of weakened liquid prepared for a particular use, such as a medicine or a cleaning fluid","definitionCN":"为特定用途配好的一定量的弱液，如药液或清洁液","example":"The nurse prepared a dilution of the medicine in water.","exampleCN":"护士用水配好了一份稀释药液。","why":"the noun shifts from the act to the thing made, since a prepared dilution can be carried, stored and poured.","whyCN":"名词从动作转向做成的东西，因为配好的稀释液可以被携带、存放和倒出。"},{"no":"04","title":"The thinning of authority","titleCN":"权威被削弱","definition":"the reduction of the force of authority or influence by spreading it among more people or bodies","definitionCN":"把权威或影响力分散给更多人或机构，使其力量下降","example":"The dilution of the committee's authority was gradual.","exampleCN":"委员会权威的削弱是渐进的。","why":"the arithmetic of dilution transfers directly: one strong voice divided among many counts for less in each place.","whyCN":"稀释的算术可以直接搬过来：一个强声音分给许多人，每处的分量就更少。"},{"no":"05","title":"The spreading of ownership","titleCN":"股权稀释","definition":"the reduction of each existing shareholder's proportion of a company when new shares are issued","definitionCN":"发行新股时，现有股东每人所占公司比例的下降","example":"The share issue caused a dilution of existing holdings.","exampleCN":"这次发行新股造成了现有持股的稀释。","why":"a company is a fixed whole, so issuing more claims over it divides the same value into smaller pieces.","whyCN":"公司是一个固定的整体，增发索取权就把同一份价值切成更小的块。"},{"no":"06","title":"The fading of a brand or a value","titleCN":"品牌或价值的稀释","definition":"the loss of distinctiveness or perceived value caused by overuse, copying or too many extensions","definitionCN":"因过度使用、仿制或过多延伸而失去辨识度或公认价值","example":"Too many licensed products caused brand dilution.","exampleCN":"授权产品过多导致品牌稀释。","why":"a name is strong when it stands for one thing, and spreading it over everything thins what it stands for.","whyCN":"名称因专指一物而有力，把它摊到一切东西上，所指就变薄了。"},{"no":"07","title":"Fading of colour or taste","titleCN":"颜色或味道的冲淡","definition":"the loss of intensity in colour, flavour or feeling after mixing with something neutral","definitionCN":"与中性之物混合后，颜色、味道或感受失去强度","example":"The dilution of the colour made the sunset look pale.","exampleCN":"颜色的冲淡让那场日落显得苍白。","why":"colour and taste are carried in a medium, so adding medium lowers the intensity exactly as it lowers concentration.","whyCN":"颜色与味道由介质承载，增加介质就会像降低浓度一样降低强度。"},{"no":"08","title":"A message spread until it is weak","titleCN":"抽象义：信息或主张被摊薄","definition":"the loss of force in a message, warning or argument repeated or spread too widely","definitionCN":"信息、警告或论证因重复过多或传播过广而失去力量","example":"Repeating the warning led to a dilution of its force.","exampleCN":"反复重复警告反而削弱了它的力量。","why":"attention is a fixed quantity like volume, and the same warning spread over every channel lands with less weight in each.","whyCN":"注意力像体积一样是定量，同一警告摊到每个渠道，落在每处的分量都更轻。"}],"etymology":{"intro":{"en":"Dilution is dilute plus -ion, modelled on Latin dilutio 'a washing away'. English has used the noun since the seventeenth century for both the process and the weakened product. Dates are approximate.","cn":"dilution 是 dilute 加 -ion 构成，仿拉丁 dilutio「冲走」。英语自十七世纪起用这个名词兼指过程与被稀释的产物。年代均为约数。"},"items":[{"era":"LATIN LAVERE","en":"Lavere 'to wash' supplies the combining form -luere, and its deeper root is reconstructed as a verb of washing rather than recorded in that shape.","cn":"lavere「洗」提供组合形式 -luere，其更深词根被重构为一个表示「洗」的动词，而非以该形态被记录。"},{"era":"LATIN DILUERE","en":"Dis- 'apart' plus -luere gave diluere 'to wash away, dilute', the image of strength carried off into a larger body of water.","cn":"dis-「分开」加 -luere 构成 diluere「冲走、稀释」，画面是强度被带进更大一片水。"},{"era":"LATIN DILUTIO","en":"The abstract noun dilutio named the act of washing away or diluting, and English rebuilt the same type of noun with -ion.","cn":"抽象名词 dilutio 命名冲走或稀释的动作，英语用 -ion 重建了同类名词。"},{"era":"ENGLISH CHEMISTRY","en":"Seventeenth-century laboratory writing fixed dilution as the standard word for lowering concentration, and it soon covered prepared weak liquids as well.","cn":"十七世纪的实验室写作把 dilution 固定为降低浓度的标准词，很快也覆盖配好的弱液。"},{"era":"FINANCE AND BRANDS","en":"Modern finance speaks of share dilution, and marketing of brand dilution, both applying the same image of value spread thin.","cn":"现代金融说股份稀释，营销说品牌稀释，两者都套用「价值被摊薄」的同一意象。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin shape of the washing root is a reconstruction, and no exact date is recorded for the first English use of the financial sense.","cn":"来源不确定（更深词源）：表示「洗」的词根在拉丁语之前的形式属于重构；金融义最早的英语使用没有确切年代记录。"}]},"similar":{"note":{"en":"Group one holds the verb and its relatives, which name the act rather than the result; group two holds words for weakening and its opposite.","cn":"第一组是动词及其亲属，命名动作而非结果；第二组是表示削弱及其反向的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dilute","ipa":"/dɪˈljuːt/","tag":"the verb","definition":"The action itself: to add water and lower the strength; dilution is what the action produces or measures.","definitionCN":"动作本身：加水降低强度；dilution 是动作所产生或所量出的东西。"},{"word":"diluent","ipa":"/dɪˈljuːənt/","tag":"the added substance","definition":"The water or solvent that is added, not the resulting mixture.","definitionCN":"被加进去的水或溶剂，而非所得的混合物。"},{"word":"dissolution","ipa":"/dɪˈsəluːʃn/","tag":"different root sense","definition":"The breaking up of a solid or an organization; it shares a Latin look but belongs to solvere 'to loosen', not to diluere 'to wash'.","definitionCN":"固体或组织的解体；拉丁外形相近，但属于 solvere「松开」，不属 diluere「洗」。"},{"word":"deluge","ipa":"/dɪˈluːdʒ/","tag":"same washing root","definition":"A flood, from diluvium; it is the violent form of the same washing image behind dilution.","definitionCN":"洪水，出自 diluvium；它是 dilution 背后同一「冲洗」意象的猛烈形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"concentration","ipa":"/ˌkɒnsənˈtreɪʃn/","tag":"the opposite measure","definition":"The amount of substance present in a volume; dilution lowers it, so the two words are read as a pair.","definitionCN":"单位体积中物质的含量；稀释降低它，因此两个词成对阅读。"},{"word":"attenuation","ipa":"/ˌætenjuˈeɪʃn/","tag":"technical weakening","definition":"The reduction of a signal, a virus or a force; common in physics and medicine, with no image of water.","definitionCN":"信号、病毒或力量的减弱；多见于物理与医学，不含水的意象。"},{"word":"weakening","ipa":"/ˈwiːkənɪŋ/","tag":"plain general word","definition":"The everyday noun for any loss of strength, used where dilution would sound technical.","definitionCN":"任何力量丧失的日常名词，在 dilution 显得太技术化时使用。"},{"word":"reduction","ipa":"/rɪˈdʌkʃn/","tag":"broad and neutral","definition":"A general lowering of amount, size or strength; dilution is a reduction caused specifically by adding liquid.","definitionCN":"数量、规模或强度的总体下降；dilution 特指由加液造成的下降。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Dilute plus -ion: the ending turns the act into a name.","cn":"dilute 加 -ion：结尾把动作变成名称。"},{"en":"The family runs dilute, dilution, diluent, diluted, undiluted.","cn":"同族词包括 dilute、dilution、diluent、diluted、undiluted。"},{"en":"Laboratory phrases mark the measured sense: serial dilution, a dilution of one in ten.","cn":"实验室说法标出测量义：梯度稀释、一比十的稀释。"},{"en":"Modern phrases mark the figurative senses: share dilution, brand dilution, dilution of authority.","cn":"现代说法标出比喻义：股份稀释、品牌稀释、权威削弱。"},{"en":"Its opposite is concentration, the ceiling against the lowered level.","cn":"它的反面是 concentration，即降低后的水平所对照的上限。"}],"abstract":[{"en":"Picture a dark drop in a river, fading with every metre downstream.","cn":"想象一滴深色墨在河里，每往下一米就淡一分。"},{"en":"Picture one voice handed to a chorus until nobody can hear it alone.","cn":"想象一个声音被交给合唱队，最后谁也听不出它。"},{"en":"Picture a famous name printed on every cheap object until it means nothing.","cn":"想象一个名牌被印在每件廉价商品上，直到它什么也不代表。"}]},"examples":[{"en":"Serial dilution is the standard way to bring a strong sample into the range of the instrument.","cn":"梯度稀释是把过强样品调进仪器量程的标准方法。"},{"en":"The dilution of the paint with solvent made the second coat too pale.","cn":"用溶剂稀释油漆，使第二遍涂层颜色过淡。"},{"en":"Analysts warned that the new shares would cause dilution for existing owners.","cn":"分析师警告新股会使现有股东权益被稀释。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「di（分开）+ lu（流）+ tion」——把浓的冲散流开：稀释、削弱","word":"dilution"},"root":"拉丁 dilutio「冲走、稀释」= diluere（冲走）+ -io（动作名词）；diluere 由 dis-（分开）+ -luere（洗，源自 lavere）构成。英语以 dilute + -ion 构成。","sensesIntro":{"en":"Eight senses follow one washing away: a liquid is made weaker, the result is measured as a ratio, a prepared weak liquid is stored, authority and ownership are spread thin, a brand loses its edge, colour fades, and a message repeated everywhere loses force.","cn":"八个义项跟着同一次「冲走」：液体被调稀，结果被量成比例，配好的弱液被存放，权威与所有权被摊薄，品牌失去锋芒，颜色变淡，最后是到处重复的信息失去力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bucket of dark dye poured into a river, fading with every metre of flow.","cn":"核心意象：一桶深色染料倒进河里，随着水流每米变淡。"},"chain":["WASHED AWAY","MEASURED RATIO","PREPARED WEAK LIQUID","AUTHORITY THINNED","BRAND FADED","MESSAGE SPREAD THIN"],"branches":[{"senses":"01 · 02","en":"ACT AND MEASURE: the process of adding liquid and the ratio that records it are two halves of one operation.","cn":"动作与量度：加液过程与记录它的比例，是同一次操作的两半。"},{"senses":"03","en":"THE MADE PRODUCT: a prepared weak liquid is the act stored in a bottle.","cn":"做成的产物：配好的弱液就是把动作装进了瓶子。"},{"senses":"04 · 05","en":"AUTHORITY AND SHARES: both are fixed wholes divided among more holders.","cn":"权威与股份：两者都是被分给更多持有者的固定整体。"},{"senses":"06","en":"BRAND VALUE: a name spread over too much stops standing for one thing.","cn":"品牌价值：名称摊到太多东西上，就不再专指一物。"},{"senses":"07 · 08","en":"FAINT QUALITIES: colour, taste and the force of a message all fade as they are spread.","cn":"变淡的性质：颜色、味道与信息的力量，都在摊开时变淡。"}]},"affixes":{"intro":{"en":"Dilution is a Latin verb plus a Latin noun ending, and the washing root still shapes the whole family.","cn":"dilution 是一个拉丁动词加上一个拉丁名词词尾，表示「洗」的词根仍塑造整个家族。"},"latinIntro":{"en":"-io becomes -ion in English and names an action or its result; dis- 'apart' plus -luere 'wash' gives dilute, diluent and dilution.","cn":"-io 在英语中变为 -ion，表示动作或其结果；dis-「分开」加 -luere「洗」构成 dilute、diluent 与 dilution。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart')","meaning":"apart; away","meaningCN":"分开；离开","example":"The prefix carries the strength away into the water.","exampleCN":"这个前缀把强度带进水里。"},{"word":"-luere","structure":"-luere (combining form of lavere, 'to wash')","meaning":"to wash","meaningCN":"洗","example":"The root supplies the image of washing out.","exampleCN":"这个词根提供「冲走」的意象。"},{"word":"diluere","structure":"dis- + -luere","meaning":"to wash away, dilute","meaningCN":"冲走；稀释","example":"The Latin verb begins the family.","exampleCN":"这个拉丁动词开启词族。"},{"word":"dilutio","structure":"diluere + -io (action noun)","meaning":"a washing away; a dilution","meaningCN":"冲走；稀释","example":"The Latin noun matches the English one.","exampleCN":"这个拉丁名词与英语名词对应。"},{"word":"-ion","structure":"-ion (from Latin -io, action or result)","meaning":"an act or its result","meaningCN":"动作或其结果","example":"The suffix makes dilution a process and a product.","exampleCN":"这个后缀让 dilution 既是过程也是产物。"},{"word":"dilute","structure":"dilutus -> dilute","meaning":"to weaken with water","meaningCN":"加水使变弱","example":"Dilute the sample before it is tested.","exampleCN":"检测前先稀释样品。"},{"word":"dilution","structure":"dilute + -ion","meaning":"the act or result of diluting","meaningCN":"稀释；稀释结果","example":"A tenfold dilution was prepared.","exampleCN":"配制了十倍稀释液。"},{"word":"dilutions","structure":"dilution + -s (plural)","meaning":"several diluted samples","meaningCN":"多份稀释液","example":"Three dilutions were compared.","exampleCN":"比较了三份稀释液。"},{"word":"diluent","structure":"dilute + -ent (agent)","meaning":"the substance added to dilute","meaningCN":"稀释剂","example":"The diluent must be sterile.","exampleCN":"稀释剂必须无菌。"},{"word":"diluted","structure":"dilute + -ed","meaning":"made weaker","meaningCN":"已稀释的","example":"The diluted sample was clear.","exampleCN":"稀释后的样品是清的。"}],"latinEntries":[{"word":"diluere","structure":"diluere, dilui, dilutum (verb, third conjugation)","meaning":"to wash away, dilute","meaningCN":"冲走；稀释"},{"word":"dilutio","structure":"dilutio, dilutionis (f., third declension)","meaning":"a washing away, a dilution","meaningCN":"冲走；稀释"},{"word":"dilutus","structure":"dilutus, diluta, dilutum (past participle)","meaning":"washed away, diluted","meaningCN":"被冲走的；被稀释的"},{"word":"lavere","structure":"lavere, lavi, lautum (verb, third conjugation)","meaning":"to wash","meaningCN":"洗"}]}},{"word":"saturation","ipa_uk":"/ˌsætʃəˈreɪʃn/","ipa_us":"/ˌsætʃəˈreɪʃn/","definition_zh":"饱和（状态）；饱和作用；市场饱和；色彩饱和度","definition_en":"the state of being filled to capacity so that nothing more can be absorbed, or the act of filling something completely","core_image":"一块干海绵吸到滴水不出，再倒水只能从表面流走","scene":"桌上放着一块吸满水的海绵，再倒水时水直接从边缘流到盘子里。The sponge reached saturation and could hold no more water.","sceneCN":"这里 saturation 指再也吸收不了更多物质的状态（第 1 个义项：饱和状态）；句意为海绵已到饱和，再也吸不进更多水。图中可辨识物件：海绵、水杯、托盘、流下的水。","pos":[{"tag":"n.","zh":"饱和状态；饱和作用（不可数）"},{"tag":"n.","zh":"（市场、信息等的）饱和；色彩饱和度"}],"collocations":[{"phrase":"reach saturation","zh":"达到饱和"},{"phrase":"market saturation","zh":"市场饱和"},{"phrase":"saturation point","zh":"饱和点"},{"phrase":"colour saturation","zh":"色彩饱和度"},{"phrase":"saturation of the soil","zh":"土壤的饱和"},{"phrase":"magnetic saturation","zh":"磁饱和"}],"forms":[{"label":"不可数名词","form":"saturation"},{"label":"动词","form":"saturate"},{"label":"形容词","form":"saturated"},{"label":"反义名词（不饱和）","form":"unsaturation"},{"label":"相关形容词","form":"supersaturated"},{"label":"相关名词（饱和点）","form":"saturation point"}],"derivatives":[{"word":"saturate","pos":"v.","zh":"使饱和；浸透"},{"word":"saturated","pos":"adj.","zh":"饱和的；浸透的"},{"word":"unsaturated","pos":"adj.","zh":"不饱和的"},{"word":"supersaturation","pos":"n.","zh":"过饱和"},{"word":"saturant","pos":"n.","zh":"饱和剂（罕用）"}],"senses":[{"no":"01","title":"A solution that can take no more","titleCN":"溶液不能再溶解更多溶质的状态","definition":"the point at which a liquid holds as much dissolved solid as it can at a given temperature","definitionCN":"在给定温度下，液体已容纳尽可能多溶解固体的那一点","example":"Saturation is reached when no more salt will dissolve.","exampleCN":"当盐再也溶不进去时，就达到了饱和。","why":"saturation comes from saturare 'to fill', so the word names a container that is full rather than a substance that is strong.","whyCN":"saturation 出自 saturare「填满」，这个词命名的是被装满的容器，而不是浓度高的物质。"},{"no":"02","title":"The process of becoming full","titleCN":"达到饱和的过程","definition":"the process by which a material takes in liquid or another substance until it can take no more","definitionCN":"材料吸收液体或其他物质直到再也吸不进去的过程","example":"The saturation of the soil took three days of rain.","exampleCN":"土壤吸透用了三天的雨。","why":"the noun covers the filling as well as the filled state, since English often names both with one -ion form.","whyCN":"这个名词既覆盖填充过程，也覆盖填满状态，因为英语常用一个 -ion 形式兼指两者。"},{"no":"03","title":"A market with no room to grow","titleCN":"市场饱和","definition":"the state in which demand has been met so fully that further growth is difficult","definitionCN":"需求已被充分满足、进一步增长困难的状态","example":"The market reached saturation within two years.","exampleCN":"这个市场两年内就饱和了。","why":"a market is treated as a container of demand, and when every buyer is filled the container is saturated.","whyCN":"市场被当作需求的容器，买主都被填满后，这个容器就饱和了。"},{"no":"04","title":"Full intensity of colour","titleCN":"色彩饱和度","definition":"the purity or intensity of a colour, from grey at the lowest to vivid at the highest","definitionCN":"颜色的纯度或强度，从最低的灰到最高的鲜艳","example":"The photograph was adjusted for higher saturation.","exampleCN":"这张照片被调高了饱和度。","why":"a colour is pictured as a vessel that can hold more or less pigment, so its fullness is named saturation.","whyCN":"颜色被想象成可容纳多少色素的容器，因此它的饱满程度被命名为饱和度。"},{"no":"05","title":"The limit of a magnetic material","titleCN":"磁饱和","definition":"the state in which a magnetic material cannot be made more strongly magnetized by any further increase in current","definitionCN":"磁材料无论电流再怎么增加也无法磁得更强的状态","example":"The core entered saturation and the current rose sharply.","exampleCN":"铁芯进入磁饱和，电流急剧上升。","why":"magnetism is pictured as a capacity that fills up, so the technical limit uses the same word as a full sponge.","whyCN":"磁性被想象成一种会被填满的容量，因此技术上的极限与吸满的海绵共用同一个词。"},{"no":"06","title":"The state of being soaked through","titleCN":"浸透、湿透","definition":"the condition of a material that has absorbed as much water as its structure allows","definitionCN":"材料已吸收其结构所能容纳的最多水分的状态","example":"Saturation of the cloth made it twice as heavy.","exampleCN":"布浸透后重量翻了一倍。","why":"soaking is literal filling, so it is the clearest everyday picture of saturation.","whyCN":"浸湿就是字面意义上的填满，因此它是饱和最清楚的日常画面。"},{"no":"07","title":"Too much information in circulation","titleCN":"信息或媒体的饱和","definition":"the condition in which messages, advertisements or data are so plentiful that each receives little attention","definitionCN":"信息、广告或数据多到每条都得不到多少注意的状态","example":"Viewers suffer from saturation of advertising.","exampleCN":"观众被过量的广告淹没。","why":"attention is a fixed vessel, and when messages fill it there is no room for one more.","whyCN":"注意力是一个固定容器，信息把它填满后，就再装不下一条。"},{"no":"08","title":"A life or schedule with no room left","titleCN":"抽象义：被填满而无余地","definition":"used figuratively of a schedule, a mind or a life filled so completely that nothing more can be added","definitionCN":"比喻指日程、头脑或生活被填得极满，再也加不进东西","example":"The saturation of his schedule left no room for rest.","exampleCN":"日程排得极满，没给休息留下一点空间。","why":"the abstract sense keeps the container image and simply replaces water with obligations.","whyCN":"抽象义保留容器意象，只是把水换成了义务。"}],"etymology":{"intro":{"en":"Saturation comes from Late Latin saturatio, from saturare 'to fill, satisfy', from satur 'full' and satis 'enough'. It is recorded in English from the fifteenth century. Dates are approximate.","cn":"saturation 来自晚期拉丁 saturatio，出自 saturare「填满、使满足」，再上溯 satur「满的」与 satis「足够」。英语自十五世纪有记录。年代均为约数。"},"items":[{"era":"LATIN SATIS","en":"Satis meant 'enough'. Its deeper origin is reconstructed as a root of satisfying, and no form of that root is recorded directly.","cn":"satis 意为「足够」。其更深来源被重构为一个表示「满足」的词根，该词根没有任何形式被直接记录。"},{"era":"LATIN SATUR","en":"From satis came satur 'full, sated', used of a person or a vessel that has taken all it wants.","cn":"由 satis 得出 satur「满的、饱足的」，用于已取得所要之量的人或容器。"},{"era":"LATIN SATURARE","en":"Saturare 'to fill, to satisfy' turned the adjective into a verb, and its participle saturatus became the everyday word for a full vessel.","cn":"saturare「填满、使满足」把形容词变成动词，其分词 saturatus 成为「容器已满」的日常说法。"},{"era":"LATIN SATURATIO","en":"Late Latin saturatio named the act or state of being filled, and English borrowed the same shape with the ending -ation.","cn":"晚期拉丁 saturatio 命名填满的动作或状态，英语以 -ation 词尾借入同一形态。"},{"era":"SCIENTIFIC USE","en":"Chemistry and physics adopted saturation for solutions, vapours and magnets, where a capacity is filled and no further intake is possible.","cn":"化学与物理把 saturation 用于溶液、蒸气与磁体，那里容量被填满，无法再接纳更多。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin root behind satis is a reconstruction, and its link to words for sowing and seed is a hypothesis rather than a demonstrated derivation.","cn":"来源不确定（更深词源）：satis 背后的拉丁语之前词根属于重构，它与表示播种、种子的词之间的联系是假说，而非已证实的派生。"}]},"similar":{"note":{"en":"Group one holds the verb and adjective of the same family, which are constantly confused with the noun; group two holds words for fullness and capacity.","cn":"第一组是同一家族的动词与形容词，常与这个名词混淆；第二组是表示充满与容量的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"saturate","ipa":"/ˈsætʃəreɪt/","tag":"the verb","definition":"To fill something to capacity; saturation is the state or process that the verb produces.","definitionCN":"把某物填到容量上限；saturation 是动词产生的状态或过程。"},{"word":"saturated","ipa":"/ˈsætʃəreɪtɪd/","tag":"the adjective","definition":"Describes something already full; it is used of fats, colours and soils as well as solutions.","definitionCN":"形容已经填满的东西；可用于脂肪、颜色、土壤以及溶液。"},{"word":"satisfactory","ipa":"/ˌsætɪsˈfæktəri/","tag":"same enough-root, different sense","definition":"Built on satis 'enough' plus facere 'to make': good enough to meet a standard, with no idea of filling a vessel.","definitionCN":"由 satis「足够」加 facere「做」构成：好到符合标准，不含装满容器的意思。"},{"word":"satire","ipa":"/ˈsætaɪə/","tag":"same root, a medley","definition":"From satura, a mixed dish or medley: writing that mixes mockery with moral comment, not a word about fullness.","definitionCN":"出自 satura「杂烩、拼盘」：把讥讽与道德评论混在一起的写作，与「充满」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"concentration","ipa":"/ˌkɒnsənˈtreɪʃn/","tag":"amount, not ceiling","definition":"How much substance is present in a volume; concentration can rise until saturation is reached.","definitionCN":"单位体积中物质的含量；浓度可以上升，直到达到饱和。"},{"word":"capacity","ipa":"/kəˈpæsəti/","tag":"the room available","definition":"The maximum that a container can hold; saturation is the state of having reached that maximum.","definitionCN":"容器能容纳的最大量；saturation 是已达到该最大值的状态。"},{"word":"fullness","ipa":"/ˈfʊlnəs/","tag":"plain everyday word","definition":"The everyday noun for being full, with no technical measurement behind it.","definitionCN":"表示「满」的日常名词，背后没有技术量度。"},{"word":"supersaturation","ipa":"/ˌsuːpəsætʃəˈreɪʃn/","tag":"beyond the limit","definition":"A state in which more solute is present than saturation normally allows, held only under special conditions.","definitionCN":"溶质超过正常饱和限度的状态，只在特殊条件下维持。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Saturare 'to fill': the word is about a full vessel, not a strong substance.","cn":"saturare「填满」：这个词说的是装满的容器，不是浓烈的物质。"},{"en":"The family runs saturate, saturated, saturation, unsaturated, supersaturation.","cn":"同族词包括 saturate、saturated、saturation、unsaturated、supersaturation。"},{"en":"Fixed phrases mark the technical senses: saturation point, market saturation, magnetic saturation.","cn":"固定搭配标出技术义：饱和点、市场饱和、磁饱和。"},{"en":"Photography speaks of colour saturation, the fullness of a hue.","cn":"摄影说色彩饱和度，即色相的饱满程度。"},{"en":"The same enough-root appears in satisfactory and in satire, which came from a mixed dish.","cn":"同一「足够」词根也出现在 satisfactory 与 satire 中，后者出自「杂烩」一菜。"}],"abstract":[{"en":"Picture a sponge held under the tap until the water runs off its edge.","cn":"想象一块海绵放在水龙头下，直到水从边缘流走。"},{"en":"Picture a shelf with one book pushed in so far that the next will not fit.","cn":"想象书架上有一本书塞得太深，下一本再也放不进。"},{"en":"Picture a day divided into meetings until no hour is left blank.","cn":"想象一天被会议切分，直到没有一小时是空的。"}]},"examples":[{"en":"Sugar stops dissolving once the solution has reached saturation.","cn":"溶液达到饱和后，糖就不再溶解。"},{"en":"The saturation of the market forced the company to look abroad.","cn":"市场饱和迫使这家公司把目光转向海外。"},{"en":"Higher saturation made the reds in the poster almost glow.","cn":"更高的饱和度让海报里的红色几乎发亮。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sat（足够）+ uration」——装到足够了：饱和、浸透、满到极限","word":"saturation"},"root":"晚期拉丁 saturatio「填满、饱和」= saturare（填满）+ -io（动作名词）；saturare 出自 satur（满的），再上溯 satis（足够），其更早词根为重构。","sensesIntro":{"en":"Eight senses follow one filling: a solution takes no more solid, soil takes no more rain, a market takes no more buyers, a colour reaches full intensity, a magnet reaches its limit, cloth soaks through, advertising fills attention, and a schedule fills until no hour is free.","cn":"八个义项跟着同一次「装满」：溶液再溶不进固体，土壤再吸不进雨，市场再接纳不了买主，颜色达到最饱满，磁体到达极限，布浸透，广告填满注意力，日程满到没有一小时空闲。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sponge that has taken all the water it can and lets the rest run off.","cn":"核心意象：一块海绵吸尽了能吸的水，余下的只能流走。"},"chain":["FILLED TO CAPACITY","NO MORE DISSOLVES","SOIL SOAKED","MARKET FILLED","COLOUR AT FULL","NO ROOM LEFT"],"branches":[{"senses":"01 · 02","en":"CHEMICAL FULLNESS: the ceiling of a solution and the process of reaching it are one state and one action.","cn":"化学的满：溶液的上限与达到上限的过程，是同一状态与同一动作。"},{"senses":"03","en":"MARKET SATURATION: demand is treated as a vessel that every buyer has filled.","cn":"市场饱和：需求被当作每个买主都已填满的容器。"},{"senses":"04","en":"COLOUR SATURATION: a hue is full when no more pigment can be added to it.","cn":"色彩饱和：色相在再也加不进色素时达到饱满。"},{"senses":"05 · 06","en":"PHYSICAL LIMITS: a magnet and a soaked cloth both stop taking more of what fills them.","cn":"物理极限：磁体与浸透的布都不再接纳更多填充之物。"},{"senses":"07 · 08","en":"FULL ATTENTION AND FULL TIME: messages and obligations compete for the same limited vessel.","cn":"满负荷的注意力与时间：信息与义务争夺同一个有限容器。"}]},"affixes":{"intro":{"en":"Saturation is a Latin verb of filling plus an action ending, and the enough-root still shows in several common English words.","cn":"saturation 是一个表示「填满」的拉丁动词加动作词尾，表示「足够」的词根仍出现在若干常用英语词中。"},"latinIntro":{"en":"-atio becomes -ation in English; satis 'enough' also gives satisfactory and saturate, while satura 'a medley' gives satire.","cn":"-atio 在英语中变为 -ation；satis「足够」也衍生 satisfactory 与 saturate，而 satura「杂烩」衍生 satire。"},"items":[{"word":"satis","structure":"satis (Latin adverb, 'enough')","meaning":"enough","meaningCN":"足够","example":"The root supplies the idea of sufficiency.","exampleCN":"这个词根提供「足够」的意思。"},{"word":"satur","structure":"satur, satura, saturum (adjective, 'full')","meaning":"full; sated","meaningCN":"满的；饱足的","example":"The adjective describes a vessel that is full.","exampleCN":"这个形容词描述装满的容器。"},{"word":"saturare","structure":"satur + -are (verb ending)","meaning":"to fill, satisfy","meaningCN":"填满；使满足","example":"The verb begins the whole family.","exampleCN":"这个动词开启整个词族。"},{"word":"saturatio","structure":"saturare + -io (action noun)","meaning":"a filling","meaningCN":"填满","example":"The Latin noun matches the English one.","exampleCN":"这个拉丁名词与英语名词对应。"},{"word":"-ation","structure":"-ation (from Latin -atio, action or state)","meaning":"an action or state","meaningCN":"动作或状态","example":"The ending makes saturation both an act and a state.","exampleCN":"这个词尾让 saturation 既是动作也是状态。"},{"word":"saturate","structure":"saturare -> saturate","meaning":"to fill to capacity","meaningCN":"使饱和；浸透","example":"Rain saturated the fields in one night.","exampleCN":"一夜的雨把田地浸透。"},{"word":"saturated","structure":"saturate + -ed","meaning":"filled to capacity","meaningCN":"饱和的；浸透的","example":"The solution is saturated with salt.","exampleCN":"这溶液已被盐饱和。"},{"word":"saturation","structure":"saturate + -ion","meaning":"the state of being full","meaningCN":"饱和状态","example":"The market reached saturation.","exampleCN":"市场达到了饱和。"},{"word":"unsaturated","structure":"un- (not) + saturated","meaning":"not filled to the limit","meaningCN":"不饱和的","example":"Olive oil is mostly unsaturated.","exampleCN":"橄榄油多为不饱和的。"},{"word":"satisfactory","structure":"satis + facere (to make)","meaning":"good enough","meaningCN":"足够好的；令人满意的","example":"The result was satisfactory.","exampleCN":"结果令人满意。"}],"latinEntries":[{"word":"satis","structure":"satis (adverb)","meaning":"enough","meaningCN":"足够"},{"word":"satur","structure":"satur, satura, saturum (adjective)","meaning":"full, sated","meaningCN":"满的；饱足的"},{"word":"saturare","structure":"saturare, saturavi, saturatum (verb, first conjugation)","meaning":"to fill, satisfy","meaningCN":"填满；使满足"},{"word":"saturatio","structure":"saturatio, saturationis (f., third declension)","meaning":"a filling, saturation","meaningCN":"填满；饱和"}]}},{"word":"saturated","ipa_uk":"/ˈsætʃəreɪtɪd/","ipa_us":"/ˈsætʃəreɪtɪd/","definition_zh":"饱和的；浸透的；（脂肪）饱和的；（色彩）浓艳的","definition_en":"filled to capacity so that no more can be absorbed, or (of fats) containing no double bonds, or (of colour) very intense","core_image":"一块布浸到水里，提起来时水顺着边角一直往下滴","scene":"雨后的田里，泥土被水浸到踩下去就渗出泥浆。The soil was saturated after two days of steady rain.","sceneCN":"这里 saturated 指被水浸透、再也吸不进更多（第 3 个义项：浸透的）；句意为两天连绵雨后土壤已浸透。图中可辨识物件：田垄、积水、泥浆、雨靴。","pos":[{"tag":"adj.","zh":"饱和的；浸透的"},{"tag":"adj.","zh":"（脂肪）饱和的；（色彩）浓艳的"}],"collocations":[{"phrase":"saturated fat","zh":"饱和脂肪"},{"phrase":"saturated solution","zh":"饱和溶液"},{"phrase":"saturated soil","zh":"浸透的土壤"},{"phrase":"fully saturated","zh":"完全饱和的"},{"phrase":"saturated colour","zh":"浓艳的色彩"},{"phrase":"saturated market","zh":"饱和的市场"}],"forms":[{"label":"原级","form":"saturated"},{"label":"比较级","form":"more saturated"},{"label":"最高级","form":"most saturated"},{"label":"动词","form":"saturate"},{"label":"名词","form":"saturation"},{"label":"反义形容词","form":"unsaturated"}],"derivatives":[{"word":"saturate","pos":"v.","zh":"使饱和；浸透"},{"word":"saturation","pos":"n.","zh":"饱和；饱和度"},{"word":"unsaturate","pos":"v.","zh":"使不饱和（罕用）"},{"word":"unsaturated","pos":"adj.","zh":"不饱和的"},{"word":"supersaturated","pos":"adj.","zh":"过饱和的"}],"senses":[{"no":"01","title":"A solution holding all it can","titleCN":"溶液已溶到不能再溶","definition":"describing a liquid that contains as much dissolved solid as it can hold at that temperature","definitionCN":"指液体在该温度下已含有尽可能多的溶解固体","example":"The solution is saturated at this temperature.","exampleCN":"在这个温度下溶液已经饱和。","why":"saturated is the participle of saturate, from satur 'full', so it describes a vessel that is full rather than a liquid that is strong.","whyCN":"saturated 是 saturate 的分词，出自 satur「满的」，描述的是装满的容器，而不是浓烈的液体。"},{"no":"02","title":"Fat with no double bonds","titleCN":"饱和脂肪的（不含双键）","definition":"describing a fat whose fatty acid chains have no double bonds, so every carbon is bonded to as much hydrogen as it can take","definitionCN":"指脂肪酸链没有双键、每个碳都已连上尽可能多氢的脂肪","example":"Butter contains a high proportion of saturated fat.","exampleCN":"黄油含有高比例的饱和脂肪。","why":"the chemical meaning of saturated is literal: the carbon chain is full of hydrogen, so it can take no more.","whyCN":"saturated 的化学义是字面义的：碳链已被氢填满，再接纳不了更多。"},{"no":"03","title":"Soaked through with water","titleCN":"被水浸透","definition":"holding as much water as the material can absorb, so that any more runs off or pools","definitionCN":"材料已含尽可能多的水，再多只能流走或积起来","example":"His coat was saturated after the storm.","exampleCN":"暴风雨后他的外套湿透了。","why":"this is the everyday physical sense: cloth, soil and paper are vessels that fill up.","whyCN":"这是日常的实体义：布、土壤与纸都是会被填满的容器。"},{"no":"04","title":"Colour at full intensity","titleCN":"色彩浓艳、饱和度高的","definition":"describing a colour that is vivid and pure rather than greyed or washed out","definitionCN":"指颜色鲜艳纯正，而非发灰或被冲淡","example":"The poster used saturated reds and blues.","exampleCN":"这张海报用了浓艳的红色与蓝色。","why":"a hue is saturated when it holds as much pigment as it can, the same fullness applied to light.","whyCN":"色相在容纳尽可能多色素时就是饱和的，这是同一种「满」被用在光上。"},{"no":"05","title":"A market with no room left","titleCN":"市场饱和的","definition":"describing a market in which every likely buyer has been reached and further growth is hard","definitionCN":"指每个可能的买主都已被触及、进一步增长困难的市场","example":"The market for basic phones is saturated.","exampleCN":"基础手机的市场已经饱和。","why":"demand is a container, and a saturated market is one that no new product can fill further.","whyCN":"需求是一个容器，饱和的市场就是新产品再也填不进去的市场。"},{"no":"06","title":"A magnet at its limit","titleCN":"磁饱和的","definition":"describing a magnetic material that cannot be magnetized more strongly by any increase in current","definitionCN":"指无论电流怎样增加都无法磁得更强的磁材料","example":"The transformer core became saturated.","exampleCN":"变压器铁芯进入了饱和状态。","why":"magnetic capacity fills up like a vessel, after which more current produces no more magnetization.","whyCN":"磁容量像容器一样被填满，此后电流再增加也不产生更多磁性。"},{"no":"07","title":"A compound with only single bonds","titleCN":"饱和化合物的（全为单键）","definition":"describing an organic compound whose carbon atoms are joined by single bonds only, with no double or triple bonds","definitionCN":"指碳原子之间只有单键、没有双键或三键的有机化合物","example":"The chemists compared saturated and unsaturated oils.","exampleCN":"化学家比较了饱和油与不饱和油。","why":"in organic chemistry saturation is a count of bonds: a chain with only single bonds is full of hydrogen.","whyCN":"在有机化学中，饱和是对键的计数：只有单键的链已被氢填满。"},{"no":"08","title":"A life filled with no room","titleCN":"抽象义：被填满而无余地","definition":"used figuratively of a schedule, mind or life so full that nothing more can be taken on","definitionCN":"比喻指日程、头脑或生活满到再也承担不了新东西","example":"His schedule was saturated with meetings.","exampleCN":"他的日程被会议塞得满满的。","why":"the abstract sense keeps the vessel and simply substitutes obligations for water.","whyCN":"抽象义保留容器，只把水换成了义务。"}],"etymology":{"intro":{"en":"Saturated is the past participle of saturate, from Latin saturare 'to fill, satisfy', from satur 'full', from satis 'enough'. The chemical use for fats and solutions dates from the nineteenth century. Dates are approximate.","cn":"saturated 是 saturate 的过去分词，出自拉丁 saturare「填满、使满足」，再上溯 satur「满的」与 satis「足够」。用于脂肪与溶液的化学义始于十九世纪。年代均为约数。"},"items":[{"era":"LATIN SATIS","en":"Satis meant 'enough'; its deeper origin is reconstructed as a root of satisfying rather than recorded directly.","cn":"satis 意为「足够」；其更深来源被重构为一个表示「满足」的词根，而非直接记录。"},{"era":"LATIN SATUR","en":"Satur 'full, sated' described a person or vessel that had taken all it wanted.","cn":"satur「满的、饱足的」描述已取得所要之量的人或容器。"},{"era":"LATIN SATURARE","en":"Saturare 'to fill' produced the participle saturatus, literally 'filled', which English borrowed as an adjective.","cn":"saturare「填满」产生分词 saturatus，字面即「被填满的」，英语把它借作形容词。"},{"era":"CHEMISTRY","en":"Nineteenth-century chemistry applied the participle to solutions that could take no more solute and to fats whose chains were full of hydrogen.","cn":"十九世纪化学把这个分词用于再溶不进溶质的溶液，以及链上已充满氢的脂肪。"},{"era":"FIGURATIVE USE","en":"The same participle came to describe markets, colours and schedules that are full to their limit, with no room for more.","cn":"同一分词也用于满到极限、再无余地的市场、色彩与日程。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin root behind satis is a reconstruction, and its connection with words for sowing is a hypothesis, not a demonstrated derivation.","cn":"来源不确定（更深词源）：satis 背后的拉丁语之前词根属于重构，它与表示播种的词之间的联系是假说，而非已证实的派生。"}]},"similar":{"note":{"en":"Group one holds the verb and noun of the same family; group two holds adjectives for something completely filled or its opposite.","cn":"第一组是同一家族的动词与名词；第二组是表示完全填满或其反面的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"saturate","ipa":"/ˈsætʃəreɪt/","tag":"the verb","definition":"The action of filling to capacity; saturated is the resulting state.","definitionCN":"填到容量上限的动作；saturated 是产生的结果状态。"},{"word":"saturation","ipa":"/ˌsætʃəˈreɪʃn/","tag":"the noun","definition":"The state or process of being full; it can also mean colour intensity and market fullness.","definitionCN":"填满的状态或过程；也可指色彩强度与市场饱和。"},{"word":"satiated","ipa":"/səˈtieɪtɪd/","tag":"appetite, not chemistry","definition":"From satiare 'to satisfy an appetite': fully fed or bored, said of desires rather than of solutions or fats.","definitionCN":"出自 satiare「满足食欲」：吃饱或腻了，用于欲望，而非溶液或脂肪。"},{"word":"satisfied","ipa":"/ˈsætɪsfaɪd/","tag":"enough, not full","definition":"Built on satis plus facere: content because a standard has been met, with no image of a full vessel.","definitionCN":"由 satis 加 facere 构成：因达到标准而满意，不含装满容器的意象。"}]},{"heading":"NEAR MEANING","entries":[{"word":"soaked","ipa":"/səʊkt/","tag":"everyday wetness","definition":"The plain word for something made thoroughly wet; saturated is its more technical and stronger counterpart.","definitionCN":"表示彻底湿透的日常词；saturated 是更技术、语气更强的对应词。"},{"word":"drenched","ipa":"/drentʃt/","tag":"wet from above","definition":"Wet through by rain or a wave; it stresses the cause, while saturated stresses the limit of absorption.","definitionCN":"被雨或浪浇透；强调成因，而 saturated 强调吸收极限。"},{"word":"full","ipa":"/fʊl/","tag":"the general word","definition":"The broad adjective for a container with no space left; saturated adds that the material itself has absorbed the maximum.","definitionCN":"表示容器没空间的通用形容词；saturated 进一步说明材料本身已吸收到极限。"},{"word":"unsaturated","ipa":"/ˌʌnˈsætʃəreɪtɪd/","tag":"the opposite","definition":"Not filled to the limit; used of fats with double bonds and of solutions that can still dissolve more.","definitionCN":"未填到极限；用于含双键的脂肪与仍能溶解更多的溶液。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Satur 'full': the ending -ated marks a state that has already been reached.","cn":"satur「满的」：词尾 -ated 标记已经达到的状态。"},{"en":"The family runs saturate, saturated, saturation, unsaturated, supersaturated.","cn":"同族词包括 saturate、saturated、saturation、unsaturated、supersaturated。"},{"en":"Fixed phrases split the senses: saturated fat, saturated solution, saturated soil, saturated market.","cn":"固定搭配切分义项：饱和脂肪、饱和溶液、浸透的土壤、饱和的市场。"},{"en":"Chemistry counts bonds: saturated fats have only single bonds, unsaturated ones have double bonds.","cn":"化学数键：饱和脂肪只有单键，不饱和脂肪含双键。"},{"en":"The spelling keeps the participle ending -ed, so it always describes a completed filling.","cn":"拼写保留分词词尾 -ed，因此它总描述已完成的填满。"}],"abstract":[{"en":"Picture a cloth lifted from a bucket, water running from every corner.","cn":"想象一块布从桶里提起，水从每个角往下流。"},{"en":"Picture a jar packed with coins until the lid will not close.","cn":"想象一个罐子塞满硬币，盖子合不上。"},{"en":"Picture a calendar with every square already written on.","cn":"想象一本日历，每一格都已写满。"}]},"examples":[{"en":"A saturated solution can be recognised by the crystals that remain at the bottom.","cn":"饱和溶液可以通过杯底留下的晶体辨认出来。"},{"en":"Doctors advise replacing saturated fat with unsaturated oils.","cn":"医生建议用不饱和油替代饱和脂肪。"},{"en":"The ground was saturated, so the water ran into the road instead of soaking away.","cn":"地面已经浸透，水便流到路上而不是渗下去。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sat（足够）+ urated」——已经装到足够、再也装不下：饱和的、浸透的","word":"saturated"},"root":"拉丁 saturatus「被填满的」，是 saturare（填满）的过去分词；saturare 出自 satur（满的），再上溯 satis（足够），其更早词根为重构。英语作形容词。","sensesIntro":{"en":"Eight senses follow one filled vessel: a solution stops dissolving, a fat chain fills with hydrogen, cloth and soil soak through, colour reaches full intensity, a market and a magnet reach their limits, an organic compound keeps only single bonds, and a schedule fills until nothing more fits.","cn":"八个义项跟着同一个被装满的容器：溶液停止溶解，脂肪链被氢填满，布与土壤浸透，颜色达到最饱满，市场与磁体到达极限，有机化合物只留单键，日程满到再也放不进东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cloth soaked until water runs from every corner when it is lifted.","cn":"核心意象：一块布浸到提起时水从每个角往下流。"},"chain":["FILLED TO THE LIMIT","NO MORE DISSOLVES","FAT CHAIN FULL","SOAKED THROUGH","COLOUR AT FULL","NO ROOM LEFT"],"branches":[{"senses":"01 · 07","en":"CHEMICAL SATURATION: a solution at its ceiling and a chain full of hydrogen are the same 'no more can be added'.","cn":"化学饱和：溶液到达上限与链被氢填满，都是「再也加不进」。"},{"senses":"02","en":"FAT WITHOUT DOUBLE BONDS: the everyday nutrition sense comes straight from the bond count.","cn":"无双键的脂肪：日常营养义直接来自键的计数。"},{"senses":"03","en":"SOAKED MATERIAL: cloth and soil show the vessel image in its plainest form.","cn":"浸透的材料：布与土壤以最朴素的形式展示容器意象。"},{"senses":"04 · 05","en":"FULL INTENSITY AND FULL MARKETS: both colour and demand reach a point where nothing more is taken.","cn":"饱满的强度与饱和的市场：颜色与需求都到达再也接纳不了更多的点。"},{"senses":"06 · 08","en":"HARD LIMITS: a magnet and a full schedule both stop responding to further pressure.","cn":"硬性极限：磁体与排满的日程都不再对更多压力作出反应。"}]},"affixes":{"intro":{"en":"Saturated is a Latin participle used as an adjective, and its root of enough also builds words about satisfaction and fullness.","cn":"saturated 是一个作形容词用的拉丁分词，其「足够」词根也构成表示满足与充满的词。"},"latinIntro":{"en":"Satur 'full' gives saturate, saturated and saturation; -ated marks a completed state, and un- reverses it in unsaturated.","cn":"satur「满的」衍生 saturate、saturated 与 saturation；-ated 标记完成状态，un- 在 unsaturated 中将其反转。"},"items":[{"word":"satis","structure":"satis (Latin adverb, 'enough')","meaning":"enough","meaningCN":"足够","example":"The root gives the idea of having enough.","exampleCN":"这个词根给出「已经足够」的意思。"},{"word":"satur","structure":"satur, satura, saturum (adjective)","meaning":"full","meaningCN":"满的","example":"The adjective is the heart of the family.","exampleCN":"这个形容词是词族的核心。"},{"word":"saturare","structure":"satur + -are","meaning":"to fill","meaningCN":"填满","example":"The verb supplies the participle.","exampleCN":"这个动词提供分词。"},{"word":"-atus","structure":"-atus (Latin past participle ending)","meaning":"having been acted on","meaningCN":"已被作用过的","example":"The ending marks a state already reached.","exampleCN":"这个词尾标记已经达到的状态。"},{"word":"saturate","structure":"saturare -> saturate","meaning":"to fill to capacity","meaningCN":"使饱和；浸透","example":"The rain saturated the soil.","exampleCN":"雨水浸透了土壤。"},{"word":"saturated","structure":"saturate + -ed","meaning":"filled to capacity","meaningCN":"饱和的；浸透的","example":"The ground is saturated after the storm.","exampleCN":"暴风雨后地面已浸透。"},{"word":"saturation","structure":"saturate + -ion","meaning":"fullness","meaningCN":"饱和","example":"Saturation is reached at this temperature.","exampleCN":"在这个温度达到饱和。"},{"word":"unsaturated","structure":"un- (not) + saturated","meaning":"not filled to the limit","meaningCN":"不饱和的","example":"The oil is unsaturated.","exampleCN":"这种油是不饱和的。"},{"word":"supersaturated","structure":"super- (above) + saturated","meaning":"holding more than the normal limit","meaningCN":"过饱和的","example":"A supersaturated solution is unstable.","exampleCN":"过饱和溶液不稳定。"},{"word":"satiated","structure":"satiare (to satisfy) + -ed","meaning":"having appetite fully satisfied","meaningCN":"已吃饱的；腻足的","example":"The diners were satiated.","exampleCN":"食客们已吃得饱足。"}],"latinEntries":[{"word":"satur","structure":"satur, satura, saturum (adjective)","meaning":"full, sated","meaningCN":"满的；饱足的"},{"word":"saturare","structure":"saturare, saturavi, saturatum (verb, first conjugation)","meaning":"to fill, satisfy","meaningCN":"填满；使满足"},{"word":"saturatus","structure":"saturatus, saturata, saturatum (past participle)","meaning":"filled, saturated","meaningCN":"被填满的；饱和的"},{"word":"saturatio","structure":"saturatio, saturationis (f., third declension)","meaning":"a filling, saturation","meaningCN":"填满；饱和"}]}},{"word":"distillation","ipa_uk":"/ˌdɪstɪˈleɪʃn/","ipa_us":"/ˌdɪstɪˈleɪʃn/","definition_zh":"蒸馏；蒸馏产物；提炼出的精华；（思想的）凝练","definition_en":"the process of heating a liquid into vapour and condensing it to separate or purify it, or the essence extracted by such a process","core_image":"一锅液体在火上冒汽，蒸汽绕过弯管，在另一头凝成清亮的一滴","scene":"实验室里，烧瓶中的液体被加热，蒸汽沿弯管上升，另一端慢慢凝出一滴滴清水。The distillation separated the alcohol from the fermented liquid.","sceneCN":"这里 distillation 指加热汽化再冷凝以分离成分的过程（第 1 个义项：蒸馏过程）；句意为蒸馏把酒精从发酵液中分离出来。图中可辨识物件：烧瓶、加热器、冷凝管、接收瓶。","pos":[{"tag":"n.","zh":"蒸馏；蒸馏过程（可数或不可数）"},{"tag":"n.","zh":"提炼出的精华；凝练的成果"}],"collocations":[{"phrase":"fractional distillation","zh":"分馏"},{"phrase":"simple distillation","zh":"简单蒸馏"},{"phrase":"distillation apparatus","zh":"蒸馏装置"},{"phrase":"a distillation of ideas","zh":"思想的凝练"},{"phrase":"the distillation of experience","zh":"经验的提炼"},{"phrase":"water distillation","zh":"水蒸馏"}],"forms":[{"label":"单数","form":"distillation"},{"label":"复数（多次蒸馏）","form":"distillations"},{"label":"动词（美式）","form":"distill"},{"label":"动词（英式）","form":"distil"},{"label":"名词（蒸馏厂）","form":"distillery"},{"label":"相关名词（馏出物）","form":"distillate"}],"derivatives":[{"word":"distill","pos":"v.","zh":"蒸馏；提炼"},{"word":"distil","pos":"v.","zh":"蒸馏（英式拼写）"},{"word":"distillate","pos":"n.","zh":"馏出物"},{"word":"distillery","pos":"n.","zh":"蒸馏厂；酿酒厂"},{"word":"distiller","pos":"n.","zh":"蒸馏者；蒸馏器"}],"senses":[{"no":"01","title":"Heating a liquid into vapour and back","titleCN":"加热汽化再冷凝的分离过程","definition":"the process of boiling a liquid into vapour and cooling it again so that it separates from substances that boil at different temperatures","definitionCN":"把液体煮沸成蒸气再冷却，使其与沸点不同的物质分开的过程","example":"Distillation separates a liquid from substances that do not boil at the same temperature.","exampleCN":"蒸馏把一种液体与沸点不同的物质分开。","why":"distillation comes from Latin distillare 'to drip down', so the whole process is pictured as vapour falling drop by drop into a new vessel.","whyCN":"distillation 出自拉丁 distillare「滴下」，整个流程被想象成蒸气一滴一滴落进另一只容器。"},{"no":"02","title":"A single round of distilling","titleCN":"一次蒸馏操作","definition":"one complete run of the apparatus, often repeated to reach a higher purity","definitionCN":"装置的一次完整运行，常重复进行以达到更高纯度","example":"A second distillation produced a cleaner sample.","exampleCN":"第二次蒸馏得到了更纯的样品。","why":"a process that can be repeated becomes a countable event, which is why the word takes a plural.","whyCN":"可重复的过程会变成可数的事件，因此这个词有复数形式。"},{"no":"03","title":"The liquid that comes across","titleCN":"馏出物、接收到的蒸馏液","definition":"the condensed liquid collected on the other side of the apparatus","definitionCN":"在装置另一端冷凝并被收集的液体","example":"The distillation was collected in a cooled flask.","exampleCN":"馏出液被收集在冷却过的烧瓶里。","why":"the noun can name the product as well as the act, since the product is literally what the dripping produced.","whyCN":"这个名词既能命名动作，也能命名产物，因为产物就是「滴下来」的东西。"},{"no":"04","title":"The extraction of an essence","titleCN":"提炼精华、浓缩要点的过程","definition":"the process of separating what matters from what does not, so that only the essential part remains","definitionCN":"把要紧的部分与不要紧的部分分开、只留下本质的过程","example":"The essay is a distillation of ten years of fieldwork.","exampleCN":"这篇文章是十年田野工作的提炼。","why":"the laboratory image of leaving impurities behind transfers easily to thought, where detail is the impurity.","whyCN":"实验室里「把杂质留下」的画面很容易搬到思想上，那里细节就是杂质。"},{"no":"05","title":"The concentrated essence itself","titleCN":"提炼出的精华、精髓","definition":"the concentrated result of long experience or argument, reduced to its essential content","definitionCN":"长期经验或论证被浓缩后的结果，只保留本质内容","example":"That sentence is the distillation of the whole argument.","exampleCN":"那句话是整个论证的精华。","why":"once the act is finished, the noun names the small clear volume that carries the strength of the large muddy one.","whyCN":"动作完成后，这个名词命名那一小份清液，它承载着大份浑浊液的全部力量。"},{"no":"06","title":"Industrial separation of petroleum","titleCN":"石油的分馏","definition":"the large-scale process that splits a mixture such as crude oil into products with different boiling ranges","definitionCN":"把原油这类混合物按不同沸程分成产品的大规模过程","example":"Fractional distillation divides crude oil into usable fuels.","exampleCN":"分馏把原油分成可用的燃料。","why":"industry scales up the same principle, and the column simply makes many repeated distillations in one tower.","whyCN":"工业把同一原理放大，分馏塔只是在一座塔里完成多次重复蒸馏。"},{"no":"07","title":"A shortened version of a longer work","titleCN":"由长文本提炼出的简明版本","definition":"a short text that keeps the essential content of a much longer one","definitionCN":"保留长文本本质内容的短文本","example":"The handbook is a distillation of the longer manual.","exampleCN":"这本手册是那本更长说明书的提炼版。","why":"a summary is to a book what a still is to a fermented mash: the same content in less volume.","whyCN":"摘要之于书，正如蒸馏器之于发酵醪：同样的内容，更少的体积。"},{"no":"08","title":"Memory keeping only the core","titleCN":"抽象义：去掉杂质、只留核心","definition":"used figuratively of any process that slowly removes the incidental and keeps the central part","definitionCN":"比喻指任何慢慢去掉偶然成分、留下核心部分的过程","example":"Memory works as a slow distillation of detail.","exampleCN":"记忆像一场缓慢的蒸馏，把细节一点点滤掉。","why":"the abstract sense treats time as heat: what is volatile goes, what matters condenses.","whyCN":"抽象义把时间当作火：易挥发的走掉，要紧的凝结下来。"}],"etymology":{"intro":{"en":"Distillation comes from Late Latin distillatio, from distillare 'to drip down', built on de- 'down' plus stillare 'to drip', from stilla 'a drop'. It is recorded in English from the fourteenth century. Dates are approximate.","cn":"distillation 来自晚期拉丁 distillatio，出自 distillare「滴下」，由 de-「向下」加 stillare「滴」构成，后者出自 stilla「一滴」。英语自十四世纪有记录。年代均为约数。"},"items":[{"era":"LATIN STILLA","en":"Stilla meant 'a drop', especially a drop of liquid; its deeper origin is not established, and any older root proposed for it is a reconstruction.","cn":"stilla 意为「一滴」，尤其指液滴；其更深来源没有定论，为其提出的更古老词根属于重构。"},{"era":"LATIN STILLARE","en":"Stillare 'to drip, to drop' turned the noun into a verb, used of liquids falling drop by drop.","cn":"stillare「滴、滴落」把名词变成动词，用于一滴一滴落下的液体。"},{"era":"LATIN DISTILLARE","en":"De- 'down' plus stillare gave distillare 'to drip down', which alchemy applied to vapour condensed and collected drop by drop.","cn":"de-「向下」加 stillare 构成 distillare「滴下」，炼金术用它指蒸气冷凝后一滴一滴被收集。"},{"era":"MEDIEVAL ALCHEMY","en":"Medieval alchemists built the still and named the process, and their Latin writings carried both into European languages.","cn":"中世纪炼金术士造出蒸馏器并为这一过程命名，他们的拉丁著作把器与名一并带入欧洲各语言。"},{"era":"ENGLISH USE","en":"English distillation appears in the fourteenth century for the apparatus and the act, and the figurative sense of extracting an essence follows by the nineteenth.","cn":"英语 distillation 在十四世纪指蒸馏器与蒸馏动作，到十九世纪出现「提炼精华」的比喻义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin origin of stilla is unsettled, so any root offered for it is a reconstruction rather than a demonstrated form.","cn":"来源不确定（更深词源）：stilla 在拉丁语之前的来源没有定论，为其提出的任何词根都是重构形式，而非已证实的形式。"}]},"similar":{"note":{"en":"Group one holds the apparatus and the verb of the same family, which are often confused with the process; group two holds other ways of separating or purifying.","cn":"第一组是同一家族的器具与动词，常与过程本身混淆；第二组是其他分离或提纯方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"distill","ipa":"/dɪˈstɪl/","tag":"the verb","definition":"To carry out the process; distillation is the process or its product.","definitionCN":"执行这个过程；distillation 是过程或产物。"},{"word":"still","ipa":"/stɪl/","tag":"the apparatus","definition":"The vessel and condenser used for distilling; the noun comes from the same dripping root, not from the adverb still.","definitionCN":"用于蒸馏的容器与冷凝器；这个名词出自同一「滴」词根，不来自副词 still。"},{"word":"distillate","ipa":"/dɪˈstɪleɪt/","tag":"the collected liquid","definition":"The condensed product itself, as opposed to the process that made it.","definitionCN":"冷凝所得产物本身，与制造它的过程相对。"},{"word":"instill","ipa":"/ɪnˈstɪl/","tag":"same dripping root","definition":"In- 'in' plus stillare: to drip something in, hence to implant an idea gradually.","definitionCN":"in-「进入」加 stillare：把某物滴进去，因此指逐渐灌输一种观念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"extraction","ipa":"/ɪkˈstrækʃn/","tag":"pulling out, not boiling","definition":"Removing a substance with a solvent or force; it does not require vaporizing and condensing.","definitionCN":"用溶剂或外力取出物质；不需要汽化再冷凝。"},{"word":"refinement","ipa":"/rɪˈfaɪnmənt/","tag":"purification","definition":"The removal of impurities to raise quality; distillation is one method of refinement.","definitionCN":"去除杂质以提高品质；蒸馏是精炼的一种方法。"},{"word":"purification","ipa":"/ˌpjʊərɪfɪˈkeɪʃn/","tag":"the goal, not the method","definition":"Making something pure, by any method; distillation is one route to that goal.","definitionCN":"用任何方法使某物纯净；蒸馏是达到该目标的一条途径。"},{"word":"condensation","ipa":"/ˌkɒndenˈseɪʃn/","tag":"vapour to liquid","definition":"The change from vapour to liquid; it is one half of a distillation, not the whole process.","definitionCN":"由蒸气变为液体；它是蒸馏的一半，而非全过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"De- 'down' plus stillare 'to drip': vapour is made to drip down into a new vessel.","cn":"de-「向下」加 stillare「滴」：让蒸气滴落进另一只容器。"},{"en":"The family runs distill, distil, distillation, distillate, distillery, distiller.","cn":"同族词包括 distill、distil、distillation、distillate、distillery、distiller。"},{"en":"Fixed phrases mark the industrial sense: fractional distillation, simple distillation.","cn":"固定搭配标出工业义：分馏、简单蒸馏。"},{"en":"The apparatus is a still, and the same dripping root gives instill.","cn":"器具叫 still，同一「滴」词根还构成 instill。"},{"en":"The figurative phrases mark the rest: a distillation of ideas, the distillation of experience.","cn":"比喻搭配标出其余义项：思想的凝练、经验的提炼。"}],"abstract":[{"en":"Picture a long speech reduced to one sentence that still carries its weight.","cn":"想象一场长演讲被收成一句仍带着全部分量的话。"},{"en":"Picture muddy water entering a still and clear drops leaving it.","cn":"想象浑浊的水进入蒸馏器，清亮的液滴从另一端落下。"},{"en":"Picture a year of travel folded into a single page of notes.","cn":"想象一年的旅行被折进一页笔记。"}]},"examples":[{"en":"Distillation is the standard method for recovering alcohol from a fermented mixture.","cn":"蒸馏是从发酵混合物中回收酒精的标准方法。"},{"en":"The book is a distillation of interviews with two hundred farmers.","cn":"这本书是对两百位农民访谈的提炼。"},{"en":"Fractional distillation at the refinery separates petrol, kerosene and diesel.","cn":"炼油厂的分馏把汽油、煤油与柴油分开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dis（分开）+ till（滴）+ ation」——让蒸汽一滴滴落下、把成分分开：蒸馏、提炼","word":"distillation"},"root":"晚期拉丁 distillatio「滴下」= distillare（滴下）+ -io（动作名词）；distillare 由 de-（向下）+ stillare（滴）构成，stillare 出自 stilla（一滴），stilla 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one dripping: vapour rises and comes back as drops, a run is repeated, the liquid is collected, an essence is extracted, that essence is named, industry separates fuels, a long work is shortened, and finally memory keeps only the core.","cn":"八个义项跟着同一次滴落：蒸气升起又落回成滴，一次操作被重复，液体被收集，精华被提取，那份精华被命名，工业借此分离燃料，长作品被缩短，最后记忆只留下核心。"},"semanticMap":{"core":{"en":"CORE IMAGE: vapour rising from a heated flask and returning as clean drops in another vessel.","cn":"核心意象：蒸气从受热的烧瓶升起，在另一只容器里变回清亮的液滴。"},"chain":["HEAT AND VAPOUR","DROPS CONDENSE","PRODUCT COLLECTED","ESSENCE EXTRACTED","ESSENCE NAMED","VOLUME REDUCED"],"branches":[{"senses":"01 · 02","en":"THE PROCESS AND A RUN OF IT: one rise-and-fall cycle becomes a countable operation when repeated.","cn":"过程与一次操作：一次升落循环在被重复时成为可数的操作。"},{"senses":"03","en":"THE COLLECTED LIQUID: what drips into the receiver is the process made tangible.","cn":"被收集的液体：滴进接收瓶的东西，是过程变得可触。"},{"senses":"04 · 05","en":"ESSENCE: extracting the essential part and naming that part are two halves of one figurative move.","cn":"精华：提取本质部分与命名本质部分，是同一次比喻动作的两半。"},{"senses":"06","en":"INDUSTRIAL SCALE: a fractionating column is many distillations stacked in one tower.","cn":"工业规模：分馏塔就是把多次蒸馏叠在一座塔里。"},{"senses":"07 · 08","en":"SHORTER FORMS: a summary and a memory both keep the core and let the rest go.","cn":"更短的形式：摘要与记忆都保留核心，让其余部分走掉。"}]},"affixes":{"intro":{"en":"Distillation is a Latin verb of dripping plus an action ending, and the drip root also builds the apparatus and the word for implanting ideas.","cn":"distillation 是一个表示「滴」的拉丁动词加动作词尾，「滴」词根还构成器具名与「灌输观念」的词。"},"latinIntro":{"en":"Stilla 'a drop' gives stillare and distillare; de- 'down' marks the direction, and -atio becomes -ation in English.","cn":"stilla「一滴」衍生 stillare 与 distillare；de-「向下」标记方向，-atio 在英语中变为 -ation。"},"items":[{"word":"stilla","structure":"stilla, stillae (f., first declension)","meaning":"a drop","meaningCN":"一滴","example":"The noun supplies the single drop.","exampleCN":"这个名词提供「一滴」这一单位。"},{"word":"stillare","structure":"stilla + -are (verb ending)","meaning":"to drip","meaningCN":"滴；滴落","example":"The verb describes liquid falling in drops.","exampleCN":"这个动词描述液体成滴落下。"},{"word":"de-","structure":"de- (Latin prefix, 'down')","meaning":"down","meaningCN":"向下","example":"The prefix gives the direction of the fall.","exampleCN":"这个前缀给出落下的方向。"},{"word":"distillare","structure":"de- + stillare","meaning":"to drip down","meaningCN":"滴下","example":"The Latin verb begins the family.","exampleCN":"这个拉丁动词开启词族。"},{"word":"distillatio","structure":"distillare + -io (action noun)","meaning":"a dripping down","meaningCN":"滴下；蒸馏","example":"The Latin noun matches the English one.","exampleCN":"这个拉丁名词与英语名词对应。"},{"word":"distillation","structure":"distill + -ation","meaning":"the process or its product","meaningCN":"蒸馏；蒸馏产物","example":"Distillation is repeated to raise purity.","exampleCN":"蒸馏被重复以提高纯度。"},{"word":"distillations","structure":"distillation + -s (plural)","meaning":"several runs","meaningCN":"多次蒸馏","example":"Three distillations were needed.","exampleCN":"需要三次蒸馏。"},{"word":"distill","structure":"distillare -> distill","meaning":"to carry out distillation","meaningCN":"进行蒸馏","example":"They distill the liquid twice.","exampleCN":"他们把这个液体蒸馏两次。"},{"word":"still","structure":"Middle English stillen, from stillare","meaning":"the distilling apparatus","meaningCN":"蒸馏器","example":"The copper still was heated slowly.","exampleCN":"铜制蒸馏器被缓慢加热。"},{"word":"instill","structure":"in- (in) + stillare","meaning":"to drip in, hence to implant","meaningCN":"滴入，因此指灌输","example":"The teacher instilled a love of reading.","exampleCN":"老师灌输了阅读的热爱。"}],"latinEntries":[{"word":"stilla","structure":"stilla, stillae (f., first declension)","meaning":"a drop","meaningCN":"一滴"},{"word":"stillare","structure":"stillare, stillavi, stillatum (verb, first conjugation)","meaning":"to drip","meaningCN":"滴；滴落"},{"word":"distillare","structure":"distillare, distillavi, distillatum (verb, first conjugation)","meaning":"to drip down","meaningCN":"滴下"},{"word":"distillatio","structure":"distillatio, distillationis (f., third declension)","meaning":"a dripping down, distillation","meaningCN":"滴下；蒸馏"}]}},{"word":"distill","ipa_uk":"/dɪˈstɪl/","ipa_us":"/dɪˈstɪl/","definition_zh":"蒸馏；提炼；使滴下；（液体）渗出","definition_en":"to purify or separate a liquid by boiling it into vapour and condensing it, or to extract the essential part of something","core_image":"蒸气在弯管里走一段，管壁上慢慢挂满水珠，最后汇成一滴落下","scene":"实验室里，学生加热烧瓶，蒸气在弯管壁上凝成水珠，最后汇成一滴滴进接收瓶。The apparatus distilled the mixture into two separate liquids.","sceneCN":"这里 distill 指用加热汽化再冷凝的方式分离液体（第 1 个义项：蒸馏分离）；句意为这套装置把混合物蒸馏成两种分开的液体。图中可辨识物件：烧瓶、弯管、水珠、接收瓶。","pos":[{"tag":"vt.","zh":"蒸馏；用蒸馏法提纯或分离"},{"tag":"vt.","zh":"提炼（思想、经验）；使滴下"},{"tag":"vi.","zh":"（液体）滴下、渗出"}],"collocations":[{"phrase":"distill water","zh":"蒸馏水"},{"phrase":"distill alcohol","zh":"蒸馏酒精"},{"phrase":"distill the essence","zh":"提炼精华"},{"phrase":"distill into","zh":"提炼成"},{"phrase":"distill from experience","zh":"从经验中提炼"},{"phrase":"freshly distilled","zh":"刚蒸馏出的"}],"forms":[{"label":"三单（he/she/it）","form":"distills"},{"label":"过去式","form":"distilled"},{"label":"过去分词","form":"distilled"},{"label":"现在分词","form":"distilling"},{"label":"英式拼写","form":"distil"},{"label":"名词","form":"distillation"}],"derivatives":[{"word":"distillation","pos":"n.","zh":"蒸馏；提炼"},{"word":"distillate","pos":"n.","zh":"馏出物"},{"word":"distillery","pos":"n.","zh":"蒸馏厂"},{"word":"distiller","pos":"n.","zh":"蒸馏者；蒸馏器"},{"word":"distilled","pos":"adj.","zh":"蒸馏过的"}],"senses":[{"no":"01","title":"To separate a liquid by boiling and condensing","titleCN":"用加热汽化再冷凝的方式分离液体","definition":"to purify or separate a liquid by turning it into vapour and then cooling it back into liquid","definitionCN":"把液体变成蒸气再冷却回液体，以提纯或分离","example":"The plant distills seawater into drinking water.","exampleCN":"这套设备把海水蒸馏成饮用水。","why":"distill comes from Latin distillare 'to drip down', so the verb describes vapour being made to fall as drops.","whyCN":"distill 出自拉丁 distillare「滴下」，这个动词描述的是让蒸气成滴落下。"},{"no":"02","title":"To draw a strong spirit from a mash","titleCN":"蒸馏出酒或烈性液体","definition":"to make a strong alcoholic drink by distilling a fermented liquid","definitionCN":"通过蒸馏发酵液制成烈性酒","example":"They distill the fruit into a strong spirit.","exampleCN":"他们把这种水果蒸馏成烈酒。","why":"alcohol boils before water, so distillation is the classic way to draw it off, and the verb took on the trade.","whyCN":"酒精比水先沸腾，蒸馏正是把它抽出的经典办法，这个动词便承接了这一行业。"},{"no":"03","title":"To extract the essential part","titleCN":"提炼思想或经验的精华","definition":"to reduce a large body of material to its essential content, as if separating a clear liquid from a muddy one","definitionCN":"把大量材料缩减为本质内容，如同从浑浊液中分出清液","example":"The book distills twenty years of research into one volume.","exampleCN":"这本书把二十年研究提炼成一册。","why":"the laboratory operation becomes a mental one: what matters is what survives the heat of selection.","whyCN":"实验室操作变成头脑里的操作：要紧的，是在挑选的加热中留下来的部分。"},{"no":"04","title":"To drip, of a liquid","titleCN":"液体滴下、渗出","definition":"to come out in drops, said of liquid falling from a surface or through a small opening","definitionCN":"以滴状流出，指液体从表面或小口落下","example":"Water distilled from the roof into the gutter.","exampleCN":"水从屋顶滴进排水沟。","why":"the oldest sense is simply 'to drip down', and it survives beside the technical sense.","whyCN":"最古老的义项就是「滴下」，它与技术义并存至今。"},{"no":"05","title":"To form drops from vapour","titleCN":"使蒸气凝结成水滴","definition":"to cause vapour to condense into droplets on a cool surface","definitionCN":"使蒸气在冷表面上凝结成小水珠","example":"Cold glass distills the vapour into droplets.","exampleCN":"冷玻璃使蒸气凝成小水珠。","why":"condensation is the second half of distilling, and the verb can name that half alone.","whyCN":"冷凝是蒸馏的后半段，这个动词可以单独命名这一半。"},{"no":"06","title":"To reduce a text to its points","titleCN":"从大量材料中提取要点","definition":"to shorten a long report or argument to its main points without losing the essential meaning","definitionCN":"把长报告或论证缩到要点，而不丢失本质含义","example":"The editor distilled the report to a single page.","exampleCN":"编辑把报告提炼成了一页。","why":"a text is treated like a mixture: the water goes, the flavour stays.","whyCN":"文本被当作混合物：水走了，味道留下。"},{"no":"07","title":"To purify by removing the rest","titleCN":"通过去除杂质使纯净","definition":"to purify a substance by leaving behind whatever does not vaporize at the chosen temperature","definitionCN":"把在所选温度下不汽化的东西留下，从而提纯物质","example":"The process distills the oil until it is clear.","exampleCN":"这个过程把油蒸馏到清澈为止。","why":"purity in distillation is not added but subtracted: everything else is left in the flask.","whyCN":"蒸馏中的纯度不是加上去的，而是减出来的：其余一切都留在烧瓶里。"},{"no":"08","title":"To keep the core and drop the rest","titleCN":"抽象义：去芜存菁","definition":"used figuratively of any act of keeping what is essential and letting the incidental go","definitionCN":"比喻指任何保留本质、放走偶然成分的行为","example":"Good teaching distills a subject without thinning it.","exampleCN":"好的教学把一门学问提炼，却不把它冲淡。","why":"the abstract sense keeps both parts of the image: heat selects, and condensation preserves.","whyCN":"抽象义保留意象的两半：火负责挑选，冷凝负责保存。"}],"etymology":{"intro":{"en":"Distill comes from Latin distillare 'to drip down', from de- 'down' plus stillare 'to drip', from stilla 'a drop'. English has used the verb since the fourteenth century, with the British spelling distil. Dates are approximate.","cn":"distill 来自拉丁 distillare「滴下」，由 de-「向下」加 stillare「滴」构成，后者出自 stilla「一滴」。英语自十四世纪使用这个动词，英式拼写为 distil。年代均为约数。"},"items":[{"era":"LATIN STILLA","en":"Stilla meant 'a drop', and its deeper origin is not established; any older root proposed for it is a reconstruction.","cn":"stilla 意为「一滴」，其更深来源没有定论，为其提出的更古老词根属于重构。"},{"era":"LATIN STILLARE","en":"Stillare 'to drip' described liquid falling drop by drop, a plain physical verb before it became a technical one.","cn":"stillare「滴」描述液体一滴一滴落下，在成为技术词之前是一个朴素的实体动词。"},{"era":"LATIN DISTILLARE","en":"De- 'down' plus stillare gave distillare 'to drip down', which alchemists used for vapour collected as drops.","cn":"de-「向下」加 stillare 构成 distillare「滴下」，炼金术士用它指把蒸气以滴状收集。"},{"era":"ENGLISH VERB","en":"English distill appears in the fourteenth century for both the dripping and the apparatus, and the spelling distil is usual in British usage.","cn":"英语 distill 在十四世纪同时指滴落与器具，英式用法通常拼作 distil。"},{"era":"FIGURATIVE USE","en":"By the nineteenth century the verb was used for extracting the essence of writing and experience, not only of liquids.","cn":"到十九世纪，这个动词已用于提取写作与经验的精华，不只用于液体。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin origin of stilla is unsettled, so any root offered for it is a reconstruction rather than a demonstrated form.","cn":"来源不确定（更深词源）：stilla 在拉丁语之前的来源没有定论，为其提出的任何词根都是重构形式，而非已证实的形式。"}]},"similar":{"note":{"en":"Group one holds the noun and apparatus of the same family, which share the dripping root; group two holds verbs for taking an essential part out of something.","cn":"第一组是同一家族的名词与器具，共享「滴」词根；第二组是表示从某物中取出本质部分的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"distillation","ipa":"/ˌdɪstɪˈleɪʃn/","tag":"the noun","definition":"The process or its product; the verb names the act that produces it.","definitionCN":"过程或产物；动词命名产生它的动作。"},{"word":"still","ipa":"/stɪl/","tag":"the apparatus","definition":"The vessel used for distilling; it comes from the same dripping root, not from the adverb meaning 'even now'.","definitionCN":"用于蒸馏的容器；出自同一「滴」词根，不来自表示「仍然」的副词。"},{"word":"instill","ipa":"/ɪnˈstɪl/","tag":"drip inward","definition":"In- 'in' plus stillare: to drip an idea into someone, hence to implant it gradually.","definitionCN":"in-「进入」加 stillare：把观念滴进某人心里，因此指逐渐灌输。"},{"word":"distillate","ipa":"/dɪˈstɪleɪt/","tag":"the product","definition":"The condensed liquid collected from the apparatus, named after the action rather than the action itself.","definitionCN":"从装置收集到的冷凝液，以动作命名而非动作本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"extract","ipa":"/ɪkˈstrækt/","tag":"pull out","definition":"To take a substance out with a solvent or force; no vaporizing is involved.","definitionCN":"用溶剂或外力取出物质；不涉及汽化。"},{"word":"refine","ipa":"/rɪˈfaɪn/","tag":"purify quality","definition":"To remove impurities and improve quality; distilling is one way to refine a liquid.","definitionCN":"去除杂质、提高品质；蒸馏是精炼液体的一种方式。"},{"word":"purify","ipa":"/ˈpjʊərɪfaɪ/","tag":"the general goal","definition":"To make something pure by any means, of which distilling is one.","definitionCN":"用任何手段使某物纯净，蒸馏是其中一种。"},{"word":"condense","ipa":"/kənˈdens/","tag":"vapour to liquid","definition":"To turn vapour into liquid or to make a text shorter; it covers only one stage of distilling.","definitionCN":"使蒸气变液，或使文本变短；只覆盖蒸馏的一个阶段。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"De- 'down' plus stillare 'drip': the verb is 'to make drip down'.","cn":"de-「向下」加 stillare「滴」：这个动词就是「使滴下」。"},{"en":"The family runs distill, distil, distillation, distillate, distillery.","cn":"同族词包括 distill、distil、distillation、distillate、distillery。"},{"en":"Fixed phrases mark the technical sense: distill water, distill alcohol.","cn":"固定搭配标出技术义：蒸馏水、蒸馏酒精。"},{"en":"The figurative phrases mark the rest: distill the essence, distill into one volume.","cn":"比喻搭配标出其余义项：提炼精华、提炼成一册。"},{"en":"British spelling doubles nothing: distil, distilled, distilling.","cn":"英式拼写不双写词尾字母：distil、distilled、distilling。"}],"abstract":[{"en":"Picture dew forming on a cold pipe and running into a jar.","cn":"想象冷管上结出露水，流进罐子里。"},{"en":"Picture a long letter cut to the one paragraph that matters.","cn":"想象一封长信被删到唯一要紧的那一段。"},{"en":"Picture a muddy pond producing a glass of clear water.","cn":"想象一潭泥水变出一杯清水。"}]},"examples":[{"en":"The refinery distills crude oil into separate fuels.","cn":"炼油厂把原油蒸馏成不同的燃料。"},{"en":"She distilled the interview transcripts into four themes.","cn":"她把访谈记录提炼成四个主题。"},{"en":"Rainwater distilled through the canvas and dripped onto the floor.","cn":"雨水透过帆布渗下，滴到地板上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dis（分开）+ till（滴）」——让汽一滴滴落下、分开成分：蒸馏、提炼","word":"distill"},"root":"拉丁 distillare「滴下」= de-（向下）+ stillare（滴）；stillare 出自 stilla（一滴），stilla 更深来源不确定。英式拼写 distil。","sensesIntro":{"en":"Eight senses follow one dripping: a liquid is boiled and condensed, a spirit is drawn off, an essence is extracted, drops fall, vapour condenses, a text is shortened, impurities are left behind, and finally only the core is kept.","cn":"八个义项跟着同一次滴落：液体被煮沸再冷凝，烈酒被抽出，精华被提取，液滴落下，蒸气凝结，文本被缩短，杂质被留下，最后只保留核心。"},"semanticMap":{"core":{"en":"CORE IMAGE: vapour travelling along a cool tube, gathering into beads, then falling as one drop.","cn":"核心意象：蒸气沿着冷管走，聚成水珠，最后落成一滴。"},"chain":["BOIL AND CONDENSE","SPIRIT DRAWN OFF","ESSENCE EXTRACTED","DROPS FALL","TEXT SHORTENED","CORE KEPT"],"branches":[{"senses":"01 · 07","en":"SEPARATION AND PURITY: distilling separates by boiling point and purifies by subtracting what stays behind.","cn":"分离与纯净：蒸馏按沸点分离，并通过减去留下的部分达到纯净。"},{"senses":"02","en":"THE STILL TRADE: drawing spirits off a mash is the oldest commercial use of the same process.","cn":"蒸馏行业：从发酵醪中抽出烈酒，是同一过程最古老的商业用途。"},{"senses":"03 · 06","en":"REDUCING MATERIAL: extracting an essence and shortening a report both drop the incidental.","cn":"缩减材料：提取精华与缩短报告，都在放走偶然成分。"},{"senses":"04 · 05","en":"DRIPPING AND CONDENSING: the plain physical sense and the laboratory half-step are one movement of water.","cn":"滴落与凝结：朴素的实体义与实验室的半步，是同一次水的运动。"},{"senses":"08","en":"KEEPING THE CORE: heat selects and condensation preserves, which is what good distillation means in thought.","cn":"保留核心：火负责挑选，冷凝负责保存，这正是思想上「好的提炼」的意思。"}]},"affixes":{"intro":{"en":"Distill is a Latin verb of dripping, and its prefix and root also build the apparatus, the product and the word for implanting an idea.","cn":"distill 是一个表示「滴」的拉丁动词，其前缀与词根还构成器具、产物与「灌输观念」的词。"},"latinIntro":{"en":"Stilla 'a drop' gives stillare and distillare; de- 'down' marks direction, and in- 'in' gives instill.","cn":"stilla「一滴」衍生 stillare 与 distillare；de-「向下」标记方向，in-「进入」构成 instill。"},"items":[{"word":"stilla","structure":"stilla, stillae (f., first declension)","meaning":"a drop","meaningCN":"一滴","example":"The root names the single drop.","exampleCN":"这个词根命名单独的一滴。"},{"word":"stillare","structure":"stillare (Latin verb, first conjugation)","meaning":"to drip","meaningCN":"滴","example":"The verb describes the falling.","exampleCN":"这个动词描述滴落。"},{"word":"de-","structure":"de- (Latin prefix, 'down')","meaning":"down","meaningCN":"向下","example":"The prefix points the fall downward.","exampleCN":"这个前缀把滴落指向下方。"},{"word":"distillare","structure":"de- + stillare","meaning":"to drip down","meaningCN":"滴下","example":"The Latin verb begins the family.","exampleCN":"这个拉丁动词开启词族。"},{"word":"distill","structure":"distillare -> distill","meaning":"to separate by vaporizing","meaningCN":"通过汽化分离","example":"They distill the mixture twice.","exampleCN":"他们把混合物蒸馏两次。"},{"word":"distills","structure":"distill + -s (third person singular)","meaning":"he, she or it distills","meaningCN":"他、她或它进行蒸馏","example":"The unit distills a thousand litres a day.","exampleCN":"这台设备每天蒸馏一千升。"},{"word":"distilled","structure":"distill + -ed (past participle)","meaning":"having been distilled","meaningCN":"已蒸馏过的","example":"Only distilled water was used.","exampleCN":"只用了蒸馏水。"},{"word":"distilling","structure":"distill + -ing (present participle)","meaning":"in the act of distilling","meaningCN":"正在蒸馏","example":"The plant is distilling the new batch.","exampleCN":"工厂正在蒸馏新一批。"},{"word":"distillation","structure":"distill + -ation","meaning":"the process","meaningCN":"蒸馏","example":"Distillation takes several hours.","exampleCN":"蒸馏要花几个小时。"},{"word":"distillery","structure":"distill + -ery (place)","meaning":"a place where distilling is done","meaningCN":"蒸馏厂","example":"The distillery stands beside the river.","exampleCN":"蒸馏厂坐落在河边。"}],"latinEntries":[{"word":"stilla","structure":"stilla, stillae (f., first declension)","meaning":"a drop","meaningCN":"一滴"},{"word":"stillare","structure":"stillare, stillavi, stillatum (verb, first conjugation)","meaning":"to drip","meaningCN":"滴"},{"word":"distillare","structure":"distillare, distillavi, distillatum (verb, first conjugation)","meaning":"to drip down","meaningCN":"滴下"},{"word":"distillatio","structure":"distillatio, distillationis (f., third declension)","meaning":"a dripping down, distillation","meaningCN":"滴下；蒸馏"}]}},{"word":"filtration","ipa_uk":"/ˌfɪlˈtreɪʃn/","ipa_us":"/ˌfɪlˈtreɪʃn/","definition_zh":"过滤；滤除；（信息、人员的）筛选","definition_en":"the process of passing a liquid or gas through a material that holds back solid particles, or the screening of information or people","core_image":"一张滤纸托住浑浊的泥水，滴下来的却是清水","scene":"实验室里，学生把浑浊的泥水倒进架在烧杯上的滤纸，滴下来的水变清了。Filtration removed the fine sediment and left clear water below.","sceneCN":"这里 filtration 指用多孔介质截留固体、让液体通过的过程（第 1 个义项：过滤过程）；句意为过滤去掉了细泥沙，下面留下清水。图中可辨识物件：滤纸、漏斗、烧杯、泥水。","pos":[{"tag":"n.","zh":"过滤；滤除（不可数）"},{"tag":"n.","zh":"筛选、审查（信息或人员）"}],"collocations":[{"phrase":"water filtration","zh":"水过滤"},{"phrase":"air filtration","zh":"空气过滤"},{"phrase":"filtration system","zh":"过滤系统"},{"phrase":"filtration rate","zh":"过滤速率"},{"phrase":"glomerular filtration","zh":"肾小球滤过"},{"phrase":"filtration of information","zh":"信息筛选"}],"forms":[{"label":"不可数名词","form":"filtration"},{"label":"动词","form":"filter"},{"label":"名词（滤液）","form":"filtrate"},{"label":"名词（过滤器）","form":"filter"},{"label":"相关形容词","form":"filtrated"},{"label":"相关名词（渗入）","form":"infiltration"}],"derivatives":[{"word":"filter","pos":"n./v.","zh":"过滤器／过滤"},{"word":"filtrate","pos":"n.","zh":"滤液"},{"word":"infiltrate","pos":"v.","zh":"渗入；渗透"},{"word":"infiltration","pos":"n.","zh":"渗入；渗透"},{"word":"filterable","pos":"adj.","zh":"可过滤的"}],"senses":[{"no":"01","title":"Passing liquid through a barrier","titleCN":"让液体通过多孔介质、截留固体","definition":"the process of passing a liquid or gas through a porous material that holds back particles too large to go through","definitionCN":"让液体或气体通过多孔材料，截住大到过不去的颗粒","example":"Filtration removed the fine sediment and left clear water below.","exampleCN":"过滤去掉了细泥沙，下面留下清水。","why":"filtration comes from Medieval Latin filtrum 'felt', the cheap cloth first used as a strainer, so the word is an object turned into a process.","whyCN":"filtration 出自中世纪拉丁 filtrum「毛毡」，最早就是用作滤布的廉价毡，因此这个词是「物」变成了「过程」。"},{"no":"02","title":"A laboratory separation step","titleCN":"实验室的一次过滤操作","definition":"the routine step of separating a solid residue from a liquid by pouring it through filter paper","definitionCN":"把固体残渣与液体分开的常规步骤，通常用滤纸","example":"The residue was gathered by filtration and dried.","exampleCN":"残渣通过过滤被收集起来并干燥。","why":"the process is a standard step in analysis, so the noun also names one pass through the apparatus.","whyCN":"这个过程是分析中的标准步骤，因此名词也指一次通过装置的操作。"},{"no":"03","title":"Water passing through sand and filters","titleCN":"水处理中的过滤","definition":"the stage in water treatment in which water is passed through sand or another medium to remove suspended matter","definitionCN":"水处理中让水通过砂层或其他介质以去除悬浮物的阶段","example":"Sand filtration is the last step before water reaches the tap.","exampleCN":"砂滤是水到达水龙头前的最后一步。","why":"municipal treatment applies the same barrier at a large scale, where sand replaces the laboratory paper.","whyCN":"市政处理把同一道屏障放大，砂层取代了实验室的滤纸。"},{"no":"04","title":"The kidney's filtering of blood","titleCN":"肾脏对血液的滤过","definition":"the physiological process in which the kidney passes blood plasma through a membrane and retains cells and large proteins","definitionCN":"肾脏让血浆通过膜、截留细胞与大分子蛋白的生理过程","example":"The kidney's filtration of blood removes waste while keeping protein.","exampleCN":"肾脏对血液的滤过清除废物而保留蛋白质。","why":"a living membrane is a filter in the literal sense, so physiology borrowed the industrial word.","whyCN":"生物膜就是字面意义上的滤器，因此生理学借用了工业词汇。"},{"no":"05","title":"Screening of applications or people","titleCN":"对申请或人员的筛选审查","definition":"the process of examining information or people and removing those that fail a standard","definitionCN":"审查信息或人员、剔除不合标准者的过程","example":"The filtration of applications took three weeks.","exampleCN":"对申请的筛选用了三周。","why":"a filter keeps what is wanted and lets the rest through or out, which is exactly what a review process does.","whyCN":"滤器留下想要的、放走其余，审查过程做的正是这件事。"},{"no":"06","title":"Removing errors in stages","titleCN":"分阶段筛除错误或不合格项","definition":"the repeated removal of unwanted items from a body of data or material, one layer at a time","definitionCN":"从一批数据或材料中逐层去除不想要的项目","example":"Repeated filtration of the data removed obvious errors.","exampleCN":"对数据反复筛选，去掉了明显的错误。","why":"one pass catches coarse particles and later passes catch finer ones, so a review is naturally described as staged.","whyCN":"第一遍截住粗颗粒，后面几遍截住更细的，因此审查天然被说成分阶段。"},{"no":"07","title":"Cleaning air through a mask","titleCN":"口罩或滤网对空气的过滤","definition":"the removal of fine particles from air by a fabric or a fibrous filter","definitionCN":"用织物或纤维滤材去除空气中的细颗粒","example":"The mask relies on filtration of fine particles.","exampleCN":"这只口罩依靠对细颗粒的过滤。","why":"air is treated as a fluid like water, and the same barrier image applies to what is breathed.","whyCN":"空气被当作像水一样的流体，同一种屏障意象也用到了呼吸之物上。"},{"no":"08","title":"Keeping only what is reliable","titleCN":"抽象义：逐层筛掉杂质留下核心","definition":"used figuratively of any process that removes noise, bias or error until only the trustworthy part remains","definitionCN":"比喻指任何去除噪音、偏见或错误直到只剩可信部分的过程","example":"Filtration of the evidence left one reliable account.","exampleCN":"对证据的筛选最后只剩一份可靠的叙述。","why":"the abstract sense keeps the barrier and replaces particles with unreliable claims.","whyCN":"抽象义保留屏障，把颗粒换成了不可靠的说法。"}],"etymology":{"intro":{"en":"Filtration is formed on filter, from Medieval Latin filtrum 'felt', a word borrowed from a Germanic term for felt. English filter is recorded from the fifteenth century and filtration from the seventeenth. Dates are approximate.","cn":"filtration 由 filter 构成，后者来自中世纪拉丁 filtrum「毛毡」，这个词借自日耳曼语中表示毛毡的词。英语 filter 自十五世纪有记录，filtration 自十七世纪。年代均为约数。"},"items":[{"era":"GERMANIC FILT","en":"The Germanic word for felt, reconstructed as a form meaning 'felt', is the ultimate source; it is a reconstruction, since no written form from that stage survives.","cn":"表示「毛毡」的日耳曼词是最终来源，其形式被重构为表示「毡」的词；这属于重构形式，因为该阶段没有书面形式留存。"},{"era":"MEDIEVAL LATIN FILTRUM","en":"Medieval Latin filtrum meant 'felt' and then 'a strainer made of felt', because felt was the cheapest cloth that let water through while holding solids back.","cn":"中世纪拉丁 filtrum 意为「毛毡」，继而指「毛毡滤器」，因为毡是最便宜、能让水通过又截住固体的布。"},{"era":"ENGLISH FILTER","en":"English borrowed filter in the fifteenth century for the strainer itself, and the verb followed in the sixteenth.","cn":"英语在十五世纪借入 filter 指滤器本身，十六世纪出现动词用法。"},{"era":"ENGLISH FILTRATION","en":"Filtration appears in the seventeenth century as the name of the process, modelled on the Latin action noun.","cn":"filtration 在十七世纪作为过程名称出现，仿拉丁动作名词构成。"},{"era":"MODERN USE","en":"Water treatment, physiology and computing each took the word over, so filtration now covers sand beds, kidney membranes and the screening of information.","cn":"水处理、生理学与计算各自接管这个词，于是 filtration 现在覆盖砂床、肾膜与信息筛选。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (earliest form): the Germanic term behind filtrum is reconstructed rather than recorded, and the exact date of the first English use of the figurative sense is not established.","cn":"来源不确定（最早形式）：filtrum 背后的日耳曼词属于重构而非记录，比喻义在英语中最早使用的确切年代没有定论。"}]},"similar":{"note":{"en":"Group one holds the apparatus, the verb and the product of the same family; group two holds other separating operations that do not use a barrier.","cn":"第一组是同一家族的器具、动词与产物；第二组是不使用屏障的其他分离操作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"filter","ipa":"/ˈfɪltə/","tag":"the device and the verb","definition":"The barrier itself or the act of passing liquid through it; filtration is the process as a whole.","definitionCN":"屏障本身或让液体通过的动作；filtration 是整个流程。"},{"word":"filtrate","ipa":"/ˈfɪltreɪt/","tag":"what came through","definition":"The clear liquid that has passed through the filter, as opposed to the residue left on it.","definitionCN":"通过滤器后得到的清液，与被留在滤器上的残渣相对。"},{"word":"felt","ipa":"/felt/","tag":"the original material","definition":"The cloth that gave the Latin word its name; it is a cousin through Germanic, not a Latin relative.","definitionCN":"给拉丁词命名的布；经日耳曼语与之同源，并非拉丁亲属。"},{"word":"infiltration","ipa":"/ˌɪnflɪˈtreɪʃn/","tag":"moving in, not out","definition":"The passage of water or people into something; the prefix reverses the direction of the same root.","definitionCN":"水或人进入某物；前缀把同一词根的方向反转。"}]},{"heading":"NEAR MEANING","entries":[{"word":"screening","ipa":"/ˈskriːnɪŋ/","tag":"checking, not straining","definition":"Examining people or things to sort them; it shares the figurative sense but not the physical barrier.","definitionCN":"检查人或物以分类；共享比喻义，但没有实体屏障。"},{"word":"straining","ipa":"/ˈstreɪnɪŋ/","tag":"kitchen-level filtering","definition":"Passing food or liquid through a sieve or cloth; the everyday word for a small filtration.","definitionCN":"让食物或液体通过筛网或布；小规模过滤的日常说法。"},{"word":"purification","ipa":"/ˌpjʊərɪfɪˈkeɪʃn/","tag":"the goal","definition":"Making something pure by any method; filtration is one method that reaches that goal.","definitionCN":"用任何方法使某物纯净；过滤是达到该目标的一种方法。"},{"word":"separation","ipa":"/ˌsepəˈreɪʃn/","tag":"the broad category","definition":"Any splitting of a mixture into parts; filtration is one kind of separation.","definitionCN":"把混合物分成若干部分的任何做法；过滤是分离的一种。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Filtrum was felt: the first filter was a piece of cloth, and the process took the cloth's name.","cn":"filtrum 就是毛毡：最早的滤器是一块布，流程沿用了布的名字。"},{"en":"The family runs filter, filtration, filtrate, infiltrate, infiltration.","cn":"同族词包括 filter、filtration、filtrate、infiltrate、infiltration。"},{"en":"Fixed phrases mark the technical senses: water filtration, air filtration, filtration system.","cn":"固定搭配标出技术义：水过滤、空气过滤、过滤系统。"},{"en":"Physiology says glomerular filtration, the kidney's own barrier.","cn":"生理学说肾小球滤过，即肾脏自己的屏障。"},{"en":"The figurative phrase is filtration of information, where claims are the particles.","cn":"比喻说法是信息筛选，那里被截住的颗粒是各种说法。"}],"abstract":[{"en":"Picture muddy water on one side of a paper and clear water on the other.","cn":"想象纸的一边是泥水，另一边是清水。"},{"en":"Picture a long list of names with most of them crossed out.","cn":"想象一长串名字，其中大多数被划掉。"},{"en":"Picture a window screen holding dust while air passes through.","cn":"想象纱窗拦住灰尘，空气却穿了过去。"}]},"examples":[{"en":"The first stage of the plant is filtration through a bed of sand.","cn":"这座工厂的第一阶段是让水通过砂床过滤。"},{"en":"Filtration of the sample left a thin layer of chalk on the paper.","cn":"样品过滤后在纸上留下一薄层白垩。"},{"en":"The agency described its review as a filtration of unreliable claims.","cn":"该机构把审查描述为对不可靠说法的筛选。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fil（毡布）+ tration」——用毡布把浑水挡住：过滤、筛选","word":"filtration"},"root":"中世纪拉丁 filtrum「毛毡、毡制滤器」+ -atio（动作名词）；filtrum 借自日耳曼语表示毛毡的词，该词形式为重构。英语以 filter + -ation 构成 filtration。","sensesIntro":{"en":"Eight senses follow one barrier: liquid passes while solids stay behind, a laboratory step is named, sand cleans a city's water, a kidney membrane does the same inside the body, applications are screened, data is cleaned in stages, air is cleaned through a mask, and finally unreliable claims are held back.","cn":"八个义项跟着同一道屏障：液体通过、固体留下，实验室的一步被命名，砂层净化城市的水，肾膜在体内做同样的事，申请被筛选，数据被逐层清理，空气经口罩被净化，最后不可靠的说法被截住。"},"semanticMap":{"core":{"en":"CORE IMAGE: muddy water resting on filter paper while clear drops fall into the flask below.","cn":"核心意象：泥水停在滤纸上，清水滴进下面的烧瓶。"},"chain":["BARRIER HOLDS SOLIDS","CLEAR LIQUID PASSES","LAB STEP","SAND AND MEMBRANES","PEOPLE SCREENED","CLAIMS HELD BACK"],"branches":[{"senses":"01 · 02","en":"THE PHYSICAL PROCESS: the barrier and the single laboratory step are the same operation at two levels of description.","cn":"实体过程：屏障与一次实验室操作，是同一动作的两种描述层级。"},{"senses":"03 · 07","en":"SCALES OF CLEANING: sand beds and mask fibres are the same barrier sized for cities and for breath.","cn":"净化的尺度：砂床与口罩纤维，是按城市与呼吸定尺寸的同一道屏障。"},{"senses":"04","en":"THE BODY'S FILTER: a kidney membrane is a literal filter, which is why the industrial word fits.","cn":"体内的滤器：肾膜就是字面意义上的滤器，因此工业词用得合适。"},{"senses":"05 · 06","en":"SCREENING: reviewing applications and cleaning data both remove what fails a standard, one layer at a time.","cn":"筛选：审查申请与清理数据，都逐层去除不合标准的东西。"},{"senses":"08","en":"TRUSTWORTHY RESIDUE: after unreliable claims are held back, what passes through is the account worth keeping.","cn":"可信的留存：不可靠的说法被截住后，通过的是值得保留的叙述。"}]},"affixes":{"intro":{"en":"Filtration is a Medieval Latin noun of felt plus an action ending, and the root still builds the device, the product and the word for seeping in.","cn":"filtration 是一个表示「毛毡」的中世纪拉丁名词加动作词尾，这个词根仍构成装置、产物与表示「渗入」的词。"},"latinIntro":{"en":"Filtrum 'felt' gives filter and filtration; -ation names the process, and in- 'in' gives infiltrate, the movement the other way.","cn":"filtrum「毛毡」衍生 filter 与 filtration；-ation 命名过程，in-「进入」构成 infiltrate，即反方向的移动。"},"items":[{"word":"filtrum","structure":"filtrum, filtri (n., second declension)","meaning":"felt; a felt strainer","meaningCN":"毛毡；毡制滤器","example":"The noun names the original material.","exampleCN":"这个名词命名最初的材质。"},{"word":"-ation","structure":"-ation (from Latin -atio, action noun)","meaning":"an action or process","meaningCN":"动作或过程","example":"The ending turns filter into a process name.","exampleCN":"这个词尾把 filter 变成过程名称。"},{"word":"filter","structure":"filtrum -> filter","meaning":"a strainer; to pass through one","meaningCN":"滤器；过滤","example":"The filter caught the sediment.","exampleCN":"滤器截住了泥沙。"},{"word":"filtration","structure":"filter + -ation","meaning":"the process of filtering","meaningCN":"过滤过程","example":"Filtration took twenty minutes.","exampleCN":"过滤用了二十分钟。"},{"word":"filtrate","structure":"filter + -ate (result)","meaning":"the liquid that passed through","meaningCN":"滤液","example":"The filtrate was clear and colourless.","exampleCN":"滤液清澈无色。"},{"word":"filterable","structure":"filter + -able (can be)","meaning":"able to be filtered","meaningCN":"可过滤的","example":"The particles are filterable.","exampleCN":"这些颗粒可以被滤掉。"},{"word":"infiltrate","structure":"in- (in) + filtrum","meaning":"to seep in","meaningCN":"渗入","example":"Rain infiltrates the sandy soil.","exampleCN":"雨水渗进沙质土壤。"},{"word":"infiltration","structure":"infiltrate + -ion","meaning":"the act of seeping in","meaningCN":"渗入；渗透","example":"Infiltration refilled the groundwater.","exampleCN":"渗入补给了地下水。"},{"word":"felt","structure":"Germanic root shared with filtrum","meaning":"the cloth itself","meaningCN":"毛毡本身","example":"The old strainer was made of felt.","exampleCN":"那个旧滤器是用毛毡做的。"},{"word":"filters","structure":"filter + -s (plural)","meaning":"more than one filter","meaningCN":"多个滤器","example":"The system uses three filters in series.","exampleCN":"这套系统串联使用三个滤器。"}],"latinEntries":[{"word":"filtrum","structure":"filtrum, filtri (n., second declension)","meaning":"felt; a strainer","meaningCN":"毛毡；滤器"},{"word":"filtrare","structure":"filtrare, filtravi, filtratum (verb, first conjugation)","meaning":"to strain, filter","meaningCN":"过滤；滤清"},{"word":"filtratio","structure":"filtratio, filtrationis (f., third declension)","meaning":"a filtering","meaningCN":"过滤"},{"word":"filtratus","structure":"filtratus, filtrata, filtratum (past participle)","meaning":"filtered","meaningCN":"过滤过的"}]}},{"word":"filter","ipa_uk":"/ˈfɪltə/","ipa_us":"/ˈfɪltər/","definition_zh":"过滤器；滤网；滤镜；过滤；筛除","definition_en":"a device or material that holds back solid particles while letting liquid or gas through, or to pass something through such a device","core_image":"一层细网拦住沙粒，水从网眼里一条条落下","scene":"厨房里，店员把一壶浑水倒进漏斗里的滤网，网眼上留下一层细沙，壶里落下的水是清的。The filter held back the grit and let the water through.","sceneCN":"这里 filter 指截留固体、让液体通过的多孔装置（第 1 个义项：过滤器）；句意为滤网截住砂砾，让水通过。图中可辨识物件：漏斗、滤网、砂砾、水壶。","pos":[{"tag":"n.","zh":"过滤器；滤网；滤镜；滤嘴"},{"tag":"vt.","zh":"过滤；筛除；筛选"},{"tag":"vi.","zh":"（光、声音）慢慢透过"}],"collocations":[{"phrase":"water filter","zh":"滤水器"},{"phrase":"air filter","zh":"空气滤清器"},{"phrase":"filter out","zh":"滤除；筛掉"},{"phrase":"filter paper","zh":"滤纸"},{"phrase":"light filter","zh":"滤光片"},{"phrase":"spam filter","zh":"垃圾邮件过滤器"}],"forms":[{"label":"单数名词","form":"filter"},{"label":"复数名词","form":"filters"},{"label":"三单（he/she/it）","form":"filters"},{"label":"过去式","form":"filtered"},{"label":"过去分词","form":"filtered"},{"label":"现在分词","form":"filtering"}],"derivatives":[{"word":"filtration","pos":"n.","zh":"过滤"},{"word":"filtrate","pos":"n.","zh":"滤液"},{"word":"filterable","pos":"adj.","zh":"可过滤的"},{"word":"infiltrate","pos":"v.","zh":"渗入"},{"word":"filtered","pos":"adj.","zh":"过滤过的"}],"senses":[{"no":"01","title":"A device that holds solids back","titleCN":"截留固体的过滤装置","definition":"a device or layer of material that lets liquid or gas pass while catching particles that are too large to go through","definitionCN":"让液体或气体通过、同时拦住过大颗粒的装置或材料层","example":"The filter caught the sediment.","exampleCN":"滤器截住了泥沙。","why":"filter comes from Medieval Latin filtrum 'felt', the cloth first used as a strainer, so the noun began as the material itself.","whyCN":"filter 出自中世纪拉丁 filtrum「毛毡」，最早就是当滤布用的毡，因此名词起初指材料本身。"},{"no":"02","title":"A coloured glass for light","titleCN":"摄影用滤光片、滤镜","definition":"a piece of glass or gel placed in front of a lens to absorb some wavelengths of light","definitionCN":"放在镜头前吸收某些波长光线的玻璃片或胶膜","example":"A red filter darkened the sky.","exampleCN":"红色滤镜把天空压暗了。","why":"light is treated as a fluid whose parts can be held back, so an optical filter uses the same verb as a water filter.","whyCN":"光被当作可截留某些成分的流体，因此光学滤镜与水滤器共用同一个动词。"},{"no":"03","title":"The tip of a cigarette","titleCN":"香烟滤嘴","definition":"the short plug of fibre or charcoal at the end of a cigarette that traps some tar and smoke particles","definitionCN":"香烟末端的一小段纤维或炭，截住部分焦油与烟粒","example":"The cigarette has a charcoal filter.","exampleCN":"这支香烟有炭滤嘴。","why":"smoke is a stream carrying particles, so the small barrier at the mouth repeats the industrial device in miniature.","whyCN":"烟雾是携带颗粒的气流，嘴端的小屏障就是工业装置的小型翻版。"},{"no":"04","title":"To pass liquid or air through a device","titleCN":"过滤液体或空气","definition":"to pass a liquid or gas through a device in order to remove solid particles from it","definitionCN":"让液体或气体通过装置，以去除其中的固体颗粒","example":"The system filters the air in the room.","exampleCN":"这套系统过滤房间里的空气。","why":"the verb is the device turned into an action: what the filter does, the sentence says the user does.","whyCN":"动词是把装置变成动作：滤器所做的事，句子说成使用者所做的事。"},{"no":"05","title":"To remove something unwanted","titleCN":"滤除、筛掉不需要的东西","definition":"to remove unwanted items from a flow, often with out, so that they do not reach the next stage","definitionCN":"把不需要的东西从流中移除，常与表示出去的小品词连用，使其到不了下一阶段","example":"The software filters out spam.","exampleCN":"这个软件筛掉垃圾邮件。","why":"what is caught by a filter is discarded, so the verb came to mean removal rather than merely passing through.","whyCN":"被滤器截住的东西会被丢弃，因此动词也指移除，而不只是通过。"},{"no":"06","title":"To examine before allowing through","titleCN":"对信息或人员先行筛选","definition":"to review information, applications or people and allow only those that meet a standard to continue","definitionCN":"审查信息、申请或人员，只让符合标准者继续","example":"Editors filter the reports before they reach the minister.","exampleCN":"报告送到部长之前先由编辑筛选。","why":"a filter decides what passes, and a review desk makes exactly that decision about documents and people.","whyCN":"滤器决定什么能通过，审阅台对文件与人做的正是这个决定。"},{"no":"07","title":"To seep gradually through","titleCN":"光、声音慢慢透过","definition":"to pass slowly and in small amounts through a material or an opening, said of light, sound or liquid","definitionCN":"以少量、缓慢的方式穿过材料或缝隙，用于光、声音或液体","example":"Morning light filtered through the curtains.","exampleCN":"晨光透过窗帘慢慢照进来。","why":"the intransitive sense keeps the barrier in view: something gets through it gradually, as water through cloth.","whyCN":"不及物义保留屏障：某物像水穿过布那样一点点透过去。"},{"no":"08","title":"To decide who may take part","titleCN":"抽象义：只让一部分通过","definition":"used figuratively of any rule, custom or system that decides which people, ideas or voices are admitted","definitionCN":"比喻指决定哪些人、观念或声音能被接纳的任何规则、习俗或制度","example":"Every rule filters who gets to speak.","exampleCN":"每条规则都在筛选谁有发言机会。","why":"the abstract sense turns the barrier into a gatekeeper, with no liquid involved at all.","whyCN":"抽象义把屏障变成守门人，完全不涉及液体。"}],"etymology":{"intro":{"en":"Filter comes from Medieval Latin filtrum 'felt, felt strainer', borrowed from a Germanic word for felt. English took the noun in the fifteenth century and the verb in the sixteenth. Dates are approximate.","cn":"filter 来自中世纪拉丁 filtrum「毛毡、毡制滤器」，借自日耳曼语中表示毛毡的词。英语在十五世纪借入名词，十六世纪出现动词。年代均为约数。"},"items":[{"era":"GERMANIC FILT","en":"The Germanic term for felt is reconstructed as a form meaning 'felt'; it is not recorded in writing at that stage and is offered as a reconstruction.","cn":"表示毛毡的日耳曼词被重构为一个意为「毡」的形式；该阶段没有书面记录，这里给出的是重构形式。"},{"era":"MEDIEVAL LATIN FILTRUM","en":"Filtrum first meant 'felt' and then 'a strainer of felt', because felt was cheap, porous and good at holding solids while letting water through.","cn":"filtrum 先指「毛毡」，再指「毡制滤器」，因为毡便宜、多孔，既能截住固体又能让水通过。"},{"era":"ENGLISH NOUN","en":"English filter appears in the fifteenth century for the strainer itself, at first in medical and household recipes.","cn":"英语 filter 在十五世纪指滤器本身，最早见于医学与家用配方。"},{"era":"ENGLISH VERB","en":"The verb followed in the sixteenth century, and the modern sense of removing unwanted things grew from it.","cn":"动词在十六世纪出现，「去除不需要之物」的现代义由它发展而来。"},{"era":"MODERN EXTENSIONS","en":"Optics, computing and public administration each added a sense: coloured glass, spam rules and the screening of people and reports.","cn":"光学、计算与公共行政各添一义：有色玻璃、垃圾邮件规则，以及对人与报告的筛选。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (earliest form): the Germanic word behind filtrum is reconstructed rather than recorded, and no exact date is fixed for the first optical use.","cn":"来源不确定（最早形式）：filtrum 背后的日耳曼词属于重构而非记录，光学义最早使用的确切年代没有定论。"}]},"similar":{"note":{"en":"Group one holds the process noun, the product and the original material of the same root; group two holds devices and actions that separate by other means.","cn":"第一组是同根的过程名词、产物与原始材料；第二组是用其他方式分离的装置与动作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"filtration","ipa":"/ˌfɪlˈtreɪʃn/","tag":"the process","definition":"The process as a whole; filter is the device that carries it out.","definitionCN":"整个流程；filter 是执行它的装置。"},{"word":"filtrate","ipa":"/ˈfɪltreɪt/","tag":"what passed through","definition":"The clear liquid that came through; the solid left on the filter is the residue.","definitionCN":"透过的清液；留在滤器上的固体是残渣。"},{"word":"felt","ipa":"/felt/","tag":"the original cloth","definition":"The material that gave the word its name, related through Germanic rather than through Latin.","definitionCN":"给这个词命名的材料，经日耳曼语而非拉丁语相关。"},{"word":"infiltrate","ipa":"/ˈɪnflɪtreɪt/","tag":"seep in","definition":"In- 'in' plus the same root: to pass into something gradually, in the opposite direction.","definitionCN":"in-「进入」加同一词根：逐渐进入某物，方向相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"strainer","ipa":"/ˈstreɪnə/","tag":"kitchen device","definition":"A mesh or perforated bowl used in cooking; it catches large pieces rather than fine particles.","definitionCN":"厨房用的网筛或有孔碗；截住大块而非细颗粒。"},{"word":"sieve","ipa":"/siːv/","tag":"sizing by holes","definition":"A mesh that sorts solids by size, letting small grains through and keeping large ones.","definitionCN":"按大小分选固体的网，让细粒通过、留下大粒。"},{"word":"screen","ipa":"/skriːn/","tag":"broad barrier","definition":"A large mesh or a review barrier; it is the general word for a filter that keeps things out.","definitionCN":"大网或审查屏障；是把东西挡在外面的通用词。"},{"word":"purifier","ipa":"/ˈpjʊərɪfaɪə/","tag":"the goal in a device","definition":"A device that makes something pure, often by filtering, but also by chemicals or light.","definitionCN":"使某物纯净的装置，常用过滤，也用化学或光照。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Filtrum was felt: the cloth became the device and then the action.","cn":"filtrum 就是毛毡：布先变成装置，再变成动作。"},{"en":"The family runs filter, filters, filtered, filtering, filtration, filtrate.","cn":"同族词包括 filter、filters、filtered、filtering、filtration、filtrate。"},{"en":"Fixed phrases mark the device: water filter, air filter, filter paper.","cn":"固定搭配标出装置义：滤水器、空气滤清器、滤纸。"},{"en":"The phrasal verb filter out marks removal, and the same phrase works for spam and for people.","cn":"表示「滤除」的短语说法标出移除义，同一个说法既用于垃圾邮件也用于人。"},{"en":"Light, sound and rumours all filter through, slowly and in small amounts.","cn":"光、声音与传言都能透过，缓慢而少量地渗出。"}],"abstract":[{"en":"Picture a gate that opens for some visitors and stays shut for others.","cn":"想象一扇门对某些访客打开，对另一些人关着。"},{"en":"Picture a colander holding the pasta while the water runs away.","cn":"想象漏勺留住面条，水却流走。"},{"en":"Picture every letter passing a desk where one person decides who reads it.","cn":"想象每封信都经过一张桌子，由一个人决定谁可以读。"}]},"examples":[{"en":"Change the water filter twice a year or the flow will slow.","cn":"滤水器每半年换一次，否则水流会变慢。"},{"en":"The app filters out messages from unknown senders.","cn":"这个应用会筛掉陌生发送者的消息。"},{"en":"A thin curtain filtered the afternoon light into the room.","cn":"一层薄帘把午后的光过滤进房间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fil（毡布）+ ter」——毡布挡沙、水却过：过滤器、过滤","word":"filter"},"root":"中世纪拉丁 filtrum「毛毡、毡制滤器」，借自日耳曼语表示毛毡的词（该形式为重构）。英语十五世纪借入名词，十六世纪用作动词。","sensesIntro":{"en":"Eight senses follow one barrier: a mesh holds solids, coloured glass holds back wavelengths, a cigarette tip holds tar, air and water are passed through, unwanted items are removed, applications are reviewed, light seeps in, and finally a rule decides who may speak.","cn":"八个义项跟着同一道屏障：网拦住固体，有色玻璃拦住某些波长，烟嘴拦住焦油，空气与水被送过装置，不需要的东西被移除，申请被审查，光透进来，最后是规则决定谁可以发言。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fine mesh holding grit while clear water falls through it.","cn":"核心意象：细网拦住砂砾，清水却从网眼落下。"},"chain":["MESH HOLDS BACK","LIGHT FILTERED","SMOKE FILTERED","AIR AND WATER PASSED","UNWANTED REMOVED","GATEKEEPER DECIDES"],"branches":[{"senses":"01 · 02","en":"BARRIERS FOR MATTER AND LIGHT: a mesh and a coloured glass both withhold part of what passes.","cn":"物质与光的屏障：网与有色玻璃都截留通过之物的某一部分。"},{"senses":"03","en":"MINIATURE BARRIER: a cigarette tip repeats the industrial device at the scale of a breath.","cn":"微缩屏障：烟嘴以一次呼吸的尺度重复工业装置。"},{"senses":"04 · 05","en":"PASSING AND REMOVING: running air through a device and deleting what it caught are two ends of one action.","cn":"通过与移除：把空气送过装置与删掉被截住的东西，是同一动作的两端。"},{"senses":"06","en":"REVIEW DESK: documents and people are passed through a standard before they continue.","cn":"审阅台：文件与人先经过标准筛选，再继续往前。"},{"senses":"07 · 08","en":"SEEPING AND ADMITTING: light gets through gradually, and a rule decides who gets through at all.","cn":"透过与准入：光一点点透进来，规则决定谁根本能进来。"}]},"affixes":{"intro":{"en":"Filter is a borrowed Medieval Latin noun that became a verb, and its root still builds the process, the product and the word for seeping in.","cn":"filter 是一个借入的中世纪拉丁名词，后来成为动词，其词根仍构成过程、产物与表示「渗入」的词。"},"latinIntro":{"en":"Filtrum 'felt' gives filter and filtration; -ate gives filtrate, the liquid that passed, and in- gives infiltrate.","cn":"filtrum「毛毡」衍生 filter 与 filtration；-ate 构成 filtrate，即透过的液体；in- 构成 infiltrate。"},"items":[{"word":"filtrum","structure":"filtrum, filtri (n., second declension)","meaning":"felt; strainer","meaningCN":"毛毡；滤器","example":"The noun names the cloth.","exampleCN":"这个名词命名那块布。"},{"word":"filter","structure":"filtrum -> filter (noun and verb)","meaning":"strainer; to strain","meaningCN":"滤器；过滤","example":"The filter is clogged.","exampleCN":"滤器堵住了。"},{"word":"filters","structure":"filter + -s (plural or third person)","meaning":"more than one filter, or he filters","meaningCN":"多个滤器，或他过滤","example":"The plant filters the water twice.","exampleCN":"工厂把水过滤两次。"},{"word":"filtered","structure":"filter + -ed (past tense or participle)","meaning":"passed through a filter","meaningCN":"经过过滤的","example":"The filtered water is stored in tanks.","exampleCN":"过滤后的水储存在罐里。"},{"word":"filtering","structure":"filter + -ing (present participle)","meaning":"in the act of filtering","meaningCN":"正在过滤","example":"The machine is filtering the oil.","exampleCN":"机器正在过滤油。"},{"word":"filtration","structure":"filter + -ation","meaning":"the process","meaningCN":"过滤","example":"Filtration removes the last particles.","exampleCN":"过滤去除最后的颗粒。"},{"word":"filtrate","structure":"filter + -ate (result)","meaning":"the liquid that passed through","meaningCN":"滤液","example":"The filtrate was kept for testing.","exampleCN":"滤液被留下检测。"},{"word":"filterable","structure":"filter + -able (can be)","meaning":"able to be filtered","meaningCN":"可过滤的","example":"The powder is not filterable.","exampleCN":"这种粉末无法过滤。"},{"word":"infiltrate","structure":"in- (in) + filtrum","meaning":"to seep in","meaningCN":"渗入","example":"Water infiltrates the gravel.","exampleCN":"水渗进砾石。"},{"word":"felt","structure":"Germanic root shared with filtrum","meaning":"the cloth","meaningCN":"毛毡","example":"The hat is made of felt.","exampleCN":"这顶帽子是毛毡做的。"}],"latinEntries":[{"word":"filtrum","structure":"filtrum, filtri (n., second declension)","meaning":"felt; strainer","meaningCN":"毛毡；滤器"},{"word":"filtrare","structure":"filtrare, filtravi, filtratum (verb, first conjugation)","meaning":"to strain, filter","meaningCN":"过滤；滤清"},{"word":"filtratio","structure":"filtratio, filtrationis (f., third declension)","meaning":"a filtering","meaningCN":"过滤"},{"word":"filtratus","structure":"filtratus, filtrata, filtratum (past participle)","meaning":"filtered","meaningCN":"过滤过的"}]}},{"word":"filtration process","ipa_uk":"/ˌfɪlˈtreɪʃn ˈprəʊses/","ipa_us":"/ˌfɪlˈtreɪʃn ˈprɑːses/","definition_zh":"过滤流程；过滤工序","definition_en":"a sequence of steps in which a liquid or gas is passed through a barrier that holds back solid particles","core_image":"水从进水口流进砂层，穿过一层层砂砾，从底部滴出清水","scene":"水厂的砂滤池里，浑水从上方流入，穿过厚厚的砂层，从池底流出时已经变清。The filtration process removes particles at every metre of sand.","sceneCN":"这里 filtration process 指把固体从液体中分离的整套操作步骤（第 1 个义项：过滤工艺流程）；句意为这套过滤流程在每一米砂层里都在去除颗粒。图中可辨识物件：砂滤池、进水口、砂层、出水口。","pos":[{"tag":"n.","zh":"过滤流程；过滤工序（可数）"},{"tag":"n.","zh":"（信息或人员的）筛选流程"}],"collocations":[{"phrase":"water filtration process","zh":"水过滤流程"},{"phrase":"two-stage filtration process","zh":"两级过滤流程"},{"phrase":"continuous filtration process","zh":"连续过滤流程"},{"phrase":"the filtration process begins","zh":"过滤流程开始"},{"phrase":"glomerular filtration process","zh":"肾小球滤过过程"},{"phrase":"a filtration process for applications","zh":"申请的筛选流程"}],"forms":[{"label":"单数","form":"filtration process"},{"label":"复数","form":"filtration processes"},{"label":"相关名词","form":"filtration"},{"label":"相关名词","form":"filter"},{"label":"相关名词（滤液）","form":"filtrate"},{"label":"相关动词","form":"filter"}],"derivatives":[{"word":"filtration","pos":"n.","zh":"过滤"},{"word":"filter","pos":"n./v.","zh":"过滤器／过滤"},{"word":"filtrate","pos":"n.","zh":"滤液"},{"word":"processing","pos":"n.","zh":"加工；处理"},{"word":"processor","pos":"n.","zh":"处理器；加工者"}],"senses":[{"no":"01","title":"A sequence that separates solids from fluid","titleCN":"把固体从流体中分离的流程","definition":"the ordered series of steps by which a liquid or gas is passed through a barrier so that solid particles are held back","definitionCN":"让液体或气体通过屏障、使固体颗粒被截留的有序步骤","example":"The filtration process begins when the slurry enters the drum.","exampleCN":"当浆料进入转鼓，过滤流程就开始了。","why":"the phrase joins a process noun to a barrier noun, so it names not one action but the whole route from feed to clear output.","whyCN":"这个短语把「过程」与「屏障」并置，命名的不是单个动作，而是从进料到清水输出的整条路线。"},{"no":"02","title":"The treatment stage at a waterworks","titleCN":"水厂中的过滤工序","definition":"the stage in municipal water treatment in which water percolates through sand or another medium to remove suspended particles","definitionCN":"市政水处理中让水渗过砂层或其他介质以去除悬浮物的阶段","example":"The filtration process removes particles down to five micrometres.","exampleCN":"这套过滤工序能去除小到五微米的颗粒。","why":"a stage in a larger works is itself a process, so the phrase marks both its internal steps and its place in the plant.","whyCN":"大厂中的一道工序本身也是流程，因此这个短语既指其内部步骤，也指它在厂中的位置。"},{"no":"03","title":"A laboratory procedure","titleCN":"实验室中的过滤步骤","definition":"the standard laboratory procedure of pouring a mixture through filter paper and collecting the clear liquid","definitionCN":"把混合物经滤纸倒过、收集清液的实验室标准步骤","example":"The filtration process left a clear filtrate in the flask.","exampleCN":"过滤步骤在烧瓶里留下了清澈的滤液。","why":"the same few moves, poured, waited, collected, become a repeatable procedure with a fixed order.","whyCN":"倒、等、收这几个相同动作构成一个顺序固定的可重复步骤。"},{"no":"04","title":"A continuous industrial run","titleCN":"工业连续过滤流程","definition":"an industrial process in which feed and filtrate flow without stopping, as on a rotary drum or a belt","definitionCN":"进料与滤液不停流动的工业流程，如转鼓或带式过滤","example":"A continuous filtration process runs without stopping the feed.","exampleCN":"连续过滤流程不必停止进料即可运行。","why":"making the steps continuous turns a batch operation into a flow, and the phrase keeps the word process for that flow.","whyCN":"把步骤连起来就把分批操作变成流动，短语仍用 process 指这股流程。"},{"no":"05","title":"The kidney's filtering sequence","titleCN":"肾脏的滤过过程","definition":"the physiological sequence in which blood plasma is forced through a membrane in the kidney while cells and large proteins are retained","definitionCN":"血浆在肾脏被压过膜、细胞与大分子蛋白被留下的生理顺序","example":"The kidney's filtration process handles about a hundred and eighty litres a day.","exampleCN":"肾脏的滤过过程每天处理约一百八十升。","why":"physiology describes an organ as a plant with stages, so the industrial phrase fits the body without strain.","whyCN":"生理学把一个器官描述成有工序的工厂，因此工业短语用在身体上毫无违和。"},{"no":"06","title":"A review that removes unreliable items","titleCN":"筛除不可靠内容的流程","definition":"a staged review by which information, claims or applications are checked and those that fail are removed","definitionCN":"分阶段审查信息、主张或申请，并移除不合格者的流程","example":"The agency described its review as a filtration process for unreliable claims.","exampleCN":"该机构把审查描述为筛除不可靠说法的流程。","why":"once filtering is a process rather than a single pass, review boards can borrow the phrase for their own stages.","whyCN":"一旦过滤被视为多阶段流程而非一次通过，审查机构就能借这个短语描述自己的阶段。"},{"no":"07","title":"Several barriers in series","titleCN":"多级串联的过滤流程","definition":"a process that passes the same fluid through two or more barriers, each catching finer particles than the last","definitionCN":"让同一流体依次通过两道或多道屏障，每道截住比上一道更细的颗粒","example":"The plant uses a two-stage filtration process.","exampleCN":"这座工厂采用两级过滤流程。","why":"stages in series are the clearest proof that filtration is a process: each output becomes the next input.","whyCN":"串联的级数最能证明过滤是一个流程：每一级的输出成为下一级的输入。"},{"no":"08","title":"A mechanism that sorts people or ideas","titleCN":"抽象义：逐层筛选的机制","definition":"used figuratively of an institutional mechanism that removes unusual or unwanted candidates at each stage","definitionCN":"比喻指在每一阶段剔除不寻常或不合需要的候选者的制度机制","example":"Hiring became a filtration process that removed unusual candidates.","exampleCN":"招聘变成一道过滤流程，把不寻常的候选者筛掉了。","why":"the abstract sense keeps the staged structure and replaces particles with people, which shows how strongly the process image shapes institutions.","whyCN":"抽象义保留分级结构，把颗粒换成人，可见「流程」意象对制度的影响之深。"}],"etymology":{"intro":{"en":"The phrase joins filtration, from Medieval Latin filtrum 'felt', to process, from Latin processus 'a going forward', the participle of procedere 'to go forward'. Both parts are old; the compound is modern technical English. Dates are approximate.","cn":"这个短语把出自中世纪拉丁 filtrum「毛毡」的 filtration 与出自拉丁 processus「向前行进」的 process 组合起来，后者是 procedere「向前走」的分词。两部分都古老，组合本身是现代技术英语。年代均为约数。"},"items":[{"era":"MEDIEVAL LATIN FILTRUM","en":"Filtrum meant 'felt' and then 'a felt strainer'; the material gave its name to the barrier and, through filtration, to the whole operation.","cn":"filtrum 先指「毛毡」，再指「毡制滤器」；材料把名字给了屏障，又经 filtration 给了整个操作。"},{"era":"LATIN PROCEDERE","en":"Procedere 'to go forward' joins pro- 'forward' to cedere 'to go', and its participle processus named a advance or a course of events.","cn":"procedere「向前走」由 pro-「向前」加 cedere「走」构成，其分词 processus 命名一次前进或一串事件。"},{"era":"ENGLISH PROCESS","en":"English process, recorded from the fourteenth century, first meant a course or progression and later a series of operations in manufacture.","cn":"英语 process 自十四世纪有记录，初指进程或经过，后指制造中的一系列操作。"},{"era":"TECHNICAL COMPOUND","en":"Nineteenth- and twentieth-century engineering put the two nouns together to name the whole route rather than a single step.","cn":"十九与二十世纪的工程把这两个名词并置，命名整条路线而非单个步骤。"},{"era":"MODERN APPLICATIONS","en":"Water treatment, chemical engineering and medicine each adopted the phrase for their own staged separations, and administration borrowed it for reviewing people.","cn":"水处理、化学工程与医学各自采用这个短语描述自己的分级分离，行政则借它描述对人的审查。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (combination date): no single citation fixes when the two words were first used together, and the Germanic form behind filtrum is a reconstruction.","cn":"来源不确定（组合年代）：没有单一书证能确定这两个词最早何时连用，且 filtrum 背后的日耳曼形式属于重构。"}]},"similar":{"note":{"en":"Group one holds the parts of the phrase and its near relatives; group two holds other named treatment processes that do a similar job.","cn":"第一组是短语的组成部分及其近亲；第二组是做类似工作的其他处理流程名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"filtration","ipa":"/ˌfɪlˈtreɪʃn/","tag":"the process alone","definition":"The separation itself; the full phrase adds the idea of ordered stages.","definitionCN":"分离本身；完整短语加入了有序阶段的意思。"},{"word":"filter","ipa":"/ˈfɪltə/","tag":"the device","definition":"The barrier that performs the separation, not the sequence around it.","definitionCN":"执行分离的屏障，而非围绕它的顺序。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"the general word","definition":"Any course of operations; it needs filtration to say which operation is meant.","definitionCN":"任何一串操作；需要 filtration 来指明是哪一种操作。"},{"word":"proceedings","ipa":"/prəˈsiːdɪŋz/","tag":"same going-forward root","definition":"Recorded events or legal steps, from the same verb; they are a course of events, not a manufacturing route.","definitionCN":"被记录的事件或法律步骤，出自同一动词；是一串事件，不是制造路线。"}]},{"heading":"NEAR MEANING","entries":[{"word":"separation","ipa":"/ˌsepəˈreɪʃn/","tag":"the broad goal","definition":"Any splitting of a mixture; a filtration process is one way to reach it.","definitionCN":"把混合物分开的任何做法；过滤流程是达到它的一种方式。"},{"word":"purification","ipa":"/ˌpjʊərɪfɪˈkeɪʃn/","tag":"the quality goal","definition":"Making something pure; a filtration process may be one stage of purification.","definitionCN":"使某物纯净；过滤流程可能是提纯的一个阶段。"},{"word":"screening","ipa":"/ˈskriːnɪŋ/","tag":"review sense","definition":"Checking people or data against a standard; close to the figurative sense of the phrase.","definitionCN":"按标准检查人或数据；接近该短语的比喻义。"},{"word":"treatment","ipa":"/ˈtriːtmənt/","tag":"the larger plant","definition":"A whole set of operations applied to water or waste; filtration is normally one stage inside it.","definitionCN":"施加于水或废物的一整套操作；过滤通常是其中一级。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Filtrum 'felt' plus processus 'a going forward': a barrier plus a route.","cn":"filtrum「毛毡」加 processus「向前行进」：一道屏障加一条路线。"},{"en":"The phrase names the whole route, while filtration alone names the separation.","cn":"这个短语命名整条路线，单说 filtration 则只命名分离本身。"},{"en":"Fixed phrases mark the stages: two-stage, continuous, water filtration process.","cn":"固定搭配标出阶段：两级、连续、水过滤流程。"},{"en":"Physiology says glomerular filtration process, the kidney's own production line.","cn":"生理学说肾小球滤过过程，即肾脏自己的生产线。"},{"en":"The institutional phrase is a filtration process for applications, where people are the particles.","cn":"制度说法是申请的筛选流程，那里人就是被截住的颗粒。"}],"abstract":[{"en":"Picture water entering at the top of a sand tank and leaving clear at the bottom.","cn":"想象水从砂池顶部进入，从底部清亮地流出。"},{"en":"Picture a queue passing three desks, each sending some people home.","cn":"想象一队人经过三张桌子，每张都让一些人回家。"},{"en":"Picture one sieve above another, each catching finer grains.","cn":"想象一个筛子叠在另一个筛子上，各自截住更细的颗粒。"}]},"examples":[{"en":"The filtration process at the plant is checked every morning before the first sample is taken.","cn":"工厂每天早晨在取样前检查过滤流程。"},{"en":"Engineers shortened the filtration process by adding a second drum.","cn":"工程师增加了一个转鼓，缩短了过滤流程。"},{"en":"The committee turned the grant review into a filtration process with three stages.","cn":"委员会把资助评审变成一道分三阶段的筛选流程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「过滤 + 流程」——从进料到清水的一整套步骤：过滤流程","word":"filtration process"},"root":"filtration（中世纪拉丁 filtrum「毛毡、滤器」）+ process（拉丁 processus「向前行进」，出自 procedere = pro-「向前」+ cedere「走」）。两词并置构成现代技术短语。","sensesIntro":{"en":"Eight senses follow one route: slurry enters a drum, water seeps through a sand bed, a laboratory pours through paper, a plant runs continuously, a kidney filters blood, a board screens claims, barriers stand in series, and finally an institution filters candidates.","cn":"八个义项跟着同一条路线：浆料进入转鼓，水渗过砂床，实验室用滤纸倒过，工厂连续运行，肾脏过滤血液，委员会筛除说法，多道屏障串联，最后是机构筛选候选者。"},"semanticMap":{"core":{"en":"CORE IMAGE: muddy water entering the top of a sand tank and leaving clear at the bottom.","cn":"核心意象：浑水从砂池顶部进入，从底部清亮地流出。"},"chain":["FEED ENTERS","BARRIER HOLDS SOLIDS","CLEAR FLUID LEAVES","STAGES IN SERIES","REVIEW DESK","CANDIDATES FILTERED"],"branches":[{"senses":"01 · 02 · 03","en":"THE ROUTE AT THREE SCALES: a drum, a sand bed and a filter paper all run the same short sequence.","cn":"三个尺度的同一路线：转鼓、砂床与滤纸都在跑同一段短流程。"},{"senses":"04","en":"CONTINUOUS FLOW: feeding and drawing off without stopping turns steps into a stream.","cn":"连续流动：不停进料与出料，把步骤变成一股水流。"},{"senses":"05","en":"THE BODY'S PRODUCTION LINE: a kidney runs the industrial route inside a living body.","cn":"体内的生产线：肾脏在活体内跑着工业路线。"},{"senses":"06 · 08","en":"ADMINISTRATIVE FILTERING: claims and candidates are passed through stages until only acceptable ones remain.","cn":"行政筛选：说法与候选者被送过各阶段，直到只剩可接受者。"},{"senses":"07","en":"SERIES OF BARRIERS: each stage takes the output of the last, which is what makes the sequence a process.","cn":"串联屏障：每一级接过上一级的输出，这才让整串步骤成为流程。"}]},"affixes":{"intro":{"en":"The phrase combines a noun of felt with a noun of going forward, and each half brings its own family.","cn":"这个短语把「毛毡」名词与「向前行进」名词组合起来，两半各自带来一族词。"},"latinIntro":{"en":"Filtrum gives filter and filtration; procedere gives process, proceed, procedure and proceedings.","cn":"filtrum 衍生 filter 与 filtration；procedere 衍生 process、proceed、procedure 与 proceedings。"},"items":[{"word":"filtrum","structure":"filtrum, filtri (n., second declension)","meaning":"felt; strainer","meaningCN":"毛毡；滤器","example":"The first half of the phrase comes from this noun.","exampleCN":"短语的前一半出自这个名词。"},{"word":"filtratio","structure":"filtrare + -io","meaning":"a filtering","meaningCN":"过滤","example":"Filtration names the separation.","exampleCN":"filtration 命名分离本身。"},{"word":"pro-","structure":"pro- (Latin prefix, 'forward')","meaning":"forward","meaningCN":"向前","example":"The prefix gives the direction of the course.","exampleCN":"这个前缀给出进程的方向。"},{"word":"cedere","structure":"cedere (Latin verb, 'to go')","meaning":"to go","meaningCN":"走","example":"The root supplies the movement.","exampleCN":"这个词根提供移动。"},{"word":"procedere","structure":"pro- + cedere","meaning":"to go forward","meaningCN":"向前走","example":"The verb begins the process family.","exampleCN":"这个动词开启 process 词族。"},{"word":"processus","structure":"procedere + -tus (noun of action)","meaning":"a going forward, a course","meaningCN":"前进；进程","example":"The noun became English process.","exampleCN":"这个名词成为英语 process。"},{"word":"process","structure":"processus -> process","meaning":"a course of operations","meaningCN":"一串操作；流程","example":"The process takes four hours.","exampleCN":"这个流程要四小时。"},{"word":"proceed","structure":"procedere -> proceed","meaning":"to go on","meaningCN":"继续进行","example":"The work proceeds in stages.","exampleCN":"这项工作分阶段进行。"},{"word":"procedure","structure":"procedere + -ura","meaning":"a fixed way of doing something","meaningCN":"程序；步骤","example":"The procedure is written on the wall.","exampleCN":"程序写在墙上。"},{"word":"processing","structure":"process + -ing","meaning":"the handling of material","meaningCN":"加工；处理","example":"Processing begins at dawn.","exampleCN":"加工在黎明开始。"}],"latinEntries":[{"word":"filtrum","structure":"filtrum, filtri (n., second declension)","meaning":"felt; strainer","meaningCN":"毛毡；滤器"},{"word":"filtratio","structure":"filtratio, filtrationis (f., third declension)","meaning":"a filtering","meaningCN":"过滤"},{"word":"procedere","structure":"procedere, processi, processum (verb, third conjugation)","meaning":"to go forward","meaningCN":"向前走"},{"word":"processus","structure":"processus, processus (m., fourth declension)","meaning":"a going forward, a course","meaningCN":"前进；进程"}]}},{"word":"chromatography","ipa_uk":"/ˌkrəʊməˈtɒɡrəfi/","ipa_us":"/ˌkroʊməˈtɑːɡrəfi/","definition_zh":"色谱法；色谱分析","definition_en":"a laboratory method that separates the components of a mixture by passing it through a medium in which the components move at different rates","core_image":"一滴墨点在滤纸条下端，水慢慢爬上去，墨散成几道不同颜色的带","scene":"课堂上，学生把一滴墨点在滤纸条下端，水沿纸面慢慢上升，墨迹散成几道颜色不同的带。Chromatography separated the ink into its component dyes.","sceneCN":"这里 chromatography 指利用各组分移动速度不同而分离混合物的方法（第 1 个义项：色谱法）；句意为色谱法把墨水分离成几种染料成分。图中可辨识物件：滤纸条、墨点、水槽、颜色分层。","pos":[{"tag":"n.","zh":"色谱法；色谱分析（不可数）"},{"tag":"n.","zh":"色谱分离操作（可数，少见）"}],"collocations":[{"phrase":"gas chromatography","zh":"气相色谱"},{"phrase":"liquid chromatography","zh":"液相色谱"},{"phrase":"paper chromatography","zh":"纸色谱"},{"phrase":"thin-layer chromatography","zh":"薄层色谱"},{"phrase":"chromatography column","zh":"色谱柱"},{"phrase":"analyse by chromatography","zh":"用色谱法分析"}],"forms":[{"label":"不可数名词","form":"chromatography"},{"label":"仪器名词","form":"chromatograph"},{"label":"结果名词（色谱图）","form":"chromatogram"},{"label":"形容词","form":"chromatographic"},{"label":"副词","form":"chromatographically"},{"label":"从业者名词","form":"chromatographer"}],"derivatives":[{"word":"chromatograph","pos":"n.","zh":"色谱仪"},{"word":"chromatogram","pos":"n.","zh":"色谱图"},{"word":"chromatographic","pos":"adj.","zh":"色谱的"},{"word":"chromatographically","pos":"adv.","zh":"用色谱法"},{"word":"chromatographer","pos":"n.","zh":"色谱分析人员"}],"senses":[{"no":"01","title":"Separation by different rates of movement","titleCN":"按不同移动速度分离混合物的方法","definition":"a method in which a mixture is carried through a stationary medium so that its components separate because they travel at different speeds","definitionCN":"让混合物通过固定介质，各组分因移动速度不同而分开的方法","example":"Chromatography separates the pigments in a leaf extract.","exampleCN":"色谱法把叶片提取液中的色素分开。","why":"the word joins Greek khrōma 'colour' to graphein 'to write', because the first separations wrote coloured bands onto paper.","whyCN":"这个词把希腊 khrōma「颜色」与 graphein「写」连起来，因为最早的分离把彩色色带「写」在纸上。"},{"no":"02","title":"A paper or thin-layer method","titleCN":"纸色谱或薄层色谱","definition":"a simple form of the method in which a solvent climbs a paper or a coated plate and leaves separated spots behind","definitionCN":"一种简单形式：溶剂沿纸或涂层板爬升，留下分开的斑点","example":"Paper chromatography showed two distinct spots.","exampleCN":"纸色谱显示出两个清晰的斑点。","why":"the general method is named after its simplest visible form, where a coloured spot literally climbs a sheet of paper.","whyCN":"这个总称来自它最简单、可见的形式：一个有色斑点真的沿纸面往上爬。"},{"no":"03","title":"Gas chromatography","titleCN":"气相色谱","definition":"a form of the method in which a vaporized sample is carried by a gas through a column","definitionCN":"把汽化样品用气体载过色谱柱的一种形式","example":"Gas chromatography identified the volatile compounds.","exampleCN":"气相色谱鉴定出了挥发性化合物。","why":"the carrier can be a gas as easily as a liquid, and the name stays the same because the separating principle is unchanged.","whyCN":"载流可以是气体也可以是液体，名称不变，因为分离原理没变。"},{"no":"04","title":"Liquid chromatography","titleCN":"液相色谱","definition":"a form of the method in which a liquid carries the sample through a packed column","definitionCN":"用液体把样品载过填充柱的一种形式","example":"Liquid chromatography is standard for drug analysis.","exampleCN":"液相色谱是药物分析的标准方法。","why":"liquids were the first carriers, and the modern high-pressure version keeps the old name.","whyCN":"液体是最早的载流，现代高压版本也沿用旧名。"},{"no":"05","title":"One run and its recorded trace","titleCN":"一次色谱分离及其记录曲线","definition":"a single separation run and the pattern of peaks or spots that records where each component ended up","definitionCN":"一次分离运行，以及记录各组分最终位置的峰形或斑点","example":"The chromatography produced three peaks.","exampleCN":"这次色谱分离产生了三个峰。","why":"a method that can be run repeatedly becomes a countable operation, and the trace makes the result visible.","whyCN":"可反复运行的方法成为可数操作，而记录曲线让结果可见。"},{"no":"06","title":"An identification technique","titleCN":"用于鉴定与定量的分析技术","definition":"the technique used to identify a substance or measure how much of it is present by comparing its position or peak","definitionCN":"通过比较位置或峰来鉴定物质、测量其含量的技术","example":"Forensic labs rely on chromatography to identify traces.","exampleCN":"法医实验室依靠色谱法鉴定微量痕迹。","why":"separation alone only divides; comparison against known standards turns the division into identification.","whyCN":"分离本身只是分开；与已知标准比较，才把分开变成鉴定。"},{"no":"07","title":"A classroom separation of colours","titleCN":"课堂上分离色素的实验","definition":"the school experiment in which ink or leaf pigment is separated into visible coloured bands","definitionCN":"把墨水或叶片色素分成可见色带的课堂实验","example":"The students used chromatography to separate ink colours.","exampleCN":"学生们用色谱法分离墨水的颜色。","why":"the original demonstration was also a lesson, so the word keeps a place in teaching long after the instruments grew complex.","whyCN":"最初的演示本身也是一堂课，因此仪器变复杂很久之后，这个词仍在教学里占一席。"},{"no":"08","title":"Sorting a mixed whole by affinity","titleCN":"抽象义：按亲和差异把混杂整体分开","definition":"used figuratively of any process that lets the parts of a mixed whole reveal themselves at different speeds or affinities","definitionCN":"比喻指让混杂整体的各部分按不同速度或亲和力自行显现的过程","example":"The committee's chromatography of proposals separated the serious from the decorative.","exampleCN":"委员会对提案的「色谱分离」，把认真的与装饰性的分开了。","why":"the abstract sense keeps the geometry of a column: what sticks travels slowly, what does not sticks goes ahead.","whyCN":"抽象义保留色谱柱的几何：附着得牢的走得慢，不附着的先走。"}],"etymology":{"intro":{"en":"Chromatography was coined in 1906 by the Russian botanist Mikhail Tsvet from Greek khrōma 'colour' and graphein 'to write', for his method of separating plant pigments on paper. Dates are approximate.","cn":"chromatography 由俄国植物学家米哈伊尔·茨维特于一九〇六年用希腊 khrōma「颜色」与 graphein「写」造出，指他在纸上分离植物色素的方法。年代均为约数。"},"items":[{"era":"GREEK KHRŌMA","en":"Khrōma meant 'colour, skin, surface', with the stem khrōmat-; it also names the colour of a thing as opposed to its substance.","cn":"khrōma 意为「颜色、皮肤、表面」，词干为 khrōmat-；它指事物的颜色，与其实体相对。"},{"era":"GREEK GRAPHEIN","en":"Graphein meant 'to write, draw, record', and its combining form -graphia names a way of writing or recording.","cn":"graphein 意为「写、画、记录」，其组合形式 -graphia 命名一种书写或记录方式。"},{"era":"COINED 1906","en":"Tsvet combined the two elements to name a method that wrote coloured bands onto paper while separating leaf pigments.","cn":"茨维特把这两个成分组合起来，命名一种在纸上「写出」彩色色带、从而分离叶片色素的方法。"},{"era":"ENGLISH USE","en":"English adopted the term in the early twentieth century, at first for the paper method and then for any separation by differing rates.","cn":"英语在二十世纪初采用这个术语，先指纸上方法，后指任何按不同速度进行的分离。"},{"era":"INSTRUMENTAL FORMS","en":"From the mid-twentieth century gas and liquid versions turned the word into a family of techniques with columns, detectors and recorded peaks.","cn":"二十世纪中叶起，气相与液相版本把这个词变成一族技术，配有色谱柱、检测器与记录峰。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first publication): accounts differ between 1903 and 1906 for the first published description, so the earlier date is not treated as fixed.","cn":"来源不确定（首次发表）：关于最早发表描述的时间，有资料记作一九〇三年，也有记作一九〇六年，因此较早的年份不作为定论。"}]},"similar":{"note":{"en":"Group one holds the instrument, the trace and the words built on the same Greek elements; group two holds other separation techniques used beside it.","cn":"第一组是仪器、记录图以及用同一希腊成分构成的词；第二组是常与它并用的其他分离技术。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chromatograph","ipa":"/krəˈmætəɡrɑːf/","tag":"the machine","definition":"The instrument that performs the separation; chromatography is the method.","definitionCN":"执行分离的仪器；chromatography 是方法。"},{"word":"chromatogram","ipa":"/krəˈmætəɡræm/","tag":"the record","definition":"The printed trace of peaks produced by a run; it is the result, not the method.","definitionCN":"一次运行产生的峰形记录；是结果，不是方法。"},{"word":"chromium","ipa":"/ˈkrəʊmiəm/","tag":"same colour root, an element","definition":"The metal named for its brightly coloured compounds; it shares khrōma but has nothing to do with separation.","definitionCN":"因化合物色彩鲜艳而得名的金属；共享 khrōma，但与分离无关。"},{"word":"chromosome","ipa":"/ˈkrəʊməsəʊm/","tag":"colour plus body","definition":"Khrōma plus sōma 'body': the stained bodies seen in a cell nucleus, named for how they take dye.","definitionCN":"khrōma 加 sōma「体」：细胞核中被染色的体，因摄取染料而得名。"}]},{"heading":"NEAR MEANING","entries":[{"word":"electrophoresis","ipa":"/ɪˌlektrəfəˈriːsɪs/","tag":"separates by charge","definition":"Separation of charged molecules in an electric field; it is used beside chromatography for proteins and DNA.","definitionCN":"在电场中分离带电分子；常与色谱法并用于蛋白质与脱氧核糖核酸的分析。"},{"word":"spectroscopy","ipa":"/spekˈtrɒskəpi/","tag":"identifies by light","definition":"Identification of substances by the light they absorb or emit; it can confirm what chromatography separated.","definitionCN":"通过吸收或发射的光鉴定物质；可确认色谱法分出的东西。"},{"word":"centrifugation","ipa":"/ˌsentrɪfjʊˈɡeɪʃn/","tag":"separates by mass","definition":"Separation by spinning, which pulls heavier parts outward; it sorts by density rather than affinity.","definitionCN":"通过旋转分离，把较重的部分甩向外侧；按密度而非亲和力分选。"},{"word":"filtration","ipa":"/ˌfɪlˈtreɪʃn/","tag":"separates by size","definition":"Separation by a barrier that holds back particles; it removes solids but does not divide dissolved components.","definitionCN":"用屏障截留颗粒的分离；能去除固体，但不分开已溶解的组分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Khrōma 'colour' plus graphein 'write': colour written onto paper.","cn":"khrōma「颜色」加 graphein「写」：把颜色写在纸上。"},{"en":"The family runs chromatography, chromatograph, chromatogram, chromatographic.","cn":"同族词包括 chromatography、chromatograph、chromatogram、chromatographic。"},{"en":"Fixed phrases mark the forms: gas chromatography, liquid chromatography, paper chromatography.","cn":"固定搭配标出形式：气相色谱、液相色谱、纸色谱。"},{"en":"The colour root also appears in chromium and chromosome, which share the name but not the method.","cn":"颜色词根也出现在 chromium 与 chromosome 中，共享名称而不共享方法。"},{"en":"The method depends on one rule: what sticks travels slowly, what does not sticks races ahead.","cn":"这个方法只依赖一条规则：附着得牢的走得慢，不附着的跑在前。"}],"abstract":[{"en":"Picture a drop of ink climbing paper and breaking into bands of colour.","cn":"想象一滴墨沿纸面爬升，裂成几道色带。"},{"en":"Picture runners on a track, some held back by mud and some free.","cn":"想象跑道上的选手，有些被泥拖住，有些不受阻。"},{"en":"Picture a crowd leaving a hall, the fastest out first and the slowest still talking.","cn":"想象人群离开大厅，最快的先出去，最慢的还在说话。"}]},"examples":[{"en":"Chromatography is used to test athletes for banned substances.","cn":"色谱法被用来检测运动员体内的违禁物质。"},{"en":"The lab ran the sample through gas chromatography and compared the peaks.","cn":"实验室让样品通过气相色谱，并比较峰形。"},{"en":"Students separated the colours of a marker pen by chromatography.","cn":"学生们用色谱法分离了记号笔的颜色。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chroma（颜色）+ graphy（写）」——把颜色写成一条条色带：色谱法","word":"chromatography"},"root":"希腊 khrōma（颜色，词干 khrōmat-）+ graphein（写）+ -ia（方法名词）；一九〇六年由茨维特为纸上分离植物色素的方法造出，早期发表年份有存疑。","sensesIntro":{"en":"Eight senses follow one separation: components travel at different rates, a paper version makes that visible, gas and liquid carriers do the same, a run leaves a trace, the trace identifies a substance, a classroom shows it with ink, and finally any mixed whole can be sorted by affinity.","cn":"八个义项跟着同一次分离：各组分以不同速度前行，纸上版本让它可见，气体与液体载流做同样的事，一次运行留下记录，记录能鉴定物质，课堂上用墨水演示，最后任何混杂整体都能按亲和力分选。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drop of ink on paper breaking into coloured bands as the solvent climbs.","cn":"核心意象：纸上的一滴墨，随溶剂爬升裂成几道彩色带。"},"chain":["MIXTURE INTRODUCED","SOLVENT CARRIES IT","COMPONENTS SEPARATE","TRACE RECORDED","SUBSTANCE IDENTIFIED","MIXED WHOLE SORTED"],"branches":[{"senses":"01 · 02","en":"THE PRINCIPLE AND ITS SIMPLEST DEMO: different speeds separate the mixture, and paper makes that visible.","cn":"原理与最简单的演示：不同速度分开混合物，纸让它看得见。"},{"senses":"03 · 04","en":"CARRIERS: gas and liquid are two ways of moving the sample, not two different principles.","cn":"载流：气体与液体是两种运送样品的方式，不是两套原理。"},{"senses":"05","en":"THE RECORD: one run and its trace turn a separation into evidence.","cn":"记录：一次运行及其曲线，把分离变成证据。"},{"senses":"06 · 07","en":"IDENTIFICATION AND TEACHING: comparison names the substance, and the school version keeps the method visible.","cn":"鉴定与教学：比较给出名称，课堂版本让方法保持可见。"},{"senses":"08","en":"SORTING A WHOLE: what sticks to the medium travels slowly, which is a way to read any mixed body.","cn":"分选整体：附着于介质的走得慢，这可以用来解读任何混杂体。"}]},"affixes":{"intro":{"en":"Chromatography is a modern compound of two Greek elements, and each element also builds many scientific words.","cn":"chromatography 是由两个希腊成分构成的现代复合词，每个成分也构成许多科学词。"},"latinIntro":{"en":"Greek khrōma 'colour' gives chromium, chromosome and chromatid; graphein 'to write' gives -graphy, graph, diagram and photograph.","cn":"希腊 khrōma「颜色」构成 chromium、chromosome 与 chromatid；graphein「写」构成 -graphy、graph、diagram 与 photograph。"},"items":[{"word":"khrōma","structure":"khrōma, khrōmatos (Greek noun, 'colour')","meaning":"colour","meaningCN":"颜色","example":"The element names the coloured bands.","exampleCN":"这个成分命名彩色色带。"},{"word":"graphein","structure":"graphein (Greek verb, 'to write')","meaning":"to write","meaningCN":"写","example":"The element names the recording.","exampleCN":"这个成分命名记录。"},{"word":"-graphy","structure":"-graphia (Greek suffix, 'writing, recording')","meaning":"a way of writing or recording","meaningCN":"书写或记录的方式","example":"The suffix makes chromatography a method.","exampleCN":"这个后缀让 chromatography 成为一种方法。"},{"word":"chromatograph","structure":"khrōma + graphein + -graph (instrument)","meaning":"the instrument","meaningCN":"色谱仪","example":"The chromatograph was calibrated.","exampleCN":"色谱仪被校准了。"},{"word":"chromatogram","structure":"khrōma + gramma (something written)","meaning":"the recorded trace","meaningCN":"色谱图","example":"The chromatogram showed four peaks.","exampleCN":"色谱图显示四个峰。"},{"word":"chromatography","structure":"khrōma + graphein + -ia","meaning":"the method","meaningCN":"色谱法","example":"Chromatography separated the dyes.","exampleCN":"色谱法把染料分开。"},{"word":"chromatographic","structure":"chromatography + -ic (adjective)","meaning":"relating to chromatography","meaningCN":"色谱的","example":"The chromatographic data were compared.","exampleCN":"色谱数据被比较。"},{"word":"chromatographically","structure":"chromatographic + -ally (adverb)","meaning":"by means of chromatography","meaningCN":"用色谱法","example":"The sample was analysed chromatographically.","exampleCN":"样品用色谱法进行了分析。"},{"word":"chromium","structure":"khrōma + -ium (element suffix)","meaning":"a metal with coloured compounds","meaningCN":"化合物有色的金属","example":"Chromium gives glass a green tint.","exampleCN":"铬使玻璃带绿色。"},{"word":"chromosome","structure":"khrōma + sōma (body)","meaning":"a stainable body in the nucleus","meaningCN":"细胞核中可被染色的体","example":"The chromosome was stained for viewing.","exampleCN":"染色体被染色以便观察。"}],"latinEntries":[{"word":"khrōma","structure":"khrōma, khrōmatos (n., Greek third declension)","meaning":"colour","meaningCN":"颜色"},{"word":"graphein","structure":"graphein (Greek verb)","meaning":"to write","meaningCN":"写"},{"word":"gramma","structure":"gramma, grammatos (n., Greek third declension)","meaning":"something written","meaningCN":"写下的东西"},{"word":"sōma","structure":"sōma, sōmatos (n., Greek third declension)","meaning":"body","meaningCN":"身体；体"}]}}]);
